"""Helpers for the data commands: if/in, vectorized evaluation,
per-observation context (for sequential replace) and messages."""

from __future__ import annotations

from typing import TYPE_CHECKING, Any

import numpy as np

from ..core import missing as M
from ..core.errors import StataError
from ..lang import functions as F
from ..lang.expr import Node, Name, Subscript, Unary, Binary, Call, parse
from ..lang.syntax import Parsed, parse_in
from ..lang.vexpr import Groups, VectorContext, broadcast, evaluate_vec, is_str, truth

if TYPE_CHECKING:
    from ..session import Session


def groups(s: "Session") -> Groups:
    return s.by_groups if s.by_groups is not None else Groups.single(s.data.nobs)


def _count_random(node) -> int:
    from ..core.rng import DISTRIBUTIONS
    if isinstance(node, Call):
        own = 1 if node.name in DISTRIBUTIONS else 0
        return own + sum(_count_random(a) for a in node.args)
    if isinstance(node, Unary):
        return _count_random(node.operand)
    if isinstance(node, Binary):
        return _count_random(node.left) + _count_random(node.right)
    if isinstance(node, Subscript):
        return 0 if isinstance(node.index, str) else _count_random(node.index)
    return 0


def eval_vector(s: "Session", text: str) -> Any:
    node = parse(text)
    k = _count_random(node)
    if k >= 2:
        # Stata evaluates the expression observation by observation: with several random functions,
        # the draws interleave (obs 1: 1st and 2nd call; obs 2: 1st and 2nd...). Draw the block
        # first and distribute it.
        from ..core import rng
        mask = getattr(s, "_rng_mask", None)
        n = s.data.nobs
        m = int(mask.sum()) if mask is not None and len(mask) == n else n
        s._rng_block = [rng.RNG.uniform(m * k).reshape(m, k), 0]
        try:
            return evaluate_vec(node, VectorContext(s, groups(s)))
        finally:
            s._rng_block = None
    return evaluate_vec(node, VectorContext(s, groups(s)))


def eval_sample(s: "Session", text: str, mask: np.ndarray) -> Any:
    """Like eval_vector, but random functions only draw for the
    observations in the sample (if/in), in their order, as Stata does: so
    `gen u = runiform() if x` consumes the same sequence as in Stata."""
    s._rng_mask = mask
    try:
        return eval_vector(s, text)
    finally:
        s._rng_mask = None


def touse(s: "Session", p: Parsed) -> np.ndarray:
    n = s.data.nobs
    mask = np.ones(n, dtype=bool)
    if p.in_:
        a, b = parse_in(p.in_, n)
        inmask = np.zeros(n, dtype=bool)
        inmask[a:b] = True
        mask &= inmask
    if p.if_:
        v = eval_vector(s, p.if_)
        t = truth(v)
        mask &= np.asarray(broadcast(t, n) if not isinstance(t, np.ndarray) else t, dtype=bool)
    return mask


def plural(n: int, word: str, plural_word: str | None = None) -> str:
    return f"{n:,} {word if n == 1 else (plural_word or word + 's')}"


def references_subscript(node: Node, name: str) -> bool:
    """Does the expression use name[...] or a time-series operator on name (L.name, D.name...)?
    replace then has to be sequential: Stata replaces observation by observation, so
    replace y = 2*L.y uses the values already replaced."""
    if isinstance(node, Name):
        return "." in node.name and node.name.rsplit(".", 1)[1] == name
    if isinstance(node, Subscript):
        return node.name == name or (not isinstance(node.index, str) and references_subscript(node.index, name))
    if isinstance(node, Unary):
        return references_subscript(node.operand, name)
    if isinstance(node, Binary):
        return references_subscript(node.left, name) or references_subscript(node.right, name)
    if isinstance(node, Call):
        return any(references_subscript(a, name) for a in node.args)
    return False


class ObsContext:
    """Scalar context positioned at one observation (sequential replace)."""

    def __init__(self, s: "Session", g: Groups):
        self.s = s
        self.g = g
        self.i = 0

    def resolve_name(self, name: str) -> Any:
        ds = self.s.data
        if ds.has(name):
            return ds.get(name).value(self.i)
        if "." in name:
            return self._ts_value(name)
        if name in self.s.scalars:
            return self.s.scalars[name]
        if name == "_n":
            return float(self.g.pos[self.i] + 1)
        if name == "_N":
            return float(self.g.size[self.i])
        return self.s.context.resolve_name(name)

    def _ts_value(self, name: str) -> Any:
        """L.y, D.y, S12.y... at the current observation, from the current values: the
        operators are a polynomial in the lag operator (D = 1 - L, S#= 1 - L#, F# = L-#)."""
        cache = self.__dict__.setdefault("_ts_cache", {})
        hit = cache.get(name)
        ds = self.s.data
        if hit is None:
            from ..estimation.fvars import _component_alts
            from ..estimation.tsops import _TSIndex, require_ts
            comps = _component_alts(ds, name, False)
            if not comps or len(comps) != 1 or not comps[0].ts:
                return self.s.context.resolve_name(name)
            poly = {0: 1.0}
            for op, k in comps[0].ts:
                terms = {"L": {k: 1.0}, "F": {-k: 1.0}, "S": {0: 1.0, k: -1.0}}.get(op)
                reps = 1
                if op == "D":
                    terms, reps = {0: 1.0, 1: -1.0}, k
                if terms is None:
                    raise StataError(198, f"{op}: unknown operator")
                for _ in range(reps):
                    new: dict[int, float] = {}
                    for a, ca in poly.items():
                        for b, cb in terms.items():
                            new[a + b] = new.get(a + b, 0.0) + ca * cb
                    poly = {o: c for o, c in new.items() if c != 0}
            info = require_ts(ds)
            index = _TSIndex(ds, info)
            srcs = {o: (index.source(o * info.delta) if o else None) for o in poly}
            hit = cache[name] = (comps[0].var, poly, srcs)
        var_name, poly, srcs = hit
        var = ds.get(var_name)
        total = 0.0
        for o, c in poly.items():
            j = self.i if srcs[o] is None else int(srcs[o][self.i])
            if j < 0:
                return M.SYSMISS
            v = var.value(j)
            if M.is_missing(v):
                return M.SYSMISS
            total += c * float(v)
        return total

    def resolve_subscript(self, name: str, index: Any) -> Any:
        ds = self.s.data
        if not ds.has(name):
            return self.s.context.resolve_subscript(name, index)
        var = ds.get(name)
        if isinstance(index, str):
            raise StataError(109, "type mismatch")
        k = int(index) if not M.is_missing(index) else 0
        if 1 <= k <= self.g.size[self.i]:
            return var.value(self.g.start[self.i] + k - 1)
        return "" if var.is_string else M.SYSMISS

    def resolve_result(self, kind: str, raw: str) -> Any:
        return self.s.context.resolve_result(kind, raw)

    def call_function(self, name: str, args: list[Any]) -> Any:
        return F.call(name, args)


def check_kind(value: Any, want_string: bool) -> None:
    if is_str(value) != want_string:
        raise StataError(109, "type mismatch")

