"""import excel and export excel ([D] import excel).

Messages and undocumented rules are marked VERIFY, with cases in
compat/do/0106_excel.do.
"""

from __future__ import annotations

from pathlib import Path
from typing import TYPE_CHECKING

import numpy as np

from ..core.errors import StataError
from ..core.varlist import expand, unique
from ..io.excel import ExcelOptions, ExcelWriteOptions, describe_excel, read_excel, write_excel
from ..lang.syntax import Parsed, match_options, parse_standard
from ..lang.words import strip_outer_quotes
from ._util import touse

if TYPE_CHECKING:
    from ..session import Session


def excel_path(text: str, *, must_exist: bool) -> Path:
    t = strip_outer_quotes(text.strip())
    if not t:
        raise StataError(198, "invalid file specification")
    p = Path(t).expanduser()
    if p.suffix == "":
        # VERIFY: default extension (Stata 14 uses .xls; OpenDTA writes .xlsx)
        candidates = [p.with_suffix(".xlsx"), p.with_suffix(".xls")]
        if must_exist:
            for c in candidates:
                if c.exists():
                    return c
        return candidates[0]
    return p


def _sheet_arg(arg: str) -> tuple[str, str]:
    """'"Plan 1", modify' -> ('Plan 1', 'modify')."""
    text = arg.strip()
    mode = ""
    if text.startswith('"'):
        end = text.find('"', 1)
        name, rest = text[1:end], text[end + 1:]
    else:
        name, _, rest = text.partition(",")
        name = name.strip()
        rest = "," + rest if _ else ""
    rest = rest.strip().lstrip(",").strip()
    if rest:
        if rest not in ("modify", "replace"):
            raise StataError(198, f"option sheet() invalid: {rest}")
        mode = rest
    return name, mode


def import_excel(s: "Session", args: str) -> None:
    p = parse_standard(args)
    if p.using is not None:
        file = p.using       # varlist before using (columns): VERIFY, still ignored
    else:
        file = p.varlist
    o = match_options(p.options, {"sheet": 5, "cellrange": 9, "firstrow": 8, "case": 4,
                                  "allstring": 9, "clear": 5, "describe": 8, "locale": 6})
    path = excel_path(file, must_exist=True)
    if not path.exists():
        raise StataError(601, f"file {path} not found")
    if o.get("describe"):
        rows = describe_excel(path)
        out = s.output
        width = max([len(n) + 4 for n, _ in rows] + [10])
        out.write(f"\n{'Sheet':>{width}} | Range\n", "text")
        out.write(f"  {'-' * (width - 1)}+{'-' * 9}\n", "text")
        for name, rng in rows:
            out.write(f"{name:>{width}} | {rng}\n", "text")
        # written from last to first: return list shows worksheet_1 first
        s.r = {}
        for k, (name, rng) in reversed(list(enumerate(rows, start=1))):
            s.r[f"range_{k}"] = rng
            s.r[f"worksheet_{k}"] = name
        s.r["N_worksheet"] = float(len(rows))
        return
    ds = s.data
    if ds.changed and ds.nvars and not o.get("clear"):
        raise StataError(4, "no; data in memory would be lost")
    opts = ExcelOptions()
    if o.get("sheet"):
        opts.sheet = strip_outer_quotes(str(o["sheet"]).strip())
    if o.get("cellrange"):
        opts.cellrange = str(o["cellrange"]).strip()
    opts.firstrow = bool(o.get("firstrow"))
    if o.get("case"):
        c = str(o["case"]).strip()
        if c not in ("preserve", "lower", "upper"):
            raise StataError(198, "option case() invalid")
        opts.case = c
    opts.allstring = bool(o.get("allstring"))
    new = read_excel(path, opts)
    s.data = new
    s.notify_state()


def export_excel(s: "Session", args: str) -> None:
    p = parse_standard(args)
    if p.using is not None:
        names_text, file = p.varlist, p.using
    else:
        names_text, file = "", p.varlist
    o = match_options(p.options, {"sheet": 5, "cell": 4, "firstrow": 8, "nolabel": 5,
                                  "replace": 7, "sheetmodify": 11, "sheetreplace": 12,
                                  "datestring": 10, "missing": 7, "locale": 6})
    ds = s.data
    if ds.nvars == 0:
        raise StataError(102, "no variables defined")   # VERIFY
    names = unique(expand(ds, names_text)) if names_text.strip() else list(ds.names)
    path = excel_path(file, must_exist=False)
    opts = ExcelWriteOptions()
    sheet_mode = ""
    if o.get("sheet"):
        opts.sheet, sheet_mode = _sheet_arg(str(o["sheet"]))
    if o.get("cell"):
        opts.cell = str(o["cell"]).strip()
    if o.get("firstrow"):
        fr = str(o["firstrow"]).strip()
        if fr not in ("variables", "varlabels"):
            raise StataError(198, "option firstrow() must be variables or varlabels")
        opts.firstrow = fr
    opts.nolabel = bool(o.get("nolabel"))
    if o.get("sheetmodify") or sheet_mode == "modify":
        opts.mode = "modify"
    elif o.get("sheetreplace") or sheet_mode == "replace":
        opts.mode = "sheetreplace"
    elif o.get("replace"):
        opts.mode = "replace"
    if path.exists() and opts.mode == "new":
        raise StataError(602, f"file {path} already exists")
    rows = np.flatnonzero(touse(s, Parsed(if_=p.if_, in_=p.in_)))
    try:
        write_excel(ds, path, names, rows, opts)
    except OSError as e:
        raise StataError(603, f"file {path} could not be opened ({e.strerror})")
    s.output.write(f"file {path} saved\n", "text")

files.opendta/commands/filecmd.py:
"""file open/write/read/close ([P] file), the basics to read and write text.

Binary files (file open ..., binary; formats in core/binfmt.py) support file read, file write,
file seek and file set byteorder; file query counts the open files.

file write directives: "text", `"text"', (expression), %fmt (expression),
_newline[(#)] (_n), _tab[(#)], _skip[(#)], _char(#), _dup(#).
"""

from __future__ import annotations

import re
from pathlib import Path
from typing import TYPE_CHECKING

from ..core import binfmt
from ..core.errors import StataError
from ..core.formats import DISPLAY_NUMERIC, format_value, parse_format
from ..lang.syntax import match_options
from ..lang.words import strip_outer_quotes
from .display import _literal
from .registry import command

if TYPE_CHECKING:
    from ..session import Session

_DIR = re.compile(r"_(newline|n|tab|skip|char|dup)\b(\s*\(\s*([^)]*)\s*\))?")
_FMT = re.compile(r"%-?~?0?\d*(\.\d+)?[a-zA-Z]+c?")


class Handle:
    def __init__(self, path: Path, mode: str, fh, binary: bool = False):
        self.path = path
        self.mode = mode          # "r", "w" or "rw"
        self.fh = fh
        self.binary = binary
        self.byteorder = binfmt.NATIVE_ORDER


def _handles(s: "Session") -> dict[str, Handle]:
    if not hasattr(s, "file_handles"):
        s.file_handles = {}
    return s.file_handles


def _get(s: "Session", name: str) -> Handle:
    h = _handles(s).get(name)
    if h is None:
        raise StataError(603, f"file handle {name} not found")   # VERIFY
    return h


def _open(s: "Session", rest: str) -> None:
    head, comma, opts_text = rest.partition(",")
    m = re.match(r"\s*([A-Za-z_][A-Za-z0-9_]*)\s+using\s+(.+)$", head.strip())
    if not m:
        raise StataError(198, "invalid syntax")
    name, file = m.group(1), strip_outer_quotes(m.group(2).strip())
    o = match_options(opts_text, {"read": 1, "write": 1, "text": 1, "binary": 1,
                                  "replace": 3, "append": 3, "all": 3}) if comma else {}
    if name in _handles(s):
        raise StataError(110, f"file handle {name} already exists")   # VERIFY
    path = Path(file).expanduser()
    binary = bool(o.get("binary"))
    if o.get("read") and o.get("write"):
        # read write: opens an existing file or creates a new one, positioned at the top
        fh = open(path, "r+b" if path.exists() else "w+b") if binary else \
            open(path, "r+" if path.exists() else "w+", encoding="utf-8", newline="")
        mode = "rw"
    elif o.get("write"):
        if path.exists() and not (o.get("replace") or o.get("append")):
            raise StataError(602, f"file {file} already exists")
        if o.get("replace") and not path.exists():
            s.output.write(f"(note: file {file} not found)\n", "text")
        mode = "a" if o.get("append") else "w"
        fh = open(path, mode + "b") if binary else open(path, mode, encoding="utf-8", newline="")
        mode = "w"
    elif o.get("read"):
        if not path.exists():
            raise StataError(601, f"file {file} not found")
        fh = open(path, "rb") if binary else open(path, "r", encoding="utf-8", errors="replace", newline="")
        mode = "r"
    else:
        raise StataError(198, "option read or write required")
    _handles(s)[name] = Handle(path, mode, fh, binary)


def _write(s: "Session", rest: str) -> None:
    m = re.match(r"\s*([A-Za-z_][A-Za-z0-9_]*)\s*(.*)$", rest, re.S)
    if not m:
        raise StataError(198, "invalid syntax")
    h = _get(s, m.group(1))
    if h.mode == "r":
        raise StataError(608, f"file {h.path} is read-only")   # VERIFY
    if h.binary:
        _write_binary(s, h, m.group(2))
        return
    text = m.group(2)
    out: list[str] = []
    fmt = None
    dup = 1
    i, n = 0, len(text)
    while i < n:
        while i < n and text[i] in " \t":
            i += 1
        if i >= n:
            break
        rest_ = text[i:]
        d = _DIR.match(rest_)
        if d:
            kind, arg = d.group(1), d.group(3)
            num = int(s.eval(arg)) if arg and arg.strip() else None
            i += d.end()
            if kind in ("newline", "n"):
                out.append("\n" * (num if num is not None else 1))
            elif kind == "tab":
                out.append("\t" * (num if num is not None else 1))
            elif kind == "skip":
                out.append(" " * (num if num is not None else 1))
            elif kind == "char":
                out.append(chr(num or 0) * dup)
                dup = 1
            elif kind == "dup":
                dup = max(num or 0, 0)
            continue
        f = _FMT.match(rest_)
        if f and rest_.startswith("%"):
            fmt = parse_format(f.group(0))
            i += f.end()
            continue
        lit = _literal(rest_)
        if lit is not None:
            value, used = lit
            i += used
            out.append((format_value(value, fmt) if fmt is not None and fmt.kind == "s" else value) * dup)
            fmt, dup = None, 1
            continue
        if rest_.startswith("("):
            depth, j = 0, 0
            while j < len(rest_):
                ch = rest_[j]
                if ch == '"':
                    k = rest_.find('"', j + 1)
                    j = len(rest_) - 1 if k == -1 else k
                elif ch == "(":
                    depth += 1
                elif ch == ")":
                    depth -= 1
                    if depth == 0:
                        break
                j += 1
            value = s.eval(rest_[1:j])
            i += j + 1
            if isinstance(value, str):
                piece = format_value(value, fmt) if fmt is not None and fmt.kind == "s" else value
            else:
                piece = format_value(value, fmt if fmt is not None else DISPLAY_NUMERIC, pad=fmt is not None)
                piece = piece if fmt is not None else piece.strip()
            out.append(piece * dup)
            fmt, dup = None, 1
            continue
        raise StataError(198, "invalid syntax")
    h.fh.write("".join(out))


def _write_binary(s: "Session", h: Handle, text: str) -> None:
    """%fmt (exp), %#s "text", %#s `"text"', %#s (exp)."""
    i, n = 0, len(text)
    while i < n:
        while i < n and text[i].isspace():
            i += 1
        if i >= n:
            break
        f = re.match(r"%\d*[a-z]+", text[i:])
        if not f:
            raise StataError(198, "invalid syntax")
        try:
            spec = binfmt.parse_spec(f.group(0))
        except ValueError:
            raise StataError(198, f"{f.group(0)} invalid format")   # VERIFY
        i += f.end()
        while i < n and text[i].isspace():
            i += 1
        rest_ = text[i:]
        lit = _literal(rest_)
        if lit is not None:
            value, used = lit
            i += used
        elif rest_.startswith("("):
            depth, j = 0, 0
            while j < len(rest_):
                ch = rest_[j]
                if ch == '"':
                    k = rest_.find('"', j + 1)
                    j = len(rest_) - 1 if k == -1 else k
                elif ch == "(":
                    depth += 1
                elif ch == ")":
                    depth -= 1
                    if depth == 0:
                        break
                j += 1
            value = s.eval(rest_[1:j])
            i += j + 1
        else:
            raise StataError(198, "invalid syntax")
        if (spec.kind == "s") != isinstance(value, str):
            raise StataError(109, "type mismatch")
        h.fh.write(binfmt.encode(value, spec, h.byteorder))


def _read_binary(s: "Session", h: Handle, rest: str) -> None:
    """file read h %fmt name: numbers go to a scalar, strings to a local macro."""
    specs = re.findall(r"(%\d*[a-z]+)\s+(\S+)", rest)
    if not specs:
        raise StataError(198, "invalid syntax")
    eof = False
    for fmt, name in specs:
        try:
            spec = binfmt.parse_spec(fmt)
        except ValueError:
            raise StataError(198, f"{fmt} invalid format")   # VERIFY
        raw = h.fh.read(spec.size)
        if len(raw) < spec.size:        # VERIFY: a partial value at the end counts as eof
            eof = True
            break
        value = binfmt.decode(raw, spec, h.byteorder)
        if spec.kind == "s":
            s.macros.set_local(name, value)
        else:
            s.scalars[name] = value
    s.r = {"eof": 1.0 if eof else 0.0}


def _seek(s: "Session", rest: str) -> None:
    parts = rest.split()
    if len(parts) != 2:
        raise StataError(198, "invalid syntax")
    h = _get(s, parts[0])
    where = parts[1]
    if where == "query":
        pass
    elif where == "tof":
        h.fh.seek(0)
    elif where == "eof":
        h.fh.seek(0, 2)
    else:
        try:
            pos = int(float(s.eval(where)))
        except (ValueError, TypeError):
            raise StataError(198, "invalid syntax")
        if pos < 0:
            raise StataError(198, "invalid file position")   # VERIFY
        h.fh.seek(pos)
    s.r = {"loc": float(h.fh.tell())}


def _set(s: "Session", rest: str) -> None:
    parts = rest.split()
    if len(parts) != 3 or parts[1] != "byteorder":
        raise StataError(198, "invalid syntax")
    h = _get(s, parts[0])
    order = {"hilo": binfmt.HILO, "1": binfmt.HILO, "lohi": binfmt.LOHI, "2": binfmt.LOHI}.get(parts[2])
    if order is None:
        raise StataError(198, "byteorder must be hilo, lohi, 1 or 2")
    h.byteorder = order


def _read(s: "Session", rest: str) -> None:
    parts = rest.split()
    h = _get(s, parts[0]) if parts else None
    if h is not None and h.binary:
        if h.mode == "w":
            raise StataError(608, f"file {h.path} is write-only")   # VERIFY
        _read_binary(s, h, rest.split(None, 1)[1] if len(parts) > 1 else "")
        return
    if len(parts) != 2:
        raise StataError(198, "invalid syntax")
    if h.mode == "w":
        raise StataError(608, f"file {h.path} is write-only")   # VERIFY
    line = h.fh.readline()
    eof = line == ""
    s.macros.set_local(parts[1], line.rstrip("\r\n"))
    s.r = {"eof": 1.0 if eof else 0.0}


def _close(s: "Session", rest: str) -> None:
    names = rest.split()
    handles = _handles(s)
    if names in (["_all"], ["all"]):
        names = list(handles)
    for name in names:
        h = _get(s, name)
        h.fh.close()
        del handles[name]


@command("file")
def cmd_file(s: "Session", args: str) -> None:
    sub, _, rest = args.strip().partition(" ")
    if sub in ("open",):
        _open(s, rest)
    elif sub in ("write", "w"):
        from ..core.formats import plain_numbers
        with plain_numbers():          # the file stores the number as Stata does
            _write(s, rest)
    elif sub in ("read", "r"):
        _read(s, rest)
    elif sub == "close":
        _close(s, rest)
    elif sub == "seek":
        _seek(s, rest)
    elif sub == "set":
        _set(s, rest)
    elif sub == "query":
        # one line per open handle: "binary read  h" (compat 1701; VERIFY: text files and read write)
        for name, h in _handles(s).items():
            how = {"r": "read", "w": "write", "rw": "read write"}.get(h.mode, h.mode)
            s.output.write(f"{'binary' if h.binary else 'text':<6} {how:<5} {name}\n", "text")
        s.r = {"N": float(len(_handles(s)))}
    else:
        raise StataError(198, f"file {sub}: subcommand not yet supported by OpenDTA")

files.opendta/commands/files.py:
"""use, save, saveold, notes, char.

Messages follow Stata 14; those marked VERIFY have cases in
compat/do/0104_arquivos.do.
"""

from __future__ import annotations

import os
import re
from pathlib import Path
from typing import TYPE_CHECKING

import numpy as np

from ..core.errors import StataError
from ..core.varlist import expand, resolve_name, unique
from ..io.dta import read_dta, write_dta
from ..lang.syntax import match_options, parse_standard
from ..lang.words import strip_outer_quotes
from ._util import touse
from .registry import command

if TYPE_CHECKING:
    from ..session import Session


def dta_path(text: str) -> Path:
    t = strip_outer_quotes(text.strip())
    if not t:
        raise StataError(198, "invalid file specification")
    p = Path(os.path.expanduser(t))
    if p.suffix == "":
        p = p.with_suffix(".dta")
    return p


def _shown(p: Path) -> str:
    """File name as Stata shows it in messages (what was typed)."""
    return str(p)


# ---------------------------------------------------------------------------
# use
# ---------------------------------------------------------------------------

@command("use", "u")
def cmd_use(s: "Session", args: str) -> None:
    p = parse_standard(args)
    opts = match_options(p.options, {"clear": 5, "nolabel": 5})
    if p.using is not None:
        path = dta_path(p.using)
        want_vars, if_, in_ = p.varlist, p.if_, p.in_
    else:
        path = dta_path(p.varlist)
        want_vars, if_, in_ = "", p.if_, p.in_
    ds = s.data
    if ds.changed and ds.nvars and not opts.get("clear"):
        raise StataError(4, "no; data in memory would be lost")
    if not path.exists():
        raise StataError(601, f"file {_shown(path)} not found")
    new = read_dta(path)
    if opts.get("nolabel"):
        new.value_labels = {}
        for v in new.vars:
            v.value_label = ""
    keep = unique(expand(new, want_vars)) if want_vars else None
    if keep is not None:
        # the if only sees the variables read (observed in Stata 14)
        new.drop_vars([n for n in new.names if n not in set(keep)])
    s.data = new
    if new.label:
        s.output.write(f"({new.label})\n", "text")
    if if_ or in_:
        try:
            from ..lang.syntax import Parsed
            mask = touse(s, Parsed(if_=if_, in_=in_))
            new.keep_obs(mask)
        except StataError:
            # Stata has already replaced the data: an error in the if leaves memory empty
            from ..core.dataset import Dataset
            s.data = Dataset()
            s.notify_state()
            raise
    new.changed = bool(want_vars or if_ or in_)
    s.notify_state()


# ---------------------------------------------------------------------------
# save / saveold
# ---------------------------------------------------------------------------

def _save(s: "Session", args: str, release: int, extra_opts: dict | None = None,
          old_note: bool = False) -> None:
    head, comma, opts_text = args.partition(",")
    spec = {"replace": 3, "emptyok": 5}
    spec.update(extra_opts or {})
    opts = match_options(opts_text, spec) if comma else {}
    ds = s.data
    if head.strip():
        path = dta_path(head)
        shown = _shown(path)
    elif ds.fullpath or ds.filename:
        path = Path(ds.fullpath or ds.filename)
        shown = ds.filename or _shown(path)   # VERIFY: name shown by `save, replace`
    else:
        raise StataError(198, "invalid file specification")
    if ds.nvars == 0 and not opts.get("emptyok"):
        raise StataError(2000, "no variables defined")
    exists = path.exists()
    if exists and not opts.get("replace"):
        raise StataError(602, f"file {shown} already exists")
    if opts.get("version"):
        v = int(str(opts["version"]))
        # Stata 14 writes version(11) in Stata 12 format (115), which Stata 11 reads
        release = {11: 115, 12: 115, 13: 117, 14: 118}.get(v, 0)
        if not release:
            raise StataError(198, f"version({opts['version']}) invalid\n    Stata 14 can write .dta "
                                  "files for Stata 14, 13, 12, or 11.  It cannot write .dta formats "
                                  "older than that.  (Stata 11 was released in 2009.)")
    if not exists and opts.get("replace"):
        s.output.write(f"(note: file {shown} not found)\n", "text")
    if old_note and release in (114, 115, 117):
        version = {114: 11, 115: 12, 117: 13}[release]
        asked = int(str(opts["version"])) if opts.get("version") else 13
        tail = {12: ", which can be read by Stata 11 or 12", 11: ", which Stata 11 can read"}.get(asked, "")
        s.output.write(f"(saving in Stata {version} format{tail})\n", "text")
        if not opts.get("version"):
            s.output.write("(FYI, saveold has options version(12) and version(11) "
                           "that write files in older Stata formats)\n", "text")
        if release in (114, 115):
            from ..io.dta import _old_vars
            _, cut = _old_vars(ds)
            for name in cut:
                # VERIFY: warning about strings cut at 244 characters
                s.output.write(f"(note: variable {name} truncated to str244)\n", "text")
    try:
        ds.timestamp = write_dta(ds, path, release=release)
    except OSError as e:
        raise StataError(603, f"file {shown} could not be opened ({e.strerror})")
    if head.strip():
        ds.filename = str(path)
    ds.fullpath = str(path.resolve())
    ds.changed = False
    s.output.write(f"file {shown} saved\n", "text")
    s.notify_state()


@command("save", "sa")
def cmd_save(s: "Session", args: str) -> None:
    _save(s, args, 118)


@command("saveold")
def cmd_saveold(s: "Session", args: str) -> None:
    # Stata 14's saveold writes for Stata 13 (format 117) by default
    _save(s, args, 117, {"version": 1}, old_note=True)


# ---------------------------------------------------------------------------
# notes (stored as characteristics: note0 = count, note1.. = texts)
# ---------------------------------------------------------------------------

def _notes_of(s: "Session", owner: str) -> list[str]:
    chars = s.data.chars.get(owner, {})
    try:
        n = int(chars.get("note0", "0"))
    except ValueError:
        n = 0
    return [chars.get(f"note{k}", "") for k in range(1, n + 1)]


def _touch_char(chars: dict, key: str, value: str) -> None:
    """Stores a characteristic. Stata lists characteristics from the most
    recent to the oldest, and changing an existing one makes it the most
    recent (observed in compat/expected/0104_arquivos.log)."""
    chars.pop(key, None)
    chars[key] = value


def _set_notes(s: "Session", owner: str, notes: list[str]) -> None:
    chars = s.data.chars.setdefault(owner, {})
    for k in [k for k in chars if re.match(r"^note\d+$", k)]:
        del chars[k]
    if notes:
        chars["note0"] = str(len(notes))
        for k, text in enumerate(notes, start=1):
            chars[f"note{k}"] = text
    if not chars:
        s.data.chars.pop(owner, None)
    s.data.changed = True


def _add_note(s: "Session", owner: str, text: str) -> None:
    """New note: first updates note0 (the count), then creates note#."""
    chars = s.data.chars.setdefault(owner, {})
    n = len(_notes_of(s, owner)) + 1
    _touch_char(chars, "note0", str(n))
    _touch_char(chars, f"note{n}", text)
    s.data.changed = True


@command("notes", "note")
def cmd_notes(s: "Session", args: str) -> None:
    t = args.strip()
    ds = s.data
    m = re.match(r"^([A-Za-z_][A-Za-z0-9_]*)?\s*:\s*(.*)$", t, re.S)
    if m:
        owner = m.group(1) or "_dta"
        if owner != "_dta":
            owner = resolve_name(ds, owner)
        text = m.group(2).strip()
        _add_note(s, owner, text)
        return
    words = t.split()
    if words and words[0] == "drop":
        targets = words[1:] or ["_all"]
        owners = ["_dta"] + ds.names if targets == ["_all"] else [
            "_dta" if w == "_dta" else resolve_name(ds, w) for w in targets]
        dropped = 0
        for o in owners:
            dropped += len(_notes_of(s, o))
            if _notes_of(s, o):
                _set_notes(s, o, [])
        s.output.write(f"  ({dropped} note{'s' if dropped != 1 else ''} dropped)\n", "text")
        return
    if words and words[0] in ("list", "l", "li", "lis"):
        words = words[1:]
    owners = ["_dta"] + ds.names if not words or words == ["_all"] else [
        "_dta" if w == "_dta" else resolve_name(ds, w) for w in words]
    out = s.output
    # VERIFY: layout of the notes listing
    for o in owners:
        notes = _notes_of(s, o)
        if not notes:
            continue
        out.write(f"\n{o}:\n", "text")
        for k, text in enumerate(notes, start=1):
            out.write(f"{k:>3}.  {text}\n", "text")


# ---------------------------------------------------------------------------
# char
# ---------------------------------------------------------------------------

@command("char")
def cmd_char(s: "Session", args: str) -> None:
    t = args.strip()
    ds = s.data
    sub, _, rest = t.partition(" ")
    if sub in ("define", "def", "de", "defi", "defin") or "[" in sub:
        spec = rest if sub.startswith("de") and "[" not in sub else t
        m = re.match(r"^([A-Za-z_][A-Za-z0-9_]*)\[([A-Za-z_][A-Za-z0-9_]*)\]\s*(.*)$", spec.strip(), re.S)
        if not m:
            raise StataError(198, "invalid syntax")
        owner = m.group(1) if m.group(1) == "_dta" else resolve_name(ds, m.group(1))
        value = strip_outer_quotes(m.group(3)) if m.group(3).strip() else ""
        chars = ds.chars.setdefault(owner, {})
        if value:
            _touch_char(chars, m.group(2), value)
        else:
            chars.pop(m.group(2), None)
            if not chars:
                ds.chars.pop(owner, None)
        ds.changed = True
        return
    if sub in ("list", "l", "li", "lis", ""):
        # a target is a variable or _dta; "_dta[]" is the same (compat 1701)
        targets = [x.split("[")[0] for x in rest.split()]
        out = s.output
        owners = [o for o in ["_dta"] + ds.names if o in ds.chars]
        owners += [o for o in ds.chars if o not in owners]
        for owner in owners:
            chars = ds.chars[owner]
            if targets and owner not in targets:
                continue
            for name, value in reversed(list(chars.items())):
                out.write(f"  {owner}[{name}]:".ljust(30) + f"{value}\n", "text")
        return
    raise StataError(198, "invalid syntax")


# ---------------------------------------------------------------------------
# browse / edit (open the Data Browser in the graphical interface)
# ---------------------------------------------------------------------------

def _browse(s: "Session", args: str, *, edit: bool = False) -> None:
    from ..lang.syntax import Parsed
    p = parse_standard(args)
    o = match_options(p.options, {"nolabel": 3}) if p.options.strip() else {}
    names = unique(expand(s.data, p.varlist)) if p.varlist.strip() else None
    rows = None
    if p.if_ or p.in_:
        rows = np.flatnonzero(touse(s, Parsed(if_=p.if_, in_=p.in_)))
    hook = s.ui_hooks.get("browse")
    if hook is not None:
        # without the interface (batch mode) Stata also shows nothing
        hook(names, rows, edit=edit, nolabel=bool(o.get("nolabel")))


@command("browse", "br")
def cmd_browse(s: "Session", args: str) -> None:
    _browse(s, args)


@command("edit", "ed")
def cmd_edit(s: "Session", args: str) -> None:
    _browse(s, args, edit=True)


# ---------------------------------------------------------------------------
# type (shows a text file)
# ---------------------------------------------------------------------------

@command("type", "ty")
def cmd_type(s: "Session", args: str) -> None:
    head, comma, opts_text = args.partition(",")
    o = match_options(opts_text, {"asis": 4, "smcl": 4, "showtabs": 8, "starbang": 8,
                                  "lines": 4}) if comma else {}
    t = strip_outer_quotes(head.strip())
    if not t:
        raise StataError(198, "invalid file specification")
    path = Path(os.path.expanduser(t))
    if not path.exists():
        raise StataError(601, f"file {t} not found")
    raw = path.read_bytes()
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        text = raw.decode("latin-1")
    lines = text.replace("\r\n", "\n").replace("\r", "\n").split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    if o.get("lines"):
        lines = lines[:int(str(o["lines"]))]
    out = []
    for ln in lines:
        if not o.get("starbang") and ln.startswith("*!"):
            continue   # VERIFY: *! lines only appear with starbang
        # VERIFY: tabs expanded every 8 columns; showtabs shows <T>
        ln = ln.replace("\t", "<T>") if o.get("showtabs") else ln.expandtabs(8)
        out.append(ln)
    s.output.write("".join(x + "\n" for x in out), "text")


# ---------------------------------------------------------------------------
# erase / rm
# ---------------------------------------------------------------------------

def _erase(s: "Session", args: str) -> None:
    t = strip_outer_quotes(args.strip())
    if not t:
        raise StataError(198, "invalid file specification")
    path = Path(os.path.expanduser(t))
    if not path.exists():
        raise StataError(601, f"file {t} not found")
    try:
        path.unlink()
    except OSError as e:
        raise StataError(693, f"could not erase file {t} ({e.strerror})")


@command("erase")
def cmd_erase(s: "Session", args: str) -> None:
    _erase(s, args)


@command("rm")
def cmd_rm(s: "Session", args: str) -> None:
    _erase(s, args)


@command("varmanage")
def cmd_varmanage(s: "Session", args: str) -> None:
    hook = s.ui_hooks.get("varmanage")
    if hook is not None:
        hook()

files.opendta/commands/graphcmd.py:
"""Graph commands: graph (and subcommands), twoway, scatter, line,
connected, tsline, histogram and kdensity ([G-2], [R] histogram, [R] kdensity).

Graphs are kept in the session (graph dir/drop/rename) and appear
in the Graph window of the interface; without the interface (batch mode),
they are only kept and can be written with graph export/graph save.
Messages follow Stata 14; what is undocumented has the VERIFY mark and
cases in compat/do/07xx."""

from __future__ import annotations

from pathlib import Path
from typing import TYPE_CHECKING

from ..core.errors import StataError
from ..graphics import families as FAM
from ..graphics import render as R
from ..graphics import twoway as TW
from ..graphics.model import Graph
from ..graphics.opts import name_opt, saving_opt
from ..graphics.store import gph_path, load_gph, save_gph, store
from ..lang.syntax import find_top, match_options
from ..lang.words import split_words, strip_outer_quotes
from .registry import command

if TYPE_CHECKING:
    from ..session import Session


# ---------------------------------------------------------------------------
# common part: name(), saving(), nodraw, scheme and display
# ---------------------------------------------------------------------------

def finish(s: "Session", g: Graph, graw: dict) -> None:
    name, replace = ("Graph", True)
    if "name" in graw and isinstance(graw["name"], str):
        name, replace = name_opt(graw["name"])
    g.name = name
    if "scheme" not in g.opts:
        g.opts["scheme"] = s.settings.get("scheme", "s2color")
    store(s).put(g, replace=replace)
    if "saving" in graw and isinstance(graw["saving"], str):
        fname, rep = saving_opt(graw["saving"])
        path = gph_path(fname)
        save_gph(g, path, replace=rep, out=s.output)
        s.output.write(f"(file {_shown(fname, path)} saved)\n", "text")
    if not graw.get("nodraw"):
        show(s, g)


def show(s: "Session", g: Graph) -> None:
    if s.settings.get("graphics", "on") != "on":
        return
    hook = s.ui_hooks.get("graph")
    if hook is not None:
        hook(g)


def _shown(text: str, path: Path) -> str:
    """File name as the user wrote it, with the extension added."""
    t = strip_outer_quotes(text.strip())
    return t if Path(t).suffix else t + path.suffix


# ---------------------------------------------------------------------------
# twoway e atalhos
# ---------------------------------------------------------------------------

def _twoway(s: "Session", text: str, default_type: str | None = None) -> None:
    g, graw = TW.build(s, text, default_type=default_type)
    finish(s, g, graw)


@command("twoway", "tw")
def cmd_twoway(s: "Session", args: str) -> None:
    _twoway(s, args)


@command("scatter", "sc")
def cmd_scatter(s: "Session", args: str) -> None:
    _twoway(s, args, "scatter")


@command("line")
def cmd_line(s: "Session", args: str) -> None:
    _twoway(s, args, "line")


@command("connected")
def cmd_connected(s: "Session", args: str) -> None:
    _twoway(s, args, "connected")


@command("tsline")
def cmd_tsline(s: "Session", args: str) -> None:
    _twoway(s, args, "tsline")


@command("histogram", "hist")
def cmd_histogram(s: "Session", args: str) -> None:
    g, graw, msg = FAM.histogram(s, args)
    # with by() Stata does not show the bins message (compat 0701)
    if "by" not in graw:
        s.output.write(msg + "\n", "text")
    finish(s, g, graw)


@command("kdensity", "kdens")
def cmd_kdensity(s: "Session", args: str) -> None:
    g, graw = FAM.kdensity(s, args)
    if g is not None:
