def _base_plot(name: str, abbrev: str | None = None):
    def run(s: "Session", args: str) -> None:
        from ..graphics import baseplots
        _post(getattr(baseplots, name), s, args)
    run.__name__ = f"cmd_{name}"
    command(name, abbrev or name)(run)


