"""local, global, macro and extended macro functions (manual [P] macro)."""

from __future__ import annotations

import fnmatch
import re
from typing import TYPE_CHECKING

from ..core.errors import StataError
from ..core.formats import number_to_macro
from ..lang.words import split_words, strip_outer_quotes
from .registry import command

if TYPE_CHECKING:
    from ..session import Session

_NAME = re.compile(r"^\s*([A-Za-z_0-9][A-Za-z0-9_]*)(.*)$", re.S)


def _assign(s: "Session", args: str, setter) -> None:
    inc = re.match(r"^\s*(\+\+|--)([A-Za-z_][A-Za-z0-9_]*)\s*$", args)
    if inc and setter == s.macros.set_local:
        # local ++i / local --i
        name = inc.group(2)
        current = s.macros.get_local(name) or "0"
        try:
            x = float(current)
        except ValueError:
            raise StataError(198, "invalid syntax")
        x += 1 if inc.group(1) == "++" else -1
        setter(name, number_to_macro(x))
        return
    m = _NAME.match(args)
    if not m:
        raise StataError(198, "invalid syntax")
    name, rest = m.group(1), m.group(2)
    if len(name) > 31:
        raise StataError(198, f"{name} invalid name")
    rest_s = rest.strip()
    if rest_s.startswith("="):
        v = s.eval(rest_s[1:])
        value = v if isinstance(v, str) else number_to_macro(v)
    elif rest_s.startswith(":"):
        value = extended_function(s, rest_s[1:].strip())
    else:
        value = strip_outer_quotes(rest_s) if rest_s else ""
    setter(name, value)


@command("local", "loc")
def cmd_local(s: "Session", args: str) -> None:
    _assign(s, args, s.macros.set_local)


@command("global", "gl")
def cmd_global(s: "Session", args: str) -> None:
    _assign(s, args, s.macros.set_global)


@command("macro", "ma")
def cmd_macro(s: "Session", args: str) -> None:
    sub, _, rest = args.strip().partition(" ")
    rest = rest.strip()
    out = s.output
    if sub in ("list", "l", "li", "lis", "dir", "di"):
        names = rest.split()
        for name, value in sorted(s.macros.globals.items()):
            if names and name not in names:
                continue
            out.write(f"{name + ':':<16}{value}\n", "text")
        for name, value in sorted(s.macros.locals.items()):
            if names and "_" + name not in names:
                continue
            out.write(f"{'_' + name + ':':<16}{value}\n", "text")
        return
    if sub == "drop":
        for pat in rest.split():
            if pat == "_all":
                s.macros.clear_globals()
                continue
            target = s.macros.locals if pat.startswith("_") else s.macros.globals
            key = pat[1:] if pat.startswith("_") else pat
            for name in [k for k in target if fnmatch.fnmatchcase(k, key)]:
                del target[name]
        return
    if sub == "shift":
        loc = s.macros.locals
        k = 1
        while str(k + 1) in loc:
            loc[str(k)] = loc[str(k + 1)]
            k += 1
        loc.pop(str(k), None)
        return
    raise StataError(198, "invalid syntax")


# ---------------------------------------------------------------------------
# Extended functions: local x : <function>
# ---------------------------------------------------------------------------

def extended_function(s: "Session", text: str) -> str:
    t = text.strip()

    m = re.match(r"^word\s+count\s+(.*)$", t, re.S)
    if m:
        return str(len(split_words(m.group(1))))
    m = re.match(r"^word\s+(\S+)\s+of\s+(.*)$", t, re.S)
    if m:
        k = int(float(s.eval(m.group(1))))
        words = split_words(m.group(2))
        return words[k - 1] if 1 <= k <= len(words) else ""
    m = re.match(r"^(?:length|strlen)\s+(local|global)\s+(\S+)$", t)
    if m:
        store = s.macros.get_local if m.group(1) == "local" else s.macros.get_global
        return str(len(store(m.group(2))))
    m = re.match(r"^di(?:s|sp|spl|spla|splay)?\s+(.*)$", t, re.S)
    if m:
        return _capture_display(s, m.group(1))
    m = re.match(r"^list\s+(.*)$", t, re.S)
    if m:
        return _list_function(s, m.group(1).strip())
    m = re.match(r"^env(?:ironment)?\s+(\S+)$", t)
    if m:
        import os
        return os.environ.get(m.group(1), "")
    m = re.match(r"^piece\s+(\S+)\s+(\S+)\s+of\s+(.*)$", t, re.S)
    if m:
        return _piece(int(float(m.group(1))), int(float(m.group(2))), strip_outer_quotes(m.group(3)))
    value = _data_function(s, t)
    if value is not None:
        return value
    word = t.split()[0] if t else ""
    # VERIFY: Stata's message for an unknown extended function
    raise StataError(198, f"{word} not allowed")


def _var(s: "Session", name: str):
    from ..core.varlist import resolve_name
    return s.data.get(resolve_name(s.data, name.strip()))


def _data_function(s: "Session", t: str) -> str | None:
    """Functions that query the data, labels, characteristics, files and
    stored results."""
    import fnmatch
    from pathlib import Path

    m = re.fullmatch(r"(type|format|f|fo|for|form|forma)\s+(\S+)", t)
    if m:
        v = _var(s, m.group(2))
        return v.vtype if m.group(1) == "type" else v.fmt
    m = re.fullmatch(r"value\s+l(?:a|ab|abe|abel)?\s+(\S+)", t)
    if m:
        return _var(s, m.group(1)).value_label
    m = re.fullmatch(r"var(?:iable)?\s+l(?:a|ab|abe|abel)?\s+(\S+)", t)
    if m:
        return _var(s, m.group(1)).label
    if re.fullmatch(r"data\s+l(?:a|ab|abe|abel)?", t):
        return s.data.label
    if t == "sortedby":
        return " ".join(s.data.sortlist)
    m = re.fullmatch(r"label\s+\((\S+)\)\s+(\S+)(?:\s+(\d+))?(\s*,\s*strict)?", t)
    if m:
        v = _var(s, m.group(1))
        return _label_text(s, v.value_label, m.group(2), m.group(3), bool(m.group(4)))
    m = re.fullmatch(r"label\s+(\S+)\s+(\S+)(?:\s+(\d+))?(\s*,\s*strict)?", t)
    if m:
        if m.group(1) not in s.data.value_labels and m.group(2) != "maxlength":
            raise StataError(111, f"value label {m.group(1)} not found")
        return _label_text(s, m.group(1), m.group(2), m.group(3), bool(m.group(4)))
    m = re.fullmatch(r"char\s+(\S+)\[([^\]]*)\]", t)
    if m:
        owner = m.group(1) if m.group(1) == "_dta" else _var(s, m.group(1)).name
        chars = s.data.chars.get(owner, {})
        if m.group(2) == "":
            return " ".join(chars)
        return chars.get(m.group(2), "")
    m = re.fullmatch(r'dir\s+(\S+|"[^"]*")\s+(files|dirs|other)\s+(\S+|"[^"]*")(\s*,.*)?', t)
    if m:
        folder = Path(strip_outer_quotes(m.group(1))).expanduser()
        pattern = strip_outer_quotes(m.group(3))
        opts = (m.group(4) or "").replace(",", " ").split()
        if not folder.is_dir():
            if "nofail" in opts:
                return ""
            raise StataError(601, f"directory {folder} not found")   # VERIFY
        kind = m.group(2)
        respect = "respectcase" in opts
        out = []
        for p in sorted(folder.iterdir(), key=lambda x: x.name):
            if kind == "files":
                ok = p.is_file()
            elif kind == "dirs":
                ok = p.is_dir()
            else:
                ok = not (p.is_file() or p.is_dir())
            name = p.name
            if name.startswith(".") and not pattern.startswith("."):
                continue                       # hidden only with an explicit pattern
            hit = (fnmatch.fnmatchcase(name, pattern) if respect
                   else fnmatch.fnmatchcase(name.lower(), pattern.lower()))
            if ok and hit:
                out.append(f'"{name}"')
        return " ".join(out)
    m = re.fullmatch(r"sysdir\s+(\S+)", t)
    if m:
        from ..lang.adopath import sysdir
        return sysdir(s).get(m.group(1).upper(), m.group(1))
    m = re.fullmatch(r"permname\s+(\S+)(?:\s*,\s*length\((\d+)\))?", t)
    if m:
        base = re.sub(r"[^A-Za-z0-9_]", "_", m.group(1))[: int(m.group(2) or 32)]
        name, k = base, 0
        while s.data.has(name):
            k += 1
            name = f"{base[: 32 - len(str(k))]}{k}"
        return name
    m = re.fullmatch(r"(copy|strlen|length|ustrlen|udstrlen)\s+(local|global)\s+(\S+)", t)
    if m:
        store = s.macros.get_local if m.group(2) == "local" else s.macros.get_global
        text = store(m.group(3))
        if m.group(1) == "copy":
            return text
        return str(len(text.encode("utf-8")) if m.group(1) in ("strlen", "length") else len(text))
    m = re.fullmatch(r'subinstr\s+(local|global)\s+(\S+)\s+("[^"]*"|`"[^`]*"\'|\S+)\s+'
                     r'("[^"]*"|`"[^`]*"\'|\S+)(\s*,.*)?', t, re.S)
    if m:
        store = s.macros.get_local if m.group(1) == "local" else s.macros.get_global
        text = store(m.group(2))
        old, new = strip_outer_quotes(m.group(3)), strip_outer_quotes(m.group(4))
        opts = m.group(5) or ""
        count_m = re.search(r"count\((local|global)\s+(\w+)\)", opts)
        all_ = re.search(r"\ball\b", opts) is not None
        word = re.search(r"\bword\b", opts) is not None
        if word:
            # replaces the word in place, without touching the surrounding spaces ("a b a" without
            # the 1st "a" becomes " b a"; observed in Stata 14)
            pattern = r"(?<!\S)" + re.escape(old) + r"(?!\S)"
            result, n = re.subn(pattern, lambda _m: new, text, count=0 if all_ else 1)
        else:
            n = text.count(old) if all_ else min(1, text.count(old))
            result = text.replace(old, new) if all_ else text.replace(old, new, 1)
        if count_m:
            setter = s.macros.set_local if count_m.group(1) == "local" else s.macros.set_global
            setter(count_m.group(2), str(n))
        return result
    m = re.fullmatch(r"([rse])\((scalars|macros|matrices|functions)\)", t)
    if m:
        store = {"r": s.r, "e": s.e, "s": s.sret}[m.group(1)]
        kind = m.group(2)
        if kind == "scalars":
            names = [k for k, v in store.items() if not isinstance(v, str) and not hasattr(v, "shape")]
        elif kind == "macros":
            names = [k for k, v in store.items() if isinstance(v, str)]
        elif kind == "matrices":
            names = [k for k, v in store.items() if hasattr(v, "rows")]
        else:
            names = []
        return " ".join(sorted(names, reverse=False))
    m = re.fullmatch(r"(rownames|colnames|rowfullnames|colfullnames|roweq|coleq)\s+(\S+)", t)
    if m:
        from .matrix import matrix_names
        return matrix_names(s, m.group(2), m.group(1))
    m = re.fullmatch(r"(rowsof|colsof)\s+(\S+)", t)
    if m:
        from .matrix import get_matrix
        mat = get_matrix(s, m.group(2))
        return str(mat.rows if m.group(1) == "rowsof" else mat.cols)
    return None


def _label_text(s: "Session", lbl: str, value: str, length: str | None, strict: bool) -> str:
    labels = s.data.value_labels.get(lbl, {})
    if value == "maxlength":
        return str(max((len(x) for x in labels.values()), default=0))
    try:
        x = float(value)
    except ValueError:
        raise StataError(198, "invalid syntax")
    text = labels.get(int(x)) if x == int(x) else None
    if text is None:
        text = "" if strict else number_to_macro(x)
    if length:
        text = text[: int(length)]
    return text


def _capture_display(s: "Session", args: str) -> str:
    from ..core.output import Capture
    from .display import cmd_display
    cap = Capture()
    out = s.output
    saved = out._listeners, out.column, out.quiet_depth, out.noisy_depth
    out._listeners = [cap]
    out.quiet_depth = out.noisy_depth = 0
    from ..core.formats import plain_numbers
    try:
        with plain_numbers():          # macro text can be read back
            cmd_display(s, args + " _continue")
    finally:
        out._listeners, out.column, out.quiet_depth, out.noisy_depth = saved
    return cap.text


def _piece(n: int, length: int, text: str) -> str:
    words = text.split()
    pieces: list[str] = []
    cur = ""
    for w in words:
        cand = (cur + " " + w).strip()
        if len(cand) <= length or not cur:
            cur = cand
        else:
            pieces.append(cur)
            cur = w
    if cur:
        pieces.append(cur)
    return pieces[n - 1] if 1 <= n <= len(pieces) else ""


def _list_function(s: "Session", spec: str) -> str:
    get = s.macros.get_local
    words = spec.split()
    if not words:
        raise StataError(198, "invalid syntax")
    op = words[0]
    if op in ("uniq", "dups", "sort", "clean", "retokenize", "sizeof"):
        items = split_words(get(words[1]), keep_quotes=True)
        if op == "uniq":
            seen: list[str] = []
            for it in items:
                if it not in seen:
                    seen.append(it)
            return " ".join(seen)
        if op == "dups":
            seen, dups = [], []
            for it in items:
                if it in seen:
                    dups.append(it)
                seen.append(it)
            return " ".join(dups)
        if op == "sort":
            return " ".join(sorted(items))
        if op in ("clean", "retokenize"):
            return " ".join(items)
        return str(len(items))
    if op == "posof":
        m = re.match(r'^posof\s+(.+?)\s+in\s+(\S+)$', spec)
        if not m:
            raise StataError(198, "invalid syntax")
        target = strip_outer_quotes(m.group(1))
        items = split_words(get(m.group(2)))
        return str(items.index(target) + 1) if target in items else "0"
    if len(words) == 3 and words[1] in ("|", "&", "-", "==", "===", "in"):
        a = split_words(get(words[0]), keep_quotes=True)
        b = split_words(get(words[2]), keep_quotes=True)
        o = words[1]
        if o == "|":
            return " ".join(a + [x for x in b if x not in a])
        if o == "&":
            return " ".join(x for x in a if x in b)
        if o == "-":
            return " ".join(x for x in a if x not in b)
        if o == "==":
            return "1" if sorted(a) == sorted(b) else "0"
        if o == "===":
            return "1" if a == b else "0"
        return "1" if all(x in b for x in a) else "0"
    raise StataError(198, "invalid syntax")

files.opendta/commands/matacmd.py:
"""One-line mata command: `mata: statement`, `mata statement` and the
subcommands `mata clear`, `mata describe`, `mata drop`. The
`mata ... end` block is handled by the interpreter (lang/interpreter.py)."""

from __future__ import annotations

from typing import TYPE_CHECKING

from .registry import command

if TYPE_CHECKING:
    from ..session import Session

_SUBCOMMANDS = {"clear", "describe", "d", "drop", "set", "mlib", "mosave", "which", "memory",
                "query", "rename"}


@command("mata")
def cmd_mata(s: "Session", args: str) -> None:
    text = args.strip()
    if text.startswith(":"):
        text = text[1:].strip()
    if not text:
        return
    first = text.split()[0]
    from ..mata.interp import MataLeave
    try:
        if first in _SUBCOMMANDS:
            s.mata.subcommand(text)
        else:
            s.mata.run_statement(text)
    except MataLeave:
        pass

files.opendta/commands/matlist.py:
"""matlist ([P] matlist): displays a matrix as a table.

    matlist matrix_exp [, style_options general_options]
    matlist matrix_exp, cspec(cspec) rspec(rspec) [general_options]

The layout is in core/layout.py. Equation names: the column equations go in a line above the
column names (showcoleq()), and each row equation in a line of its own above its rows. VERIFY the
whole layout with equations against Stata (compat 1910).
"""

from __future__ import annotations

import re
from typing import TYPE_CHECKING

import numpy as np

from ..core import missing as M
from ..core.errors import StataError
from ..core.formats import format_value, parse_format
from ..core.layout import Field, Sep, align, render_table
from ..lang.syntax import find_top, match_options
from ..lang.words import strip_outer_quotes
from .matrix import Matrix, evaluate_matrix
from .registry import command

if TYPE_CHECKING:
    from ..session import Session

_OPTIONS = {"lines": 3, "border": 3, "format": 3, "twidth": 2, "left": 3, "right": 3,
            "title": 3, "tindent": 3, "rowtitle": 4, "names": 5, "nonames": 3, "noblank": 3,
            "nohalf": 3, "nodotz": 3, "underscore": 5, "aligncolnames": 5, "linesize": 5,
            "cspec": 5, "rspec": 5, "showcoleq": 5, "roweqonly": 5, "coleqonly": 5,
            "colorcoleq": 6, "keepcoleq": 5}
# alignment of the column equation over its group (first and lcombined: left, from the first column;
# compat 1910); combined: VERIFY
_SHOWCOLEQ = {"first": "L", "each": "R", "combined": "C", "lcombined": "L", "rcombined": "R"}
_LINES = ("oneline", "eq", "rowtotal", "coltotal", "rctotal", "rows", "columns", "cells", "none")


def _int(s: "Session", text, name: str, low: int = 0) -> int:
    try:
        x = float(s.eval(str(text)))
    except StataError:
        raise StataError(198, f"option {name}() incorrectly specified")
    if x != int(x) or x < low:
        raise StataError(198, f"option {name}() incorrectly specified")
    return int(x)


def _border(text: str) -> set[str]:
    words = set(text.split()) if text else {"all"}
    allowed = {"none", "all", "rows", "columns", "left", "right", "top", "bottom"}
    if not words <= allowed:
        raise StataError(198, "option border() incorrectly specified")
    out: set[str] = set()
    for w in words:
        out |= {"all": {"left", "right", "top", "bottom"}, "rows": {"top", "bottom"},
                "columns": {"left", "right"}, "none": set()}.get(w, {w})
    return out


def _parse_cspec(text: str, nfields: int) -> tuple[list[Field], list[Sep], list[str]]:
    """cspec(): separators (& or |, with o# spaces before and after) and the specs of the fields.
    Returns the fields, the separators and the formats of the fields."""
    tokens = re.findall(r"o\d+|&|\||%[-~]?\d*(?:\.\d+)?[a-zA-Z]+|w\d+|[sbitecLRC]", text)
    seps: list[dict] = [{"line": None, "before": None, "after": None}]
    fields: list[dict] = []
    cur_field: dict | None = None
    for tok in tokens:
        sep = seps[-1]
        if tok[0] == "o" and tok[1:].isdigit():
            if cur_field is not None and cur_field.get("fmt"):
                cur_field = None
                seps.append({"line": None, "before": None, "after": None})
                sep = seps[-1]
            n = int(tok[1:])
            if sep["line"] is None:
                sep["before"] = n
            else:
                sep["after"] = n
        elif tok in "&|":
            if cur_field is not None and cur_field.get("fmt"):
                cur_field = None
                seps.append({"line": None, "before": None, "after": None})
                sep = seps[-1]
            sep["line"] = tok == "|"
        else:
            if cur_field is None or cur_field.get("fmt"):
                cur_field = {"fmt": "", "align": "", "width": None}
                fields.append(cur_field)
            if tok.startswith("%"):
                cur_field["fmt"] = tok
            elif tok in ("L", "R", "C"):
                cur_field["align"] = tok
            elif tok.startswith("w"):
                cur_field["width"] = int(tok[1:])
    if len(fields) != nfields or len(seps) != nfields + 1:
        raise StataError(198, "option cspec() incorrectly specified")      # VERIFY
    out_fields, out_seps, fmts = [], [], []
    for k, f in enumerate(fields):
        fmt = f["fmt"] or "%9.0g"
        w = f["width"] or parse_format(fmt).width
        out_fields.append(Field(w, f["align"] or ("L" if "-" in fmt else "R")))
        fmts.append(fmt)
    last = len(seps) - 1
    for k, sp in enumerate(seps):
        line = bool(sp["line"])
        # one space on each side of a line, none before the first separator or after the last
        before = sp["before"] if sp["before"] is not None else (0 if k == 0 or (k == last and not line) else 1)
        after = sp["after"] if sp["after"] is not None else (0 if k == last or (k == 0 and not line) else 1)
        out_seps.append(Sep(line, before, after))
    return out_fields, out_seps, fmts


@command("matlist")
def cmd_matlist(s: "Session", args: str) -> None:
    i = find_top(args, ",")
    head, opts = (args, "") if i < 0 else (args[:i], args[i + 1:])
    if not head.strip():
        raise StataError(198, "invalid syntax")
    mat: Matrix = evaluate_matrix(s, head.strip())
    o = match_options(opts, _OPTIONS) if opts.strip() else {}
    showcoleq = str(o.get("showcoleq", "first")).strip() if o.get("showcoleq") not in (None, True) \
        else "first"
    if showcoleq not in _SHOWCOLEQ:
        raise StataError(198, f"option {showcoleq} not allowed")                 # compat 1910
    if o.get("colorcoleq") not in (None, True) and str(o["colorcoleq"]).strip() not in ("txt", "res"):
        raise StataError(198, "option colorcoleq() incorrectly specified")        # VERIFY
    fmt = str(o.get("format", "%9.0g")).strip()
    twidth = _int(s, o["twidth"], "twidth", 1) if o.get("twidth") not in (None, True) else 12
    left = _int(s, o["left"], "left") if o.get("left") not in (None, True) else 0
    right = _int(s, o["right"], "right") if o.get("right") not in (None, True) else 0
    tindent = _int(s, o["tindent"], "tindent") if o.get("tindent") not in (None, True) else 0
    title = strip_outer_quotes(str(o["title"]).strip()) if o.get("title") not in (None, True) else ""
    rowtitle = strip_outer_quotes(str(o["rowtitle"]).strip()) if o.get("rowtitle") not in (None, True) else ""
    names = str(o.get("names", "all")).strip()
    if o.get("nonames"):
        names = "none"
    if names not in ("rows", "columns", "all", "none"):
        raise StataError(198, "option names() incorrectly specified")
    show_rows, show_cols = names in ("rows", "all"), names in ("columns", "all")
    if rowtitle and not (show_rows and show_cols):
        raise StataError(198, "option rowtitle() requires both row and column names")
    aname = str(o.get("aligncolnames", "ralign")).strip()
    how = {"ralign": "R", "lalign": "L", "center": "C"}.get(aname)
    if how is None:
        raise StataError(198, f"option {aname} not allowed")
    lines = str(o.get("lines", "")).strip()
    if lines and lines not in _LINES:
        raise StataError(198, "option lines() incorrectly specified")
    border = _border(str(o["border"]).strip()) if o.get("border") else set()
    linesize = _int(s, o["linesize"], "linesize", 1) if o.get("linesize") not in (None, True) \
        else int(float(s.settings.get("linesize", 80)))

    rown = [r.replace("_", " ") for r in mat.rownames] if o.get("underscore") else list(mat.rownames)
    coln = [c.replace("_", " ") for c in mat.colnames] if o.get("underscore") else list(mat.colnames)
    req = [q if q != "_" else "" for q in (mat.roweq or ["_"] * mat.rows)]
    ceq = [q if q != "_" else "" for q in (mat.coleq or ["_"] * mat.cols)]
    has_req, has_ceq = any(req), any(ceq)
    if not lines:
        # with equation names, the equations are separated by lines (compat 1910)
        lines = "eq" if (has_req or has_ceq) else "oneline"
    sym = mat.rows == mat.cols and mat.rows > 1 and np.array_equal(mat.data, mat.data.T)
    half = sym and not o.get("nohalf")

    def text(x: float, f: str) -> str:
        if x >= M.SYSMISS:
            return "" if o.get("nodotz") and x == M.EXTENDED["z"] else M.missing_name(float(x))
        return format_value(float(x), f, pad=False).strip()

    if o.get("cspec") or o.get("rspec"):
        if not (o.get("cspec") and o.get("rspec")):
            raise StataError(198, "options cspec() and rspec() must be specified together")
        fields, seps, fmts = _parse_cspec(str(o["cspec"]), mat.cols + (1 if show_rows else 0))
        numfmts = fmts[1:] if show_rows else fmts
        numfields = fields[1:] if show_rows else fields
    else:
        numfmts = [fmt] * mat.cols
        wfmt = parse_format(fmt).width
        numfields = [Field(max(wfmt, len(c)) if show_cols else wfmt, "R") for c in coln]
        fields = ([Field(twidth, "R")] if show_rows else []) + numfields
        n = len(fields)
        seps = [Sep() for _ in range(n + 1)]
        seps[n] = Sep(False, 0, 1)        # a blank after the last column (compat 1801)
        for k in range(1, n):
            seps[k] = Sep(False, 1, 1)
        vline = {"oneline", "eq", "rowtotal", "coltotal", "rctotal", "rows", "columns", "cells"}
        if show_rows and lines in vline and mat.cols:
            seps[1].line = True
        if lines in ("columns", "cells"):
            for k in range(1 if show_rows else 0, n):
                if k > 0:
                    seps[k].line = True
        if lines in ("coltotal", "rctotal") and mat.cols > 1:
            seps[n - 1].line = True
        if lines == "eq" and has_ceq:
            off = 1 if show_rows else 0
            for c in range(1, mat.cols):
                if ceq[c] != ceq[c - 1]:
                    seps[off + c].line = True
        if "left" in border:
            seps[0] = Sep(True, 0, 1)
        if "right" in border:
            seps[n] = Sep(True, 1, 0)

    rows: list[list[str]] = []
    spans: dict[int, list[tuple[int, int, str, str]]] = {}
    off = 1 if show_rows else 0
    eq_header = show_cols and has_ceq
    if eq_header:
        # the column equations: over each group of columns, or over its first column or each one
        cells = [""] * (off + mat.cols)
        start = 0
        for c in range(1, mat.cols + 1):
            if c == mat.cols or ceq[c] != ceq[start]:
                if showcoleq == "each":
                    for k in range(start, c):
                        cells[off + k] = ceq[k]
                else:
                    spans.setdefault(0, []).append((off + start, off + c - 1, ceq[start],
                                                    _SHOWCOLEQ[showcoleq]))
                start = c
        rows.append(cells)
    if show_cols and not (o.get("coleqonly") and has_ceq):
        header = [rowtitle] if show_rows else []
        rows.append(header + [c for c in coln])
    nh = len(rows)
    eq_rows: list[int] = []
    for r in range(mat.rows):
        if show_rows and has_req and (r == 0 or req[r] != req[r - 1]):
            eq_rows.append(len(rows))
            rows.append([req[r]] + [""] * mat.cols)
        # roweqonly: the rows keep only the line of their equation (compat 1910)
        stub = "" if o.get("roweqonly") and has_req else rown[r]
        cells = [stub[:fields[0].width]] if show_rows else []
        for c in range(mat.cols):
            cells.append("" if half and c > r else text(mat.data[r, c], numfmts[c]))
        rows.append(cells)
    # widths of the columns from the cspec/format are kept; names longer than the field are cut
    rules = [False] * (len(rows) + 1)
    if o.get("rspec"):
        spec = re.sub(r"\s", "", str(o["rspec"]))
        if len(spec) != len(rows) + 1 or set(spec) - set("-|&"):
            raise StataError(198, "option rspec() incorrectly specified")     # VERIFY
        rules = [ch in "-|" for ch in spec]
    else:
        if "top" in border:
            rules[0] = True
        if "bottom" in border:
            rules[-1] = True
        if lines in ("oneline", "eq", "rowtotal", "coltotal", "rctotal", "columns", "cells",
                     "rows") and nh and len(rows) > nh:
            rules[nh] = True
        if lines == "eq":
            for k in eq_rows[1:]:
                rules[k] = True
        if lines in ("rows", "cells"):
            for k in range(1 + nh, len(rows)):
                rules[k] = True
        if lines in ("rowtotal", "rctotal") and len(rows) - nh > 1:
            rules[len(rows) - 1] = True
    # column names are aligned as asked (default: right)
    if show_cols:
        for k in range(mat.cols):
            rows[nh - 1][off + k] = align(rows[nh - 1][off + k], fields[off + k].width, how)
    out = s.output
    if not o.get("noblank"):
        out.write("\n", "text")
    if title:
        out.write(" " * tindent + title + "\n", "text")
    for line in render_table(rows, fields, seps, rules, left=left,
                             limit=linesize - right, repeat=1 if show_rows else 0, spans=spans,
                             groups=[None] * off + ceq if (o.get("keepcoleq") or has_ceq) else None,
                             flush=set(eq_rows), body=nh if half else None):
        out.write(line + "\n", "text")

files.opendta/commands/matrix.py:
"""matrix ([P] matrix): definition, operators, functions, listing and names.

Matrices live in s.matrices (and in r()/e() as results). Values are
float64 with OpenDTA's missing codes; in computations, missing becomes NaN
and goes back to '.' at the end (extended missing values become '.').

Matrix expressions:

    A + B   A - B   A * B (product or scalar)   A # B (Kronecker)
    A / k   -A   A'   (A, B) joins columns   (A \\ B) joins rows
    J(r,c,z) I(n) inv() invsym() cholesky() diag() vecdiag() hadamard()
    corr() vec() nullmat() matuniform(r,c)   A[i..j, k...]   r(name) e(name)

In ordinary expressions: A[i,j], el(A,i,j), rowsof(), colsof(), trace(),
det(), issymmetric(), rownumb(), colnumb(), matmissing(), mreldif().
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import TYPE_CHECKING

import numpy as np

from ..core import missing as M
from ..core.errors import StataError
from ..core.formats import format_value, parse_format
from ..lang.syntax import match_options
from .registry import command

if TYPE_CHECKING:
    from ..session import Session


@dataclass
class Matrix:
    data: np.ndarray
    rownames: list[str] = field(default_factory=list)
    colnames: list[str] = field(default_factory=list)
    roweq: list[str] = field(default_factory=list)       # "_" = no equation
    coleq: list[str] = field(default_factory=list)

    def __post_init__(self) -> None:
        self.data = np.atleast_2d(np.asarray(self.data, dtype=np.float64))
        r, c = self.data.shape
        if len(self.rownames) != r:
            self.rownames = [f"r{i}" for i in range(1, r + 1)]
        if len(self.colnames) != c:
            self.colnames = [f"c{j}" for j in range(1, c + 1)]
        if len(self.roweq) != r:
            self.roweq = ["_"] * r
        if len(self.coleq) != c:
            self.coleq = ["_"] * c

    @property
    def rows(self) -> int:
        return int(self.data.shape[0])

    @property
    def cols(self) -> int:
        return int(self.data.shape[1])

    def copy(self) -> "Matrix":
        return Matrix(self.data.copy(), list(self.rownames), list(self.colnames),
                      list(self.roweq), list(self.coleq))


def _store(s: "Session") -> dict[str, Matrix]:
    if not hasattr(s, "matrices"):
        s.matrices = {}
    return s.matrices


def _nan(a: np.ndarray) -> np.ndarray:
    out = np.array(a, dtype=np.float64)
    out[out >= M.SYSMISS] = np.nan
    return out


def _miss(a: np.ndarray) -> np.ndarray:
    out = np.array(a, dtype=np.float64)
    bad = ~np.isfinite(out) | (np.abs(out) >= M.SYSMISS)
    out[bad] = M.SYSMISS
    return out


def get_matrix(s: "Session", name: str) -> Matrix:
    name = name.strip()
    m = re.fullmatch(r"([re])\((\w+)\)", name)
    if m:
        store = s.r if m.group(1) == "r" else s.e
        v = store.get(m.group(2))
        if isinstance(v, Matrix):
            return v
        raise StataError(111, f"matrix {name} not found")
    mat = _store(s).get(name)
    if mat is None:
        raise StataError(111, f"matrix {name} not found")
    return mat


def matrix_names(s: "Session", name: str, which: str) -> str:
    mat = get_matrix(s, name)
    row = which.startswith("row")
    names, eqs = (mat.rownames, mat.roweq) if row else (mat.colnames, mat.coleq)
    if which.endswith("eq"):
        return " ".join(eqs)
    if which.endswith("fullnames") and _has_eqs(eqs):
        return " ".join(f"{q}:{n}" for q, n in zip(eqs, names))
    return " ".join(names)


def _has_eqs(eqs: list[str]) -> bool:
    return any(q != "_" for q in eqs)


# ---------------------------------------------------------------------------
# matrix expressions
# ---------------------------------------------------------------------------

_TOKEN = re.compile(r"""
    (?P<num>\d+\.?\d*(?:[eE][+-]?\d+)?|\.\d+(?:[eE][+-]?\d+)?)
  | (?P<res>[re]\(\w+\))
  | (?P<name>[A-Za-z_][A-Za-z0-9_]*)
  | (?P<range>\.\.\.|\.\.)
  | (?P<miss>\.[a-z]?)
  | (?P<str>"[^"]*")
  | (?P<op>[-+*#/'\\,()\[\]^])
  | (?P<ws>\s+)
""", re.X)

_MATFUNCS = {"J", "I", "inv", "invsym", "cholesky", "diag", "vecdiag", "hadamard", "corr", "vec",
             "nullmat", "matuniform", "get"}


class _Parser:
    def __init__(self, s: "Session", text: str):
        self.s = s
        self.text = text
        self.toks: list[tuple[str, str, int]] = []
        pos = 0
        while pos < len(text):
            m = _TOKEN.match(text, pos)
            if not m:
                raise StataError(198, "invalid syntax")
            kind = m.lastgroup
            if kind != "ws":
                self.toks.append((kind, m.group(0), pos))
            pos = m.end()
        self.toks.append(("end", "", len(text)))
        self.i = 0

    @property
    def tok(self):
        return self.toks[self.i]

    def take(self):
        t = self.toks[self.i]
        self.i += 1
        return t

    def is_op(self, v: str) -> bool:
        return self.tok[0] == "op" and self.tok[1] == v

    def expect(self, v: str) -> None:
        if not self.is_op(v):
            raise StataError(198, "invalid syntax")
        self.i += 1

    def parse(self) -> Matrix:
        m = self.joined()             # A \ B and A, B also work outside parentheses
        if self.tok[0] != "end":
            raise StataError(198, "invalid syntax")
        return m

    def expr(self) -> Matrix:
        left = self.term()
        while self.is_op("+") or self.is_op("-"):
            op = self.take()[1]
            right = self.term()
            left = _add(left, right, op)
        return left

    def term(self) -> Matrix:
        left = self.unary()
        while self.is_op("*") or self.is_op("#") or self.is_op("/"):
            op = self.take()[1]
            right = self.unary()
            if op == "*":
                left = _mul(left, right)
            elif op == "#":
                d = _miss(np.kron(_nan(left.data), _nan(right.data)))
                left = Matrix(d)
            else:
                if right.data.shape != (1, 1):
                    raise StataError(503, "conformability error")
                left = Matrix(_miss(_nan(left.data) / _nan(right.data)[0, 0]),
                              left.rownames, left.colnames)
        return left

    def unary(self) -> Matrix:
        if self.is_op("-"):
            self.take()
            m = self.unary()
            return Matrix(_miss(-_nan(m.data)), m.rownames, m.colnames)
        if self.is_op("+"):
            self.take()
            return self.unary()
        return self.power()

    def power(self) -> Matrix:
        """x^y only between scalars (1 x 1), as inside (`i', `i'^2)."""
        base = self.postfix()
        if self.is_op("^"):
            self.take()
            exp = self.unary()
            if base.data.shape != (1, 1) or exp.data.shape != (1, 1):
                raise StataError(503, "conformability error")
            x = self.s.eval(f"({float(base.data[0, 0])!r})^({float(exp.data[0, 0])!r})") \
                if base.data[0, 0] < M.SYSMISS and exp.data[0, 0] < M.SYSMISS else M.SYSMISS
            return Matrix(np.array([[float(x)]]))
        return base

    def postfix(self) -> Matrix:
        m = self.primary()
        while True:
            if self.is_op("'"):
                self.take()
                m = Matrix(m.data.T.copy(), list(m.colnames), list(m.rownames))
            elif self.is_op("["):
                m = self.submatrix(m)
            else:
                return m

    def primary(self) -> Matrix:
        kind, val, pos = self.tok
        if self.is_op("("):
            self.take()
            m = self.joined()
            self.expect(")")
            return m
        if kind == "num":
            self.take()
            return Matrix(np.array([[float(val)]]))
        if kind == "miss":
            self.take()
            return Matrix(np.array([[M.missing_code(val)]]))
        if kind == "res":
            self.take()
            return get_matrix(self.s, val).copy()
        if kind == "name":
            nxt = self.toks[self.i + 1]
            if nxt[0] == "op" and nxt[1] == "(":
                return self.function()
            if val in _store(self.s):
                self.take()
                return _store(self.s)[val].copy()
            # named scalar (scalar, variable in the 1st obs.)
            self.take()
            x = self.s.eval(val)
            if isinstance(x, str):
                raise StataError(109, "type mismatch")
            return Matrix(np.array([[float(x)]]))
        raise StataError(198, "invalid syntax")

    def joined(self) -> Matrix:
        """Inside parentheses: ',' joins columns and '\\' joins rows.
        nullmat() of a nonexistent matrix drops out of the join."""
        rows = [self.row()]
        while self.is_op("\\"):
            self.take()
            rows.append(self.row())
        rows = [r for r in rows if not isinstance(r, _Empty)] or [_Empty()]
        if len(rows) == 1:
            return rows[0]
        cols = {r.cols for r in rows}
        if len(cols) != 1:
            raise StataError(503, "conformability error")
        names = [n for r in rows for n in r.rownames]
        return Matrix(np.vstack([r.data for r in rows]),
                      names if len(set(names)) == len(names) and not _default(names, "r") else [],
                      rows[0].colnames)

    def row(self) -> Matrix:
        parts = [self.expr()]
        while self.is_op(","):
            self.take()
            parts.append(self.expr())
        parts = [p for p in parts if not isinstance(p, _Empty)] or [_Empty()]
        if len(parts) == 1:
            return parts[0]
        nrows = {p.rows for p in parts}
        if len(nrows) != 1:
            raise StataError(503, "conformability error")
        names = [n for p in parts for n in p.colnames]
        return Matrix(np.hstack([p.data for p in parts]), parts[0].rownames,
                      names if len(set(names)) == len(names) and not _default(names, "c") else [])

    def function(self) -> Matrix:
        name = self.take()[1]
        self.expect("(")
        start = self.tok[2]
        depth = 1
        args_raw: list[str] = []
        arg_start = start
        while True:
            kind, val, pos = self.tok
            if kind == "end":
                raise StataError(132, "too many '(' or '['")
            if kind == "op" and val == "(":
                depth += 1
            elif kind == "op" and val == ")":
                depth -= 1
                if depth == 0:
                    args_raw.append(self.text[arg_start:pos])
                    self.take()
                    break
            elif kind == "op" and val == "," and depth == 1:
                args_raw.append(self.text[arg_start:pos])
                arg_start = pos + 1
            self.take()
        args = [a.strip() for a in args_raw if a.strip() or len(args_raw) > 1]
        return _call(self.s, name, args)

    def submatrix(self, m: Matrix) -> Matrix:
        self.expect("[")
        start = self.tok[2]
        depth = 1
        while True:
            kind, val, pos = self.tok
            if kind == "end":
                raise StataError(198, "invalid syntax")
            if kind == "op" and val == "[":
                depth += 1
            if kind == "op" and val == "]":
                depth -= 1
                if depth == 0:
                    inner = self.text[start:pos]
                    self.take()
                    break
            self.take()
        parts = _split_top(inner, ",")
        if len(parts) != 2:
            raise StataError(198, "invalid syntax")
        ri = _index_range(self.s, parts[0], m.rownames)
        ci = _index_range(self.s, parts[1], m.colnames)
        return Matrix(m.data[np.ix_(ri, ci)], [m.rownames[i] for i in ri],
                      [m.colnames[j] for j in ci])


def _default(names: list[str], prefix: str) -> bool:
    return all(re.fullmatch(prefix + r"\d+", n) for n in names)


def _split_top(text: str, sep: str) -> list[str]:
    out, depth, cur, q = [], 0, "", False
    for ch in text:
        if ch == '"':
            q = not q
        if not q:
            if ch in "([":
                depth += 1
            elif ch in ")]":
                depth -= 1
            elif ch == sep and depth == 0:
                out.append(cur)
                cur = ""
                continue
        cur += ch
    out.append(cur)
    return out


def _index_range(s: "Session", text: str, names: list[str]) -> list[int]:
    t = text.strip()
    n = len(names)

    def one(x: str) -> int:
        x = x.strip()
        if x.startswith('"'):
            label = x.strip('"')
            if label not in names:
                raise StataError(111, f"{label} not found")
            return names.index(label) + 1
        v = s.eval(x)
        return int(v)

    if "..." in t:
        a = one(t.split("...")[0])
        b = n
    elif ".." in t:
        a_txt, b_txt = t.split("..", 1)
        a, b = one(a_txt), one(b_txt)
    else:
        a = b = one(t)
    if not (1 <= a <= n and 1 <= b <= n and a <= b):
        raise StataError(503, "conformability error")
    return list(range(a - 1, b))


def _add(a: Matrix, b: Matrix, op: str) -> Matrix:
    if a.data.shape != b.data.shape:
        raise StataError(503, "conformability error")
    d = _nan(a.data) + _nan(b.data) if op == "+" else _nan(a.data) - _nan(b.data)
    return Matrix(_miss(d), a.rownames, a.colnames)


def _mul(a: Matrix, b: Matrix) -> Matrix:
    if a.data.shape == (1, 1) and b.data.shape != (1, 1):
        return Matrix(_miss(_nan(b.data) * _nan(a.data)[0, 0]), b.rownames, b.colnames)
    if b.data.shape == (1, 1) and a.data.shape != (1, 1):
        return Matrix(_miss(_nan(a.data) * _nan(b.data)[0, 0]), a.rownames, a.colnames)
    if a.cols != b.rows:
        raise StataError(503, "conformability error")
    return Matrix(_miss(_nan(a.data) @ _nan(b.data)), a.rownames, b.colnames)


def _scalar(s: "Session", text: str) -> float:
    v = s.eval(text)
    if isinstance(v, str):
        raise StataError(109, "type mismatch")
    return float(v)


def _mat_arg(s: "Session", text: str) -> Matrix:
    return _Parser(s, text).parse()


def _call(s: "Session", name: str, args: list[str]) -> Matrix:
    if name not in _MATFUNCS:
        # scalar function: becomes a 1 x 1 matrix
        x = _scalar(s, f"{name}({', '.join(args)})")
        return Matrix(np.array([[x]]))
    if name == "J":
        if len(args) != 3:
            raise StataError(198, "invalid syntax")
        r, c = int(_scalar(s, args[0])), int(_scalar(s, args[1]))
        return Matrix(np.full((r, c), _scalar(s, args[2])))
    if name == "I":
        n = int(_scalar(s, args[0]))
        return Matrix(np.eye(n))
    if name == "matuniform":
        r, c = int(_scalar(s, args[0])), int(_scalar(s, args[1]))
        return Matrix(np.random.default_rng().random((r, c)))
    if name == "nullmat":
        nm = args[0].strip()
        if nm in _store(s):
            return _store(s)[nm].copy()
        return _Empty()
    a = _mat_arg(s, args[0])
    if name in ("inv", "invsym"):
        if a.rows != a.cols:
            raise StataError(505, "matrix not symmetric" if name == "invsym" else "matrix not square")
        x = _nan(a.data)
        try:
            d = np.linalg.inv(x)
        except np.linalg.LinAlgError:
            if name == "inv":
                raise StataError(504, "matrix has missing values" if np.isnan(x).any()
                                 else "matrix not positive definite")   # VERIFY
            d = np.linalg.pinv(x)   # VERIFY: o Stata zera linhas/colunas dependentes
        return Matrix(_miss(d), list(a.colnames), list(a.rownames))
    if name == "cholesky":
        try:
            d = np.linalg.cholesky(_nan(a.data))
        except np.linalg.LinAlgError:
            raise StataError(506, "matrix not positive definite")
        return Matrix(d, a.rownames, a.colnames)
    if name == "diag":
        v = a.data.ravel()
        names = a.colnames if a.rows == 1 else a.rownames
        return Matrix(np.diag(v), names, names)
    if name == "vecdiag":
        if a.rows != a.cols:
            raise StataError(505, "matrix not square")
        return Matrix(np.diag(a.data)[None, :], ["r1"], list(a.colnames))
    if name == "hadamard":
        b = _mat_arg(s, args[1])
        if a.data.shape != b.data.shape:
            raise StataError(503, "conformability error")
        return Matrix(_miss(_nan(a.data) * _nan(b.data)), a.rownames, a.colnames)
    if name == "corr":
        d = np.sqrt(np.diag(_nan(a.data)))
        return Matrix(_miss(_nan(a.data) / np.outer(d, d)), a.rownames, a.colnames)
    if name == "vec":
        col = a.data.T.reshape(-1, 1)
        names = [f"{c}:{r}" for c in a.colnames for r in a.rownames]
        return Matrix(col, names, ["c1"])
    raise StataError(133, f"unknown function {name}()")


class _Empty(Matrix):
    """nullmat() of a nonexistent matrix: the neutral element of the join."""

    def __init__(self):
        self.data = np.zeros((0, 0))
        self.rownames, self.colnames = [], []


def evaluate_matrix(s: "Session", text: str) -> Matrix:
    m = _Parser(s, text).parse()
    if isinstance(m, _Empty):
        raise StataError(503, "conformability error")
    return m


# ---------------------------------------------------------------------------
# scalar functions of matrices (used by the expression evaluator)
# ---------------------------------------------------------------------------

MATRIX_SCALAR_FUNCS = {"rowsof", "colsof", "el", "trace", "det", "issymmetric", "rownumb",
                       "colnumb", "matmissing", "mreldif"}


def matrix_scalar(s: "Session", name: str, args: list, eval_arg) -> float:
    """args: expression nodes; the 1st (and the 2nd in mreldif) is a matrix name."""
    from ..lang.expr import Name, Call

    def mat(node) -> Matrix:
        if isinstance(node, Name):
            return get_matrix(s, node.name)
        if isinstance(node, Call) and node.name in ("r", "e"):
            return get_matrix(s, f"{node.name}({node.raw})")
        raise StataError(198, "invalid syntax")

    a = mat(args[0])
    if name == "rowsof":
        return float(a.rows)
    if name == "colsof":
        return float(a.cols)
    if name == "el":
        i, j = int(eval_arg(args[1])), int(eval_arg(args[2]))
        if 1 <= i <= a.rows and 1 <= j <= a.cols:
            return float(a.data[i - 1, j - 1])
        return M.SYSMISS
    if name == "trace":
        if a.rows != a.cols:
            raise StataError(505, "matrix not square")
        return float(_miss(np.array([np.trace(_nan(a.data))]))[0])
    if name == "det":
        if a.rows != a.cols:
            raise StataError(505, "matrix not square")
        return float(_miss(np.array([np.linalg.det(_nan(a.data))]))[0])
    if name == "issymmetric":
        return 1.0 if a.rows == a.cols and np.array_equal(a.data, a.data.T) else 0.0
    if name in ("rownumb", "colnumb"):
        label = eval_arg(args[1])
        names = a.rownames if name == "rownumb" else a.colnames
        return float(names.index(label) + 1) if label in names else M.SYSMISS
    if name == "matmissing":
        return 1.0 if (a.data >= M.SYSMISS).any() else 0.0
    if name == "mreldif":
        b = mat(args[1])
        if a.data.shape != b.data.shape:
            return M.SYSMISS
        x, y = _nan(a.data), _nan(b.data)
        return float(np.nanmax(np.abs(x - y) / (np.abs(y) + 1)))
    raise StataError(133, f"unknown function {name}()")


def matrix_element(s: "Session", name: str, i: float, j: float) -> float:
    a = get_matrix(s, name)
    i, j = int(i), int(j)
    if 1 <= i <= a.rows and 1 <= j <= a.cols:
        return float(a.data[i - 1, j - 1])
    raise StataError(503, "conformability error")   # VERIFY


# ---------------------------------------------------------------------------
# matrix list
# ---------------------------------------------------------------------------

def list_matrix(s: "Session", title: str, mat: Matrix, fmt: str = "%10.0g",
                *, names: bool = True, header: bool = True, show_title: str = "") -> None:
    out = s.output
    f = parse_format(fmt)
    # a 1x1 matrix is listed as symmetric (e(V) in compat/expected/0514_fweight_robust.log;
    # VERIFY for matrices defined by the user)
    sym = mat.rows == mat.cols and np.array_equal(mat.data, mat.data.T)
    cells = [[format_value(float(x), f, pad=False).strip() if x < M.SYSMISS
              else M.missing_name(float(x)) for x in row] for row in mat.data]
    # equation names: "eq:name" on the rows and an "eq:" line above the column names
    # (compat/expected/0514_fweight_robust.log)
    rlab = ([f"{q}:{n}" for q, n in zip(mat.roweq, mat.rownames)] if _has_eqs(mat.roweq)
            else list(mat.rownames))
    ceqs = [f"{q}:" for q in mat.coleq] if names and _has_eqs(mat.coleq) else []
    rw = max([len(n) for n in rlab] + [0]) if names else 0
    shown = [cells[i][j] for i in range(mat.rows) for j in range(mat.cols) if not sym or i >= j]
    # names with operators (1b.k, L.x) take two lines: "1b." above "k"
    split = names and any("." in c for c in mat.colnames)
    if split:
        heads = [(c[: c.rfind(".") + 1], c[c.rfind(".") + 1:]) if "." in c else ("", c)
                 for c in mat.colnames]
    else:
        heads = [("", c) for c in mat.colnames]
    # all columns as wide as the largest value or name (observed in Stata 14,
    # compat/expected/0203_matrix.log)
    w_all = max([max(len(a), len(b)) for a, b in heads] if names else [0])
    w_all = max([w_all] + [len(q) for q in ceqs])          # "a:" counts with its colon (compat 1910)
    w_all = max([w_all] + [len(c) for c in shown])
    widths = [w_all] * mat.cols
    if header:
        lead = "symmetric " if sym else ""
        extra = f":  {show_title}" if show_title else ""
        out.write(f"\n{lead}{title}[{mat.rows},{mat.cols}]{extra}\n", "text")
    if names:
        if ceqs:
            # like the operator part, the equation sits one column to the right
            line = " " * (rw + 1) + "".join("  " + q.rjust(w) for q, w in zip(ceqs, widths))
            out.write(line.rstrip() + "\n", "text")
        if split:
            # the operator part sits one column to the right (compat 0502)
            line = " " * (rw + 1) + "".join("  " + a.rjust(w) for (a, _), w in zip(heads, widths))
            out.write(line.rstrip() + "\n", "text")
        line = " " * rw + "".join("  " + b.rjust(w) for (_, b), w in zip(heads, widths))
        out.write(line + "\n", "text")
    for i in range(mat.rows):
        out.write((rlab[i].rjust(rw) if names else ""), "text")
        last = i + 1 if sym else mat.cols
        out.write("".join("  " + cells[i][j].rjust(widths[j]) for j in range(last)) + "\n", "result")


# ---------------------------------------------------------------------------
# comando matrix
# ---------------------------------------------------------------------------

_NAME = re.compile(r"[A-Za-z_][A-Za-z0-9_]{0,31}")


def _define(s: "Session", text: str) -> None:
    m = re.match(r"\s*([A-Za-z_][A-Za-z0-9_]*)\s*(\[(.*?)\])?\s*=\s*(.*)$", text, re.S)
    if not m:
        raise StataError(198, "invalid syntax")
    name, sub, rhs = m.group(1), m.group(3), m.group(4).strip()
    if sub is not None:
        # matrix A[i,j] = exp
        mat = get_matrix(s, name)
        parts = _split_top(sub, ",")
        if len(parts) != 2:
            raise StataError(198, "invalid syntax")
        i, j = int(_scalar(s, parts[0])), int(_scalar(s, parts[1]))
        if not (1 <= i <= mat.rows and 1 <= j <= mat.cols):
            raise StataError(503, "conformability error")
        x = _scalar(s, rhs)
        mat.data[i - 1, j - 1] = x
        return
    value = evaluate_matrix(s, rhs)
    store = _store(s)
    store.pop(name, None)       # redefining counts as the most recent (matrix dir)
    store[name] = value


def _input(s: "Session", text: str) -> None:
    m = re.match(r"\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*\((.*)\)\s*$", text, re.S)
    if not m:
        raise StataError(198, "invalid syntax")
    rows = []
    for row in m.group(2).split("\\"):
        vals = []
        for cell in row.replace(",", " ").split():
            if cell == "." or re.fullmatch(r"\.[a-z]", cell):
                vals.append(M.missing_code(cell))
            else:
                try:
                    vals.append(float(cell))
                except ValueError:
                    raise StataError(198, "invalid syntax")
        rows.append(vals)
    if len({len(r) for r in rows}) != 1:
        raise StataError(503, "conformability error")
    _store(s)[m.group(1)] = Matrix(np.array(rows))


def _names_cmd(s: "Session", which: str, text: str) -> None:
    m = re.match(r"\s*(\S+)\s*=\s*(.*)$", text, re.S)
    if not m:
        raise StataError(198, "invalid syntax")
    mat = get_matrix(s, m.group(1))
    names = m.group(2).split()
    n = mat.rows if which.startswith("row") else mat.cols
    if len(names) != n:
        raise StataError(503, "conformability error")
    if which == "roweq":
        mat.roweq = names
    elif which == "coleq":
        mat.coleq = names
    else:
        # "eq:name" sets the equation as well (VERIFY: a name without a colon keeps the equation)
        eqs = list(mat.roweq if which.startswith("row") else mat.coleq) or ["_"] * n
        for k, nm in enumerate(names):
            if ":" in nm:
                eqs[k], names[k] = nm.split(":", 1)
                names[k] = names[k] or "_cons"                                  # VERIFY
        if which.startswith("row"):
            mat.rownames, mat.roweq = names, eqs
        else:
            mat.colnames, mat.coleq = names, eqs


@command("matrix", "mat")
def cmd_matrix(s: "Session", args: str) -> None:
    t = args.strip()
    sub, _, rest = t.partition(" ")
    if re.match(r"\s*(=|\[)", rest) or "=" in sub or "[" in sub:
        _define(s, t)                 # matrix d = ...: "d" is the name, not define
        return
    if sub in ("define", "def", "de", "defi", "defin", "d"):
        _define(s, rest)
        return
    if sub in ("input", "in", "inp", "inpu"):
        _input(s, rest)
        return
    if sub in ("list", "l", "li", "lis"):
        head, comma, opts = rest.partition(",")
        o = match_options(opts, {"format": 3, "title": 3, "nonames": 7, "noheader": 8,
                                 "nohalf": 6, "nodotz": 6}) if comma else {}
        name = head.strip()
        mat = get_matrix(s, name)
        fmt = str(o.get("format", "%10.0g")).strip()
        list_matrix(s, name, mat, fmt, names=not o.get("nonames"), header=not o.get("noheader"),
                    show_title=str(o.get("title", "")).strip().strip('"'))
        return
    if sub in ("drop", "drop"):
        names = rest.split()
        store = _store(s)
        if names in (["_all"], []):
            store.clear()
            return
        for n in names:
            if n not in store:
                raise StataError(111, f"matrix {n} not found")
            del store[n]
        return
    if sub in ("dir",):
        # from the most recent to the oldest, names aligned in 13 columns
        for n, mat in reversed(list(_store(s).items())):
            s.output.write(f"{n:>13}[{mat.rows},{mat.cols}]\n", "text")
        return
    if sub in ("dissimilarity", "dissim", "dissimi", "dissimil", "dissimila", "dissimilar", "dissimilari", "dissimilarit"):
        from .mvcluster import matrix_dissimilarity
        matrix_dissimilarity(s, rest)
        return
    if sub in ("rename", "ren"):
        a, b = rest.split()
        store = _store(s)
        store[b] = get_matrix(s, a)
        del store[a]
        return
    if sub in ("rownames", "colnames", "roweq", "coleq", "rown", "coln"):
        _names_cmd(s, {"rown": "rownames", "coln": "colnames"}.get(sub, sub), rest)
        return
    if re.match(r"dispCns\b", t):
        from .estprog import dispcns
        dispcns(s, t[len("dispCns"):])
        return
    # matrix A = ...
    _define(s, t)


# ---------------------------------------------------------------------------
# return/ereturn matrix
# ---------------------------------------------------------------------------

def take_matrix(s: "Session", text: str) -> tuple[str, Matrix]:
    """return matrix name = matrix [, copy]: the matrix leaves s.matrices."""
    head, comma, opts = text.partition(",")
    m = re.match(r"\s*([A-Za-z_]\w*)\s*=\s*(\S+)\s*$", head)
    if not m:
        raise StataError(198, "invalid syntax")
    copy = comma and "copy" in opts
    mat = get_matrix(s, m.group(2))
    if not copy and m.group(2) in _store(s):
        del _store(s)[m.group(2)]
    return m.group(1), (mat.copy() if copy else mat)


def ereturn_matrix(s: "Session", sub: str, rest: str) -> None:
    if sub in ("matrix", "mat"):
        name, mat = take_matrix(s, rest)
        s.e[name] = mat
        return
    if sub in ("post", "repost"):
        head, comma, opts = rest.partition(",")
        names = head.split()
        if sub == "post":
            s.e = {}
        if names:
            b = get_matrix(s, names[0])
            s.e["b"] = b.copy()
            _store(s).pop(names[0], None)
        if len(names) > 1:
            V = get_matrix(s, names[1])
            s.e["V"] = V.copy()
            _store(s).pop(names[1], None)
        for m in re.finditer(r"(depname|obs|dof)\(([^)]*)\)", opts if comma else ""):
            key, val = m.group(1), m.group(2).strip()
            if key == "depname":
                s.e["depvar"] = val
            else:
                s.e["N" if key == "obs" else "df_r"] = float(s.eval(val))
        return
    raise StataError(198, "ereturn display arrives with the estimation commands (phase 5)")

