"""power cmh, power mcc and power trend ([PSS] power cmh, power mcc, power trend): stratified and
matched 2x2 tables and the trend test. The formulas are in core/power_suites.py."""

from __future__ import annotations

import math
import re

import numpy as np

from ..core import power_suites as C
from ..core.errors import StataError
from . import power as P
from .matrix import get_matrix
from .power3_base import _I, _M, _N, _SOLVER, _fail, _solver_vals, _store


def _probspec(s, body: str):
    """Probabilities per group: numbers or (numlist) per stratum, or a matrix (one row per
    scenario). Returns (list of value lists per column, or list of rows of a matrix)."""
    toks = P._split_args(body)
    if len(toks) == 1 and re.fullmatch(r"[A-Za-z_]\w*", toks[0]):
        m = np.array(get_matrix(s, toks[0]).data, dtype=float)
        return None, [list(r) for r in m]
    return [P._values(t) for t in toks], None


class CMH(_M):
    method = "cmh"
    allowed = {"oratio", "nperstratum", "strweights", "grratios", "continuity", "direction",
               "onesided", "showgrstrsizes"}

    def __init__(self, s, body, o):
        super().__init__(s, body, o)
        self.cols, self.rows = _probspec(s, body)
        self.iterates = not self.flag("onesided")       # Stata 14 prints no iteration message when onesided
        self.K = len(self.cols) if self.cols is not None else len(self.rows[0])
        if self.K < 2:
            _fail("at least two probabilities are required")
        self.sw = self.gr = None
        if o.get("strweights") not in (None, True):
            w = P._values(str(o["strweights"]))
            if len(w) != self.K or min(w) <= 0 or (not self.flag("nfractional") and
                                                      not np.allclose(w, np.round(w))):
                _fail("option strweights() incorrectly specified")
            self.sw = C.standard_weights(w)
        if o.get("grratios") not in (None, True):
            g = P._values(str(o["grratios"]))
            if len(g) != self.K or min(g) <= 0 or max(g) >= 1:
                _fail("option grratios() incorrectly specified")
            self.gr = g
        if self.sw is not None and o.get("nperstratum"):
            _fail("nperstratum() and strweights() may not be combined")
        self.up_dir = not str(o.get("direction") or "upper").lower().startswith("l")

    def base(self):
        b = self.common()
        for k in ("oratio", "nperstratum"):
            v = self.vals(k)
            if v is not None:
                b[k] = v
        if self.cols is not None:
            for j, col in enumerate(self.cols):
                b[f"p1_{j + 1}"] = col
        else:
            b["_row"] = list(range(len(self.rows)))
        return b

    def title(self, what):
        what_ = {"n": "sample size", "power": "power", "effect": "odds ratio"}[what]
        return f"Estimated {what_} for a test of independence in stratified 2x2 tables"

    def hyp_lines(self, c, what):
        op = "!=" if self.sides() == 2 else (">" if (self.up_dir if what == "effect" else c["oratio"] > 1) else "<")
        extra = ", OR " + (">" if self.up_dir else "<") + " 1" if (what == "effect" and self.sides() == 2) else ""
        eq = " = ".join(["OR"] + [f"OR_{j + 1}" for j in range(self.K)])
        cmh = "Cochran-Mantel-Haenszel test" + (" with continuity correction" if self.flag("continuity") else "")
        return [cmh, f"Ho: OR = 1  versus  Ha: OR {op} 1{extra};  {eq}"]

    def p1(self, c):
        if self.cols is not None:
            return np.array([c[f"p1_{j + 1}"] for j in range(self.K)])
        return np.array(self.rows[c["_row"]])

    def compute(self, c):
        self.fix(c)
        K, a, sides, cont = self.K, c["alpha"], self.sides(), self.flag("continuity")
        p1 = self.p1(c)
        if ((p1 <= 0) | (p1 >= 1)).any():
            _fail("probabilities must be between 0 and 1")
        w = self.sw if self.sw is not None else [1.0] * K
        s_ = self.gr if self.gr is not None else [0.5] * K
        sw = sum(w)
        have_n = c.get("n") is not None or c.get("nperstratum") is not None
        theta = c.get("oratio")
        if theta is None:
            if not have_n:
                _fail("oratio() required")                   # VERIFY
            what = "effect"
            c.setdefault("power", 0.8)
        elif have_n:
            if c.get("power") is not None:
                _fail("only two of n(), power() and the effect size may be specified")
            what = "power"
        else:
            c.setdefault("power", 0.8)
            what = "n"

        def power_at(n1, n2, th, up=None):
            return C.cmh_power(n1, n2, p1, C.odds_probability(p1, th), a, sides, cont, up)

        def sizes_total(N):
            nk = np.array(w) * N / sw
            if np.allclose(s_, 0.5):
                return nk / 2, nk / 2
            n2 = nk * np.array(s_)
            return nk - n2, n2
        if what == "n":
            def pw(k):
                n1, n2 = C.cmh_sizes(w, s_, k, self.flag("nfractional"))
                return power_at(n1, n2, theta)
            k = self.size(pw, 1.0 / max(w), c["power"], exact=lambda k: power_at(*C.cmh_sizes(w, s_, k, True), theta))
            if self.exact is not None:
                c["N_a"] = self.exact * sw
            n1, n2 = C.cmh_sizes(w, s_, k, self.flag("nfractional"))
            c["power_out"] = pw(k)
            try:        # r(init) of Stata 14: the root when only the tail in the direction of the effect counts
                c["_init"] = sw * C.solve_up(lambda x: C.cmh_power(*C.cmh_sizes(w, s_, x, True), p1,
                                                                   C.odds_probability(p1, theta), a, sides, cont,
                                                                   tail=True) - c["power"], 1.0 / max(w), 4.0)
            except ValueError:
                c["_init"] = 1.0
        else:
            N = float(c["n"]) if c.get("n") is not None else K * c["nperstratum"]
            n1, n2 = sizes_total(N)
            if what == "power":
                c["power_out"] = power_at(n1, n2, theta)
            else:
                sgn = 1.0 if self.up_dir else -1.0
                try:
                    t = C.solve_up(lambda t: power_at(n1, n2, math.exp(sgn * t), self.up_dir) - c["power"],
                                   1e-9, 1.0)
                except ValueError:
                    raise StataError(498, "failed to find a solution")
                theta = math.exp(sgn * t)
                c["power_out"], c["_init"] = c["power"], 1.0
        c["oratio"], c["n1k"], c["n2k"], c["p1"] = theta, np.array(n1), np.array(n2), p1
        c["N"] = float(np.sum(n1) + np.sum(n2))
        c["delta"] = theta
        nk = c["n1k"] + c["n2k"]
        c["eq_strata"] = bool(np.allclose(nk, nk[0]))
        c["eq_groups"] = bool(abs(c["n1k"].sum() - c["n2k"].sum()) < 1e-9)
        c["balanced"] = c["eq_strata"] and bool(np.allclose(c["n1k"], c["n2k"]))
        return what

    def sizes(self, c):
        items = [("N", _I(c["N"]))]
        nk = c["n1k"] + c["n2k"]
        if c["eq_strata"]:
            items.append(("N per stratum", _I(nk[0])))
        else:
            items += [(f"N{j + 1}", _I(v)) for j, v in enumerate(nk)]
        if c["eq_groups"]:
            items.append(("N per group", _N(c["n1k"].sum())))
        else:
            items += [("N group 1", _I(c["n1k"].sum())), ("N group 2", _I(c["n2k"].sum()))]
        if c["balanced"]:
            items.append(("N per group/stratum", _N(c["n1k"][0])))
        return items

    def show(self, c, what):
        items = [("alpha", P._f4(c["alpha"]))]
        if what != "power":
            items.append(("power", P._f4(c["power"])))
        if what != "n":
            items += self.sizes(c)
        if what != "effect":
            items.append(("delta", P._f4(c["delta"])))
        items.append(("N_s", _I(self.K)))
        items += [(f"p1_{j + 1}", P._f4(v)) for j, v in enumerate(c["p1"])]
        if what != "effect":
            items.append(("oratio", P._f4(c["oratio"])))
        if what == "n":
            tail = ("Estimated sample sizes:", self.sizes(c))
        elif what == "power":
            tail = ("Estimated power:", [("power", P._f4(c["power_out"]))])
        else:
            tail = ("Estimated effect size and odds ratio:",
                    [("delta", P._f4(c["delta"])), ("odds ratio", P._f4(c["oratio"]))])
        self.fit_width(items + tail[1])
        self.put(items)
        self.results(*tail)
        if not c["balanced"] and what == "n":
            self.grstr(c)
        self.returns(c, what)

    def grstr(self, c):
        out = self.s.output
        out.write("\nGroup-per-stratum sample sizes:\n", "text")
        out.write(" " * 15 + "| stratum\n", "text")
        out.write(" " * 15 + "|" + "".join(f"{j + 1:>{9 if j == 0 else 10}}" for j in range(self.K)) + "\n", "text")
        out.write("  " + "-" * 13 + "+" + "-" * (10 * self.K) + "\n", "text")
        out.write("  group".ljust(15) + "|\n", "text")
        for g, arr in ((1, c["n1k"]), (2, c["n2k"])):
            out.write(f"{g:>14} |", "text")
            out.write("".join(f"{P._nfmt(v):>{9 if j == 0 else 10}}" for j, v in enumerate(arr)) + "\n", "result")

    def columns(self, c, what):
        cols = ["alpha", "power", "N", "N_per_stratum" if c["eq_strata"] else "N_avg"]
        if c["balanced"]:
            cols += ["N_per_group", "N_per_grstr"]
        return cols + ["delta", "N_s"] + [f"p1_{j + 1}" for j in range(self.K)] + ["oratio"]

    def row(self, c, what):
        d = {"alpha": c["alpha"], "power": c["power_out"] if what == "power" else c["power"],
             "N": c["N"], "N_per_stratum": c["N"] / self.K, "N_avg": c["N"] / self.K,
             "N_per_group": c["n1k"].sum(), "N_per_grstr": c["n1k"][0],
             "delta": c["delta"], "N_s": self.K, "oratio": c["oratio"]}
        d.update({f"p1_{j + 1}": v for j, v in enumerate(c["p1"])})
        return d

    _ORDER = (["oratio"] + [f"grratio{j}" for j in range(1, 4)] + ["continuity", "N_per_group", "N_per_grstr",
              "balanced", "N_per_stratum"] + _SOLVER + ["onesided", "nfractional", "delta", "alpha", "beta",
              "power", "N"] + [f"p1_{j}" for j in (3, 2, 1)] + ["N_a", "N_s", "N_avg", "type", "method"])

    def returns(self, c, what):
        pw = c["power_out"] if what == "power" else c["power"]
        N = c["N"]
        v = {"N": N, "N_avg": N / self.K, "N_a": c.get("N_a", N), "power": pw, "beta": 1 - pw,
             "alpha": c["alpha"], "delta": c["delta"], "nfractional": float(self.flag("nfractional")),
             "balanced": float(c["balanced"]), "onesided": float(self.sides() == 1),
             "N_per_group": c["n1k"].sum(), "N_s": float(self.K), "oratio": float(c["oratio"]),
             "continuity": float(self.flag("continuity"))}
        if c["eq_strata"]:
            v["N_per_stratum"] = N / self.K
        if c["balanced"]:
            v["N_per_grstr"] = c["n1k"][0]
        s_ = self.gr if self.gr is not None else [0.5] * self.K
        v.update({f"grratio{j + 1}": float(x) for j, x in enumerate(s_)})
        v.update({f"p1_{j + 1}": float(x) for j, x in enumerate(c["p1"])})
        v.update(_solver_vals(c))
        v.update({"type": "test", "method": "cmh"})
        _store(self.s, {k: (float(x) if not isinstance(x, str) else x) for k, x in v.items()}, self._ORDER)


class MCC(_M):
    method = "mcc"
    allowed = {"oratio", "m", "compare", "corr", "direction", "onesided"}

    def __init__(self, s, body, o):
        super().__init__(s, body, o)
        toks = P._split_args(body)
        if len(toks) != 1:
            _fail("p0 required")
        self.p0 = P._values(toks[0])
        self.up_dir = not str(o.get("direction") or "upper").lower().startswith("l")

    def base(self):
        b = self.common()
        b["p0"] = self.p0
        for k in ("oratio", "m", "corr"):
            v = self.vals(k)
            if v is not None:
                b[k] = v
        return b

    def title(self, what):
        w = {"n": "sample size", "power": "power", "effect": "odds ratio"}[what]
        return f"Estimated {w} for a matched case-control study"

    def hyp_lines(self, c, what):
        up = self.up_dir if what == "effect" else c["oratio"] > 1
        return [f"Asymptotic z test, 1:{int(c['M'])} matched design",
                f"Ho: OR = 1  versus  Ha: OR {self.hyp_op(c, up)} 1"]

    def compute(self, c):
        self.fix(c)
        a, sides = c["alpha"], self.sides()
        p0, rho, M = c["p0"], c.get("corr", 0.0), int(c.get("m", 1))
        if not 0 < p0 < 1 or M < 1 or not -1 <= rho <= 1:
            _fail("invalid argument value")                         # VERIFY
        c["M"], c["rho"] = M, rho
        theta = c.get("oratio")
        have_n = c.get("n") is not None
        if theta is None:
            if not have_n:
                _fail("oratio() required")
            what = "effect"
            c.setdefault("power", 0.8)
        elif have_n:
            if c.get("power") is not None:
                _fail("only two of n(), power() and the effect size may be specified")
            what = "power"
        else:
            c.setdefault("power", 0.8)
            what = "n"
        if self.flag("compare") and (what != "n" or M < 2):
            _fail("compare requires sample-size determination and m() of at least 2")   # VERIFY
        try:
            if what == "power":
                c["N"] = float(c["n"])
                c["power_out"] = C.mcc_power(c["N"], p0, theta, rho, M, a, sides)
            elif what == "n":
                c["N"] = self.size(lambda n: C.mcc_power(n, p0, theta, rho, M, a, sides), 1.0, c["power"])
                c["power_out"] = C.mcc_power(c["N"], p0, theta, rho, M, a, sides)
                c["_init"] = C.mcc_size_start(p0, theta, rho, M, a, sides, c["power"])
                if self.flag("compare"):
                    n1 = self.size(lambda n: C.mcc_power(n, p0, theta, rho, 1, a, sides), 1.0, c["power"])
                    c["F_M"] = c["N"] / n1                  # n_M / n_1 with the same corr() (checked, case 1919)
            else:
                sgn = 1.0 if self.up_dir else -1.0
                N = float(c["n"])
                t = C.solve_up(lambda t: C.mcc_power(N, p0, math.exp(sgn * t), rho, M, a, sides, self.up_dir)
                               - c["power"], 1e-9, 1.0)
                theta = math.exp(sgn * t)
                c["N"], c["power_out"], c["_init"] = N, c["power"], 1.0
        except ValueError as e:
            raise StataError(498, f"failed to find a solution: {e}")
        c["oratio"], c["delta"] = theta, theta               # delta is the odds ratio (checked, case 1919)
        c["N"] = float(c["N"])
        return what

    def show(self, c, what):
        items = [("alpha", P._f4(c["alpha"]))]
        if what != "power":
            items.append(("power", P._f4(c["power"])))
        if what != "n":
            items.append(("N cases", _I(c["N"])))
        if what != "effect":
            items += [("delta", P._f4(c["delta"])), ("p0", P._f4(c["p0"])), ("oratio", P._f4(c["oratio"]))]
        else:
            items.append(("p0", P._f4(c["p0"])))
        items += [("corr", P._f4(c["rho"])), ("M", _I(c["M"]))]
        self.put(items)
        if what == "n":
            res = [("N cases", _I(c["N"]))]
            if "F_M" in c:
                res.append(("F_M", P._f4(c["F_M"])))
            self.results("Estimated sample size:", res)
        elif what == "power":
            self.results("Estimated power:", [("power", P._f4(c["power_out"]))])
        else:
            self.results("Estimated effect size and odds ratio:",
                         [("delta", P._f4(c["delta"])), ("odds ratio", P._f4(c["oratio"]))])
        self.returns(c, what)

    def columns(self, c, what):
        return ["alpha", "power", "N", "delta", "M", "p0", "oratio", "corr"]

    def row(self, c, what):
        return {"alpha": c["alpha"], "power": c["power_out"] if what == "power" else c["power"],
                "N": c["N"], "delta": c["delta"], "M": c["M"], "p0": c["p0"], "oratio": c["oratio"],
                "corr": c["rho"]}

    # Stata lists the solver of mcc in the order of the iterations, unlike the other methods
    _ORDER = (["N", "power", "beta", "alpha", "delta", "nfractional", "onesided"] + _SOLVER[::-1]
              + ["p0", "corr", "oratio", "M", "p1", "F_M", "type", "method"])

    def returns(self, c, what):
        pw = c["power_out"] if what == "power" else c["power"]
        v = {"N": c["N"], "power": pw, "beta": 1 - pw, "alpha": c["alpha"], "delta": c["delta"],
             "nfractional": float(self.flag("nfractional")), "onesided": float(self.sides() == 1),
             "p0": c["p0"], "corr": c["rho"], "oratio": c["oratio"], "M": float(c["M"]),
             "p1": C.mcc_p1(c["p0"], c["oratio"], c["rho"])}
        if "F_M" in c:
            v["F_M"] = c["F_M"]
        v.update(_solver_vals(c))
        v.update({"type": "test", "method": "mcc"})
        _store(self.s, {k: (float(x) if not isinstance(x, str) else x) for k, x in v.items()}, self._ORDER)


class Trend(_M):
    method = "trend"
    allowed = {"npergroup", "grweights", "exposure", "continuity", "onesided"}

    def __init__(self, s, body, o):
        super().__init__(s, body, o)
        self.cols, self.rows = _probspec(s, body)
        self.J = len(self.cols) if self.cols is not None else len(self.rows[0])
        if self.J < 2:
            _fail("at least two probabilities are required")
        self.x = None
        if o.get("exposure") not in (None, True):
            x = P._values(str(o["exposure"]))
            if len(x) != self.J or (np.diff(x) <= 0).any():
                _fail("option exposure() incorrectly specified")
            self.x = x
        xs = self.x or list(range(1, self.J + 1))
        self.xs = xs
        if self.flag("continuity") and not np.allclose(np.diff(xs), xs[1] - xs[0]):
            _fail("continuity requires equally spaced exposure levels")
        self.gw = None
        if o.get("grweights") not in (None, True):
            w = P._values(str(o["grweights"]))
            if len(w) != self.J or min(w) <= 0 or (not self.flag("nfractional") and
                                                      not np.allclose(w, np.round(w))):
                _fail("option grweights() incorrectly specified")
            self.gw = C.standard_weights(w)
        if self.gw is not None and o.get("npergroup"):
            _fail("npergroup() and grweights() may not be combined")

    def base(self):
        b = self.common()
        v = self.vals("npergroup")
        if v is not None:
            b["npergroup"] = v
        if self.cols is not None:
            for j, col in enumerate(self.cols):
                b[f"p{j + 1}"] = col
        else:
            b["_row"] = list(range(len(self.rows)))
        return b

    def title(self, what):
        return f"Estimated {'sample size' if what == 'n' else 'power'} for a trend test"

    def hyp_lines(self, c, what):
        up = c["p"][-1] > c["p"][0]
        op = self.hyp_op(c, up)
        cat = "Cochran-Armitage trend test" + (" with continuity correction" if self.flag("continuity") else "")
        return [cat, f"Ho: b = 0  versus  Ha: b {op} 0;  logit(p) = a + b*x"]

    def compute(self, c):
        self.fix(c)
        J, a, sides, cont = self.J, c["alpha"], self.sides(), self.flag("continuity")
        p = (np.array([c[f"p{j + 1}"] for j in range(J)]) if self.cols is not None
             else np.array(self.rows[c["_row"]]))
        if ((p <= 0) | (p >= 1)).any():
            _fail("probabilities must be between 0 and 1")
        c["p"] = p
        c["mono"] = C.is_monotonic(p)
        w = self.gw if self.gw is not None else [1.0] * J
        sw = sum(w)
        have_n = c.get("n") is not None or c.get("npergroup") is not None
        if have_n:
            if c.get("power") is not None:
                _fail("only two of n(), power() and the effect size may be specified")
            N = float(c["n"]) if c.get("n") is not None else float(J * c["npergroup"])
            nj = np.array(w) * N / sw
            c["power_out"] = C.trend_power(nj, p, self.xs, a, sides, cont)
            what = "power"
        else:
            c.setdefault("power", 0.8)
            k = self.size(lambda k: C.trend_power(np.array(w) * k, p, self.xs, a, sides, cont),
                          1.0 / max(w), c["power"])
            nj = np.array(w) * k
            if self.exact is not None:
                c["N_a"] = self.exact * sw
            N = float(nj.sum())
            c["power_out"] = C.trend_power(nj, p, self.xs, a, sides, cont)
            try:        # r(init) of Stata 14: the root when only the tail in the direction of the effect counts
                c["_init"] = sw * C.solve_up(lambda x: C.trend_power(np.array(w) * x, p, self.xs, a, sides, cont,
                                                                     tail=True) - c["power"], 1.0 / max(w), 4.0)
            except ValueError:
                c["_init"] = 1.0
            what = "n"
        c["N"], c["nj"] = N, nj
        c["balanced"] = bool(np.allclose(nj, nj[0]))
        return what

    def sizes(self, c):
        if c["balanced"]:
            return [("N", _I(c["N"])), ("N per group", _I(c["nj"][0]))]
        return [("N", _I(c["N"])), ("Average N", P._f4(c["N"] / self.J))] + [
            (f"N{j + 1}", _I(v)) for j, v in enumerate(c["nj"])]

    def show(self, c, what):
        out = self.s.output
        items = [("alpha", P._f4(c["alpha"]))]
        if what == "n":
            items.append(("power", P._f4(c["power"])))
        else:
            items += self.sizes(c)
        items.append(("N_g", _I(self.J)))
        out.write("\nStudy parameters:\n\n", "text")
        for name, val in items:
            self.line(name, val)
        # the exposure beside each probability when it is given
        for j, v in enumerate(c["p"]):
            out.write(f"{'p' + str(j + 1):>{self.w}} = ", "text")
            out.write(P._f4(v), "result")
            if self.x is not None:
                out.write(f"{'x' + str(j + 1):>{self.w}} = ", "text")
                out.write(P._f4(self.x[j]), "result")
            out.write("\n", "text")
        if what == "n":
            self.results("Estimated sample sizes:", self.sizes(c))
        else:
            self.results("Estimated power:", [("power", P._f4(c["power_out"]))])
        if not c["mono"]:
            out.write("\nWarning: Alternative probabilities are not monotonic.\n", "text")
        self.returns(c, what)

    def header(self, c, what, lines):
        if self.x is None:
            self.s.output.write("\nnote: exposure levels are assumed to be equally spaced\n", "text")
        super().header(c, what, lines)

    def columns(self, c, what):
        cols = ["alpha", "power", "N", "N_per_group" if c["balanced"] else "N_avg", "N_g"]
        return cols + [f"p{j + 1}" for j in range(self.J)]

    def row(self, c, what):
        d = {"alpha": c["alpha"], "power": c["power_out"] if what == "power" else c["power"], "N": c["N"],
             "N_per_group": c["N"] / self.J,
             "N_avg": c["N"] / self.J, "N_g": self.J}
        d.update({f"p{j + 1}": v for j, v in enumerate(c["p"])})
        return d

    def returns(self, c, what):
        pw = c["power_out"] if what == "power" else c["power"]
        J, N = self.J, c["N"]
        v = {"N": N, "N_per_group": N / J, "N_avg": N / J, "N_a": c.get("N_a", N), "power": pw,
             "beta": 1 - pw, "alpha": c["alpha"], "nfractional": float(self.flag("nfractional")),
             "balanced": float(c["balanced"]), "onesided": float(self.sides() == 1), "N_g": float(J),
             "continuity": float(self.flag("continuity"))}
        v.update({f"p{j + 1}": float(x) for j, x in enumerate(c["p"])})
        if self.x is not None:
            v.update({f"x{j + 1}": float(x) for j, x in enumerate(self.x)})      # VERIFY: place of x_j
        v.update(_solver_vals(c))
        v.update({"type": "test", "method": "trend"})
        order = (["continuity", "balanced", "N_per_group", "N_avg", "N_g", "N_a"]
                 + [f"p{j + 1}" for j in range(J)] + [f"x{j + 1}" for j in range(J)]
                 + ["N", "power", "beta", "alpha"] + _SOLVER + ["onesided", "nfractional", "type", "method"])
        _store(self.s, {k: (float(x) if not isinstance(x, str) else x) for k, x in v.items()}, order)

files.opendta/commands/preserve.py:
"""preserve/restore and tempvar/tempname/tempfile ([P] preserve, [P] macro).

Temporaries and preserve belong to the current scope (program or
do-file) and are undone when it ends, with or without an error. Outside
programs and do-files, they belong to the interactive session.

preserve keeps a copy of the data in memory (the native vectors of
each variable), which is fast; Stata writes a temporary file.
"""

from __future__ import annotations

import os
import tempfile
from pathlib import Path
from typing import TYPE_CHECKING

from ..core.dataset import NAME_RE
from ..core.errors import StataError
from ..lang.programs import Scope
from ..lang.syntax import match_options
from .registry import command

if TYPE_CHECKING:
    from ..session import Session


def current_scope(s: "Session") -> Scope:
    if s.scopes:
        return s.scopes[-1]
    top = getattr(s, "top_scope", None)
    if top is None:
        top = s.top_scope = Scope("interactive")
    return top


def restore_preserved(s: "Session", scope: Scope) -> None:
    """End of the program or do-file: back to the preserved data."""
    if scope.preserved is not None:
        s.data = scope.preserved
        scope.preserved = None
        s.notify_state()


@command("preserve")
def cmd_preserve(s: "Session", args: str) -> None:
    head, comma, opts = args.partition(",")
    if head.strip():
        raise StataError(198, "invalid syntax")
    if comma:
        match_options(opts, {"changed": 6})
    scope = current_scope(s)
    if scope.preserved is not None:
        raise StataError(621, "already preserved")
    scope.preserved = s.data.copy()


@command("restore")
def cmd_restore(s: "Session", args: str) -> None:
    head, comma, opts = args.partition(",")
    if head.strip():
        raise StataError(198, "invalid syntax")
    o = match_options(opts, {"not": 3, "preserve": 8}) if comma else {}
    scope = next((sc for sc in reversed(s.scopes) if sc.preserved is not None), None)
    if scope is None:
        top = getattr(s, "top_scope", None)
        scope = top if top is not None and top.preserved is not None else None
    if scope is None:
        raise StataError(622, "nothing to restore")
    if o.get("not"):
        scope.preserved = None
        return
    snapshot = scope.preserved
    s.data = snapshot.copy() if o.get("preserve") else snapshot
    if not o.get("preserve"):
        scope.preserved = None
    s.notify_state()


def _counter(s: "Session") -> str:
    k = getattr(s, "_temp_counter", 0)
    while True:
        name = f"__{k:06X}"
        k += 1
        if not s.data.has(name) and name not in s.scalars and name not in getattr(s, "matrices", {}):
            s._temp_counter = k
            return name


def _names(args: str) -> list[str]:
    names = args.split()
    if not names:
        raise StataError(100, "something required")
    for n in names:
        if not NAME_RE.match(n):
            raise StataError(198, f"{n} invalid name")
    return names


@command("tempvar")
def cmd_tempvar(s: "Session", args: str) -> None:
    scope = current_scope(s)
    for n in _names(args):
        t = _counter(s)
        scope.tempvars.append(t)
        s.macros.set_local(n, t)


@command("tempname")
def cmd_tempname(s: "Session", args: str) -> None:
    scope = current_scope(s)
    for n in _names(args):
        t = _counter(s)
        scope.tempnames.append(t)
        s.macros.set_local(n, t)


@command("tempfile")
def cmd_tempfile(s: "Session", args: str) -> None:
    scope = current_scope(s)
    folder = Path(tempfile.gettempdir()) / f"opendta-{os.getpid()}"
    folder.mkdir(exist_ok=True)
    for n in _names(args):
        t = folder / f"S{_counter(s)}"
        scope.tempfiles.append(t)
        s.macros.set_local(n, str(t))

files.opendta/commands/progcmd.py:
"""program drop/dir/list and return, ereturn, sreturn ([P] program, [P] return).

r() of an rclass program only changes when it ends without an error: `return`
writes to an accumulator of the scope, published at the end (lang/programs.py).
e() changes immediately, as in Stata, and s() follows the same rule as r() for sclass.
"""

from __future__ import annotations

import re
from typing import TYPE_CHECKING

from ..core.errors import StataError
from ..core.formats import format_value
from ..lang.programs import current_program_scope
from .macro import _assign
from .registry import command

if TYPE_CHECKING:
    from ..session import Session


@command("program", "pr")
def cmd_program(s: "Session", args: str) -> None:
    words = args.split()
    if not words:
        raise StataError(198, "invalid syntax")
    sub, rest = words[0], words[1:]
    if sub == "drop":
        if not rest:
            raise StataError(198, "invalid syntax")
        if rest in (["_all"], ["_allado"]):
            if rest == ["_all"]:
                s.programs.clear()
            else:
                for k in [k for k, p in s.programs.items() if p.source.endswith(".ado")]:
                    del s.programs[k]
            return
        for name in rest:
            if name not in s.programs:
                raise StataError(111, f"program {name} not found")   # VERIFY
            del s.programs[name]
        return
    if sub == "dir":
        out = s.output
        # VERIFY: layout of program dir
        for name, p in s.programs.items():
            size = sum(len(ln.text) + 1 for ln in p.lines)
            out.write(f"  {'ado' if p.source.endswith('.ado') else '   '} {size:>8,}  {name}\n", "text")
        return
    if sub in ("list", "li", "l"):
        names = rest or list(s.programs)
        if names == ["_all"]:
            names = list(s.programs)
        out = s.output
        for name in names:
            p = s.programs.get(name)
            if p is None:
                raise StataError(111, f"program {name} not found")
            # VERIFY: layout of program list
            out.write(f"\n{name}{', ' + p.kind if p.kind != 'nclass' else ''}:\n", "text")
            for k, ln in enumerate(p.lines, start=1):
                out.write(f"  {k}.  {ln.text}\n", "text")
        return
    # a prefix (capture, quietly...) sends `program name, plugin` here
    from ..lang.programs import define_plugin, parse_definition
    name, options = parse_definition(args)
    if "plugin" in options:
        define_plugin(s, name, options)
    raise StataError(198, "invalid syntax")


# ---------------------------------------------------------------------------
# return / sreturn
# ---------------------------------------------------------------------------

def _scalar_value(s: "Session", text: str) -> float:
    m = re.match(r"^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.+)$", text, re.S)
    if not m:
        raise StataError(198, "invalid syntax")
    v = s.eval(m.group(2))
    if isinstance(v, str):
        raise StataError(109, "type mismatch")
    return m.group(1), float(v)


def _pending(s: "Session", kind: str) -> dict:
    sc = current_program_scope(s)
    if sc is None or sc.program is None or sc.program.kind != kind:
        letter = {"rclass": "r", "sclass": "s"}[kind]
        raise StataError(151, f"non {letter}-class program may not set {letter}()")   # VERIFY
    return sc.pending


def _store_cmd(s: "Session", args: str, kind: str) -> None:
    sub, _, rest = args.strip().partition(" ")
    if sub in ("list", "li", "l"):
        _results_list(s, s.r if kind == "rclass" else s.sret, "r" if kind == "rclass" else "s")
        return
    if sub == "clear":
        if kind == "rclass":
            sc = current_program_scope(s)
            if sc is not None and sc.program is not None and sc.program.kind == "rclass":
                sc.pending.clear()
            s.r = {}
        else:
            s.sret = {}
            sc = current_program_scope(s)
            if sc is not None and sc.program is not None and sc.program.kind == "sclass":
                sc.pending.clear()
        return
    store = _pending(s, kind)
    if sub in ("local", "loc"):
        _assign(s, rest, lambda name, value: store.__setitem__(name, value))
        return
    if sub in ("scalar", "sca") and kind == "rclass":
        name, value = _scalar_value(s, rest)
        store[name] = value
        return
    if sub == "add" and kind == "rclass":
        for k, v in s.r.items():
            store.setdefault(k, v)
        return
    if sub in ("matrix", "mat") and kind == "rclass":
        from .matrix import take_matrix
        store_matrix(store, take_matrix(s, rest))
        return
    raise StataError(198, "invalid syntax")


def store_matrix(store: dict, item) -> None:
    name, mat = item
    store[name] = mat


@command("return", "ret")
def cmd_return(s: "Session", args: str) -> None:
    _store_cmd(s, args, "rclass")


@command("sreturn", "sret")
def cmd_sreturn(s: "Session", args: str) -> None:
    _store_cmd(s, args, "sclass")


@command("ereturn", "eret")
def cmd_ereturn(s: "Session", args: str) -> None:
    sub, _, rest = args.strip().partition(" ")
    if sub in ("list", "li", "l"):
        _results_list(s, s.e, "e")
        return
    if sub == "clear":
        s.e = {}
        return
    if sub in ("local", "loc"):
        _assign(s, rest, lambda name, value: s.e.__setitem__(name, value) if value
                else s.e.pop(name, None))
        return
    if sub in ("scalar", "sca"):
        name, value = _scalar_value(s, rest)
        s.e[name] = value
        return
    if sub in ("matrix", "mat", "post", "repost", "display", "di"):
        from .matrix import ereturn_matrix
        ereturn_matrix(s, sub, rest)
        return
    raise StataError(198, "invalid syntax")


def _results_list(s: "Session", store: dict, prefix: str) -> None:
    """return list / ereturn list / sreturn list."""
    from .matrix import Matrix
    out = s.output
    scalars = {k: v for k, v in store.items() if isinstance(v, float) or isinstance(v, int)}
    macros = {k: v for k, v in store.items() if isinstance(v, str)}
    mats = {k: v for k, v in store.items() if isinstance(v, Matrix)}
    # Stata lists from the last stored result to the first (observed in
    # compat/expected/0201_programas.log) and aligns the names in 22 columns
    scalars = dict(reversed(list(scalars.items())))
    macros = dict(reversed(list(macros.items())))
    mats = dict(reversed(list(mats.items())))
    if scalars:
        out.write("\nscalars:\n", "text")
        for k, v in scalars.items():
            out.write(f"{prefix + '(' + k + ')':>22} =  ", "text")
            # values with up to 16 digits (%18.0g), as in Stata 14 (compat 0501, 0504)
            out.write(format_value(float(v), "%18.0g", pad=False).strip() + "\n", "result")
    if macros:
        out.write("\nmacros:\n", "text")
        for k, v in macros.items():
            out.write(f"{prefix + '(' + k + ')':>22} : ", "text")
            # a value longer than the line is cut and ends in ".." (compat 1912: 254 columns with
            # linesize 255; VERIFY with other line sizes)
            room = int(float(s.settings.get("linesize", 80))) - 1 - 27
            out.write(f'"{v[:room - 2]}.."\n' if len(v) > room else f'"{v}"\n', "result")
    if mats:
        out.write("\nmatrices:\n", "text")
        for k, v in mats.items():
            out.write(f"{prefix + '(' + k + ')':>22} :  ", "text")
            out.write(f"{v.rows} x {v.cols}\n", "result")
    if prefix == "e" and s.data.esample is not None and ("b" in store or getattr(getattr(s, "_estimates", None), "no_b", False)):
        # VERIFY spaces after e(sample)
        out.write("\nfunctions:\n", "text")
        out.write(f"{'e(sample)':>22}\n", "text")

files.opendta/commands/program.py:
"""do, run, include, exit, error, continue, args, tokenize, confirm."""

from __future__ import annotations

import os
import re
from pathlib import Path
from typing import TYPE_CHECKING

from ..core.errors import (BreakLoop, ContinueLoop, ExitRequest, StataError,
                           STANDARD_MESSAGES)
from ..lang.lexer import split_commands
from ..lang.words import split_words
from .registry import command

if TYPE_CHECKING:
    from ..session import Session


def _split_path(args: str) -> tuple[str, str]:
    a = args.strip()
    if a.startswith('`"'):
        j = a.find("\"'")
        return a[2:j], a[j + 2:].strip()
    if a.startswith('"'):
        j = a.find('"', 1)
        if j == -1:
            raise StataError(198, "invalid syntax")
        return a[1:j], a[j + 1:].strip()
    path, _, rest = a.partition(" ")
    return path, rest.strip()


def _resolve_do(path: str) -> Path:
    p = Path(os.path.expanduser(path))
    if p.suffix == "":
        p = p.with_suffix(".do")
    if not p.exists():
        raise StataError(601, f"file {p} not found")
    return p


def _run_file(s: "Session", args: str, *, echo: bool, new_scope: bool) -> None:
    path_text, rest = _split_path(args)
    if "," in rest and rest.strip().startswith(","):
        rest = ""  # options (nostop) come later
    path = _resolve_do(path_text)
    try:
        source = path.read_text(encoding="utf-8")
    except UnicodeDecodeError:
        source = path.read_text(encoding="latin-1")
    lines = split_commands(source, blanks=echo)

    out = s.output
    scope = None
    if new_scope:
        argv = split_words(rest)
        frame = {str(k): v for k, v in enumerate(argv, start=1)}
        if rest:
            frame["0"] = rest
        s.macros.push_frame(frame)
        from ..lang.programs import Scope
        scope = Scope("do", str(path))
        s.scopes.append(scope)
    if not echo:
        out.quiet_depth += 1
    s.do_depth += 1
    saved_file = s.current_dofile
    s.current_dofile = str(path)
    if echo:
        out.end_command()
    record = None
    if s.review_root is not None:
        record = (s._review_stack[-1] if s._review_stack else s.review_root)["children"]
    try:
        s.interp.run_lines(lines, echo=echo, record=record)
    except ExitRequest as e:
        if e.clear_all:
            raise
        if e.rc:
            raise StataError(e.rc, "")
    except (ContinueLoop, BreakLoop):
        raise StataError(198, "continue outside loop")
    except StataError as e:
        if echo:
            s.report_error(e)
            out.write("\nend of do-file\n", "text", force=True)
            raise StataError(e.rc, "")
        raise
    finally:
        s.do_depth -= 1
        s.current_dofile = saved_file
        if not echo:
            out.quiet_depth -= 1
        if new_scope:
            s.macros.pop_frame()
            s.scopes.remove(scope)
            s.close_scope(scope)      # temporaries and preserve of the do-file
    if echo:
        out.ensure_line_start()
        out.write(". \nend of do-file\n", "text")


@command("do")
def cmd_do(s: "Session", args: str) -> None:
    _run_file(s, args, echo=True, new_scope=True)


@command("run")
def cmd_run(s: "Session", args: str) -> None:
    _run_file(s, args, echo=False, new_scope=True)


@command("include")
def cmd_include(s: "Session", args: str) -> None:
    _run_file(s, args, echo=True, new_scope=False)


@command("exit")
def cmd_exit(s: "Session", args: str) -> None:
    t = args.strip()
    clear_all = False
    if "," in t:
        t, _, opts = t.partition(",")
        clear_all = "clear" in opts.split() or "STATA" in opts.split()
    t = t.strip()
    rc = int(float(s.eval(t))) if t else 0
    in_program = any(sc.kind == "program" for sc in s.scopes)
    if s.do_depth == 0 and not in_program:
        clear_all = True
    raise ExitRequest(rc, clear_all=clear_all)


@command("error")
def cmd_error(s: "Session", args: str) -> None:
    t = args.strip()
    if not t:
        raise StataError(198, "invalid syntax")
    rc = int(float(s.eval(t)))
    if rc == 0:
        return
    # error raised on purpose (error #): no OpenDTA explanation
    raise StataError(rc, STANDARD_MESSAGES.get(rc, ""), explain=False)


@command("continue")
def cmd_continue(s: "Session", args: str) -> None:
    t = args.strip()
    if t in ("", ","):
        raise ContinueLoop()
    if re.match(r"^,\s*break$", t):
        raise BreakLoop()
    raise StataError(198, "invalid syntax")


@command("args")
def cmd_args(s: "Session", args: str) -> None:
    for k, name in enumerate(args.split(), start=1):
        s.macros.set_local(name, s.macros.get_local(str(k)))


@command("tokenize")
def cmd_tokenize(s: "Session", args: str) -> None:
    text = args
    parse_chars = None
    m = re.search(r",\s*p(?:a|ar|ars|arse)?\(\s*\"?(.*?)\"?\s*\)\s*$", text)
    if m:
        parse_chars = m.group(1)
        text = text[:m.start()]
    text = text.strip()
    if text.startswith('`"') and text.endswith("\"'"):
        text = text[2:-2]
    elif len(text) >= 2 and text.startswith('"') and text.endswith('"'):
        text = text[1:-1]
    loc = s.macros.locals
    for k in [k for k in loc if k.isdigit()]:
        del loc[k]
    if parse_chars:
        pattern = "([" + re.escape(parse_chars) + "])"
        pieces = [p.strip() for p in re.split(pattern, text) if p.strip()]
    else:
        pieces = split_words(text)
    for k, w in enumerate(pieces, start=1):
        s.macros.set_local(str(k), w)


@command("confirm", "conf")
def cmd_confirm(s: "Session", args: str) -> None:
    t = args.strip()
    m = re.match(r"^(?:(integer)\s+)?n(?:u|um|umb|umbe|umber)?\s+(.*)$", t)
    if m:
        val = m.group(2).strip()
        try:
            x = float(val)
        except ValueError:
            raise StataError(7, f"'{val}' found where number expected" if not m.group(1)
                             else f"'{val}' found where integer expected")
        if m.group(1) and x != int(x):
            raise StataError(7, f"'{val}' found where integer expected")
        return
    m = re.match(r"^(new\s+)?f(?:i|il|ile)?\s+(.*)$", t)
    if m:
        path = m.group(2).strip().strip('"')
        exists = Path(path).exists()
        if m.group(1) and exists:
            raise StataError(602, f"file {path} already exists")
        if not m.group(1) and not exists:
            raise StataError(601, f"file {path} not found")
        return
    m = re.match(r"^names?\s+(.*)$", t)
    if m:
        for name in m.group(1).split():
            if not re.match(r"^[A-Za-z_][A-Za-z0-9_]{0,31}$", name):
                raise StataError(7, f"{name} invalid name")
        return
    raise StataError(198, "invalid syntax")

files.opendta/commands/progutil.py:
"""pause, sleep, window, plugin and viewsource ([P] pause, [P] sleep, [P] window, [P] plugin,
[P] viewsource).

The commands that need the graphical interface (window fopen, fsave, stopbox, push, manage and
menu) call a hook in `Session.ui_hooks`; without the interface they do what the manual says for a
window that does not exist, or act as if the user had cancelled.
"""

from __future__ import annotations

import inspect
import re
import sys
import time
from typing import TYPE_CHECKING

from ..core.errors import StataError
from ..lang.adopath import find_file
from ..lang.words import strip_outer_quotes
from .registry import command, lookup

if TYPE_CHECKING:
    from ..session import Session


# ---------------------------------------------------------------------------
# sleep, pause
# ---------------------------------------------------------------------------

@command("sleep")
def cmd_sleep(s: "Session", args: str) -> None:
    if not args.strip():
        raise StataError(111, " not found")        # Stata evaluates the empty argument
    ms = s.eval(args.strip())
    if isinstance(ms, str) or ms != ms or ms < 0:
        raise StataError(198, "invalid syntax")
    time.sleep(float(ms) / 1000.0)


def _read_line(s: "Session"):
    """A line typed in pause mode; None at the end of the input."""
    if s.input_provider is not None:
        text = s.input_provider()
        if text is None:
            raise StataError(1, "--Break--")
        return str(text)
    line = sys.stdin.readline()
    return None if line == "" else line.rstrip("\r\n")


@command("pause")
def cmd_pause(s: "Session", args: str) -> None:
    t = args.strip()
    if t in ("on", "off"):
        s.pause_on = t == "on"
        return
    if not getattr(s, "pause_on", False):
        return
    out = s.output
    out.write(f"pause: {t}\n" if t else "pause:\n", "text")
    while True:
        out.write("-> . ", "text")
        line = _read_line(s)
        if line is None:
            out.write("\n", "text")
            break
        out.write(line + "\n", "input")
        word = line.strip()
        if word in ("end", "q"):
            break
        if word == "BREAK":
            out.write("sending Break to calling program...\n", "text")
            raise StataError(1, "Break")
        s.run(line)
    out.write("execution resumes...\n", "text")


# ---------------------------------------------------------------------------
# window
# ---------------------------------------------------------------------------

_MANAGE = {"minimize", "restore", "maintitle", "associate", "docklabel", "prefs", "forward",
           "print", "close", "rename"}
_MENU = {"clear", "append", "refresh", "add"}


def _quoted(text: str) -> list[str]:
    """The strings of '"a" "b" c': quoted ones without the quotes, the others as they are."""
    return [m.group(1) if m.group(1) is not None else m.group(2)
            for m in re.finditer(r'"([^"]*)"|(\S+)', text)]


@command("window", "wind")
def cmd_window(s: "Session", args: str) -> None:
    sub, _, rest = args.strip().partition(" ")
    rest = rest.strip()
    hook = s.ui_hooks.get(f"window_{sub}")
    if sub in ("fopen", "fsave"):
        words = _quoted(rest)
        if len(words) < 3 or not re.fullmatch(r"[A-Za-z_]\w*", words[0]):
            raise StataError(198, "invalid syntax")
        name, title, filt = words[:3]
        ext = words[3] if len(words) > 3 else ""
        path = hook(sub, title, filt, ext, s.macros.get_global(name)) if hook else None
        s.macros.set_global(name, path or "")
        if not path:
            # cancelled (and, without the interface, there is nobody to choose a file)
            raise StataError(601, "")
    elif sub == "stopbox":
        kind, _, text = rest.partition(" ")
        if kind not in ("stop", "note", "rusure"):
            raise StataError(198, "invalid syntax")
        lines = _quoted(text)[:4]
        if not lines:
            raise StataError(198, "invalid syntax")
        answer = hook(kind, lines) if hook else None
        if hook is None:
            for line in lines:
                s.output.write(line + "\n", "text")
            answer = kind == "note"      # VERIFY: nobody to answer without the interface
        if kind == "stop" or (kind == "rusure" and not answer):
            raise StataError(1, "")
    elif sub == "push":
        if not rest:
            raise StataError(198, "invalid syntax")
        if hook:
            hook(rest)
    elif sub == "manage":
        word = rest.split(None, 1)[0] if rest else ""
        if word not in _MANAGE:
            raise StataError(198, "invalid syntax")
        if hook:
            hook(rest)
    elif sub == "menu":
        word = rest.split(None, 1)[0] if rest else ""
        if word not in _MENU:
            raise StataError(198, "invalid syntax")
        if word == "clear":
            s.window_menu = []
        elif word in ("append", "add"):
            s.window_menu = getattr(s, "window_menu", []) + [_quoted(rest)]
        elif hook:
            hook(getattr(s, "window_menu", []))
    else:
        raise StataError(198, "invalid syntax")


# ---------------------------------------------------------------------------
# plugin, viewsource
# ---------------------------------------------------------------------------

@command("plugin")
def cmd_plugin(s: "Session", args: str) -> None:
    sub = args.split(None, 1)[0] if args.strip() else ""
    if sub != "call":
        raise StataError(198, "invalid syntax")
    # Stata says this when the plugin was not loaded; OpenDTA never loads one
    raise StataError(199, "unrecognized command")


@command("viewsource")
def cmd_viewsource(s: "Session", args: str) -> None:
    """Shows a file found on the adopath or, for a command that OpenDTA has built in, the source of
    OpenDTA's own implementation (not Stata's)."""
    fname = strip_outer_quotes(args.strip())
    if not fname:
        raise StataError(601, 'file "" not found')
    hits = find_file(s, fname)
    if hits:
        try:
            text = hits[0].read_text(encoding="utf-8")
        except UnicodeDecodeError:
            text = hits[0].read_text(encoding="latin-1")
    else:
        spec = lookup(fname[:-4]) if fname.endswith(".ado") else None
        try:
            fn = spec.fn if spec is not None else None
            while fn is not None and "_inner" in inspect.signature(fn).parameters:
                fn = inspect.signature(fn).parameters["_inner"].default    # a wrapper of the command
            text = inspect.getsource(fn) if fn is not None else None
        except (OSError, TypeError):
            text = None
        if text is None:
            raise StataError(601, f'file "{fname}" not found')
    for line in text.splitlines():
        s.output.write(line + "\n", "text")

files.opendta/commands/putexcel.py:
"""putexcel ([P] putexcel): writes text, expressions and matrices to
cells of an .xlsx spreadsheet (openpyxl) or of an .xls one (xlrd and xlwt, io/excel.py).

Accepts both Stata 14 syntaxes:
    putexcel set file [, sheet(name) replace modify]
    putexcel A1 = "text" B2 = (expression) C3 = matrix(name), names
and the 14.0 one, with the file in the command itself:
    putexcel A1=("text") B1=(expr) using file [, sheet() replace modify]
"""

from __future__ import annotations

import re
from pathlib import Path
from typing import TYPE_CHECKING

from ..core.errors import StataError
from ..lang.syntax import find_top, match_options, parse_options
from ..lang.words import strip_outer_quotes
from .registry import command

if TYPE_CHECKING:
    from ..session import Session

_CELL = re.compile(r"^([A-Za-z]{1,3})(\d+)$")


def _state(s: "Session") -> dict:
    st = getattr(s, "_putexcel", None)
    if st is None:
        st = {}
        s._putexcel = st
    return st


def _path(text: str) -> Path:
    t = strip_outer_quotes(text.strip())
    if not t:
        raise StataError(198, "invalid file specification")
    p = Path(t).expanduser()
    if p.suffix == "":
        p = p.with_suffix(".xlsx")
    return p


def _split_cells(text: str) -> list[tuple[str, str]]:
    """'A1 = "x" B2 = (1+1) C3=matrix(m), names' -> [(cell, value)]."""
    items: list[tuple[str, str]] = []
    i, n = 0, len(text)
    while i < n:
        while i < n and text[i].isspace():
            i += 1
        if i >= n:
            break
        m = re.match(r"([A-Za-z]{1,3}\d+)\s*=\s*", text[i:])
        if not m:
            raise StataError(198, "invalid syntax")
        cell = m.group(1).upper()
        i += m.end()
        j = i
        depth = 0
        while j < n:
            c = text[j]
            if c == '"':
                k = text.find('"', j + 1)
                j = n if k == -1 else k + 1
                continue
            if c == "(":
                depth += 1
            elif c == ")":
                depth -= 1
            elif c.isspace() and depth == 0:
                rest = text[j:].lstrip()
                if re.match(r"[A-Za-z]{1,3}\d+\s*=", rest):
                    break
            j += 1
        items.append((cell, text[i:j].strip()))
        i = j
    return items


def _col_index(letters: str) -> int:
    k = 0
    for ch in letters.upper():
        k = k * 26 + (ord(ch) - 64)
    return k


@command("putexcel", "putexcel")
def cmd_putexcel(s: "Session", args: str) -> None:
    t = args.strip()
    st = _state(s)
    head = t.split(None, 1)[0] if t else ""
    if head == "set":
        rest = t[3:].strip()
        c = find_top(rest, ",")
        body, opt = (rest, "") if c == -1 else (rest[:c], rest[c + 1:])
        o = match_options(opt, {"sheet": 2, "replace": 3, "modify": 3}) if opt.strip() else {}
        st.clear()
        st["path"] = _path(body)
        st["sheet"] = strip_outer_quotes(str(o["sheet"]).split(",")[0]) if isinstance(o.get("sheet"), str) else ""
        st["sheet_replace"] = isinstance(o.get("sheet"), str) and "replace" in str(o["sheet"])
        st["mode"] = "replace" if o.get("replace") else "modify"
        st["fresh"] = bool(o.get("replace"))
        return
    if head == "clear":
        st.clear()
        return
    if head == "describe":
        out = s.output
        if not st:
            out.write("  (no file set)\n", "text")   # VERIFY
            return
        out.write(f"  File: {st['path']}\n  Sheet: {st.get('sheet') or 'Sheet1'}\n", "text")
        return
    # 14.0 syntax: ... using file
    m = re.search(r"\busing\b", t)
    c = find_top(t, ",")
    body, opt = (t, "") if c == -1 else (t[:c], t[c + 1:])
    o = {}
    for nm, a in parse_options(opt) if opt.strip() else []:
        o[nm] = a if a is not None else True
    if m and (c == -1 or m.start() < c):
        cells_txt = body[:m.start()]
        path = _path(body[m.end():])
        sheet = strip_outer_quotes(str(o.get("sheet", "")).split(",")[0]) if isinstance(o.get("sheet"), str) else ""
        fresh = "replace" in o
    else:
        if opt.strip():
            # with the putexcel set syntax, Stata 14.0 does not accept options at the end of the
            # command (matrix options go inside matrix(name, names)); compat 0804: "option names
            # not allowed"
            raise StataError(198, f"option {next(iter(o))} not allowed")
        if not st:
            raise StataError(198, "file not set; use putexcel set")   # VERIFY
        cells_txt = body
        path, sheet = st["path"], st.get("sheet", "")
        fresh = st.get("fresh", False)
    items = _split_cells(cells_txt)
    if not items:
        raise StataError(198, "invalid syntax")
    if path.suffix.lower() == ".xls":
        from ..io.excel import XlsBook
        wb = XlsBook(path if path.exists() and not fresh else None)
    else:
        import openpyxl
        if path.exists() and not fresh:
            wb = openpyxl.load_workbook(path)
        else:
            wb = openpyxl.Workbook()
            if sheet:
                wb.active.title = sheet
    ws = wb[sheet] if sheet and sheet in wb.sheetnames else (wb.create_sheet(sheet) if sheet else wb.active)
    for cell, val in items:
        mm = _CELL.match(cell)
        col, row = _col_index(mm.group(1)), int(mm.group(2))
        _write_value(s, ws, row, col, val, o)
    try:
        wb.save(path)
    except OSError:
        raise StataError(603, f"file {path} could not be opened")
    if st:
        st["fresh"] = False    # after the first write, the following ones modify
    s.output.write(f"file {path} saved\n", "text")


def _write_value(s: "Session", ws, row: int, col: int, val: str, o: dict) -> None:
    v = val.strip()
    mm = re.match(r"^matrix\s*\((.*)\)\s*(,.*)?$", v, re.S)
    if mm:
        inner = mm.group(1)
        c = find_top(inner, ",")
        name, sub = (inner, "") if c == -1 else (inner[:c], inner[c + 1:])
        flags = {n for n, _ in parse_options(sub)} if sub.strip() else set()
        if mm.group(2):
            flags |= {n for n, _ in parse_options(mm.group(2)[1:])}
        flags |= {k for k in o if k in ("names", "rownames", "colnames")}
        _write_matrix(s, ws, row, col, name.strip(), flags)
        return
    if v.startswith('"') or v.startswith('`"'):
        ws.cell(row=row, column=col, value=strip_outer_quotes(v))
        return
    if v.startswith("(") and v.endswith(")"):
        v = v[1:-1]
    if v.startswith('"'):
        ws.cell(row=row, column=col, value=strip_outer_quotes(v))
        return
    res = s.eval(v)
    if isinstance(res, str):
        ws.cell(row=row, column=col, value=res)
    else:
        from ..core.missing import SYSMISS
        ws.cell(row=row, column=col, value=None if res >= SYSMISS else float(res))


def _write_matrix(s: "Session", ws, row: int, col: int, name: str, flags: set) -> None:
    from .matrix import get_matrix
    mat = get_matrix(s, name)
    data = mat.data
    rn = "names" in flags or "rownames" in flags
    cn = "names" in flags or "colnames" in flags
    r0 = row + (1 if cn else 0)
    c0 = col + (1 if rn else 0)
    if cn:
        for j, nm in enumerate(mat.colnames):
            ws.cell(row=row, column=c0 + j, value=nm)
    if rn:
        for i, nm in enumerate(mat.rownames):
            ws.cell(row=r0 + i, column=col, value=nm)
    from ..core.missing import SYSMISS
    for i in range(data.shape[0]):
        for j in range(data.shape[1]):
            x = float(data[i, j])
            ws.cell(row=r0 + i, column=c0 + j, value=None if x >= SYSMISS else x)

files.opendta/commands/registry.py:
"""Command registry and abbreviation resolution.

Each command declares its full name and minimal abbreviation (the
underlined part in the manual's syntax diagram). E.g.: display -> "di".
"""

from __future__ import annotations

from dataclasses import dataclass
from importlib import import_module
from typing import TYPE_CHECKING, Callable

if TYPE_CHECKING:
    from ..session import Session

CommandFn = Callable[["Session", str], None]


@dataclass(frozen=True)
class CommandSpec:
    name: str
    min_abbrev: int
    fn: CommandFn
    prefix: bool = False  # quietly, noisily, capture, version: take a command
    byable: bool = False  # aceita o prefixo by


REGISTRY: dict[str, CommandSpec] = {}


def command(name: str, abbrev: str | None = None, *, prefix: bool = False, byable: bool = False):
    """Registers a command. `abbrev` is the minimal accepted form (default: full name)."""
    minimal = abbrev or name
    if not name.startswith(minimal):
        raise ValueError(f"abbreviation {minimal!r} is not a prefix of {name!r}")

    def deco(fn: CommandFn) -> CommandFn:
        REGISTRY[name] = CommandSpec(name, len(minimal), fn, prefix, byable)
        return fn
    return deco


def lazy_commands(module: str, *names: str | tuple[str, str], prefix: bool = False) -> None:
    """Registers commands whose code, cmd_<name> in opendta.estimation.<module>, is imported on
    first use (start-up time). A name may be given with its minimal abbreviation: ("regress", "reg")."""
    for entry in names:
        name, abbrev = entry if isinstance(entry, tuple) else (entry, entry)

        def run(s: "Session", args: str, _target=f"cmd_{name}") -> None:
            getattr(import_module(f"opendta.estimation.{module}"), _target)(s, args)
        run.__name__ = f"cmd_{name}"
        command(name, abbrev, prefix=prefix)(run)


def lookup(word: str) -> CommandSpec | None:
    spec = REGISTRY.get(word)
    if spec is not None:
        return spec
    # with more than one candidate (sca: scalar or scatter), the one with the longest minimal
    # abbreviation wins: it is the one the manual reserves for that form
    best = None
    for spec in REGISTRY.values():
        if len(word) >= spec.min_abbrev and spec.name.startswith(word):
            if best is None or spec.min_abbrev > best.min_abbrev:
                best = spec
    return best


def all_commands() -> list[str]:
    return sorted(REGISTRY)

