"""ICD code tables for icd9 and icd10: ICD-9-CM diagnosis codes (version 29) and
ICD-10-CM (2018), from the public-domain files of the U.S. Centers for Medicare &
Medicaid Services (see src/opendta/data/icd/README.md and
tools/make_icd_tables.py). Codes are kept without the period."""

from __future__ import annotations

import gzip
from functools import lru_cache
from pathlib import Path

DATA = Path(__file__).resolve().parent.parent / "data" / "icd"
FILES = {"icd9": "icd9cm.tsv.gz", "icd10": "icd10cm.tsv.gz"}
VERSIONS = {"icd9": "ICD-9-CM diagnosis codes, version 29 (CMS)", "icd10": "ICD-10-CM, 2018 (CMS)"}


@lru_cache(maxsize=None)
def table(kind: str) -> dict[str, tuple[bool, str, str]]:
    """{code: (billable, short description, long description)}."""
    out = {}
    with gzip.open(DATA / FILES[kind], "rt", encoding="utf-8") as f:
        for line in f:
            code, bill, short, long_ = line.rstrip("\n").split("\t")
            out[code] = (bill == "1", short, long_)
    return out


@lru_cache(maxsize=None)
def _prefixes(kind: str) -> frozenset[str]:
    """Every leading part of a code: categories and subcategories of the codes in the table
    (the ICD-9-CM file lists only the most detailed codes)."""
    pre = set()
    for code in table(kind):
        for k in range(3, len(code) + 1):
            pre.add(code[:k])
    return frozenset(pre)


def norm(code: str) -> str:
    return code.strip().upper().replace(".", "")


def defined(kind: str, code: str) -> bool:
    return norm(code) in _prefixes(kind)


def describe(kind: str, code: str, long: bool = False) -> str:
    """Description of a code in the table; empty for a category the table does not list (the
    ICD-9-CM file has no titles for its categories)."""
    entry = table(kind).get(norm(code))
    return "" if entry is None else entry[2 if long else 1]


def dotted(kind: str, code: str) -> str:
    """The code with its period: after the 3rd character (4th for ICD-9 E codes)."""
    c = norm(code)
    head = 4 if kind == "icd9" and c.startswith("E") else 3
    return c if len(c) <= head else c[:head] + "." + c[head:]

files.opendta/core/output.py:
"""Text output (Results window, console, logs).

All output goes through `Output`, which keeps the current column (needed for
_column() and _continue) and passes the pieces on to the registered listeners:
the Results window of the interface, the console and log files.

Styles follow Stata's categories: "text", "result", "error",
"input" and "command" (echo of the typed command).
"""

from __future__ import annotations

import contextlib

from typing import Callable

Listener = Callable[[str, str], None]

STYLES = ("text", "result", "error", "input", "command")


class Output:
    def __init__(self) -> None:
        self._listeners: list[Listener] = []
        self.column = 0           # current column (0 = start of the line)
        self.quiet_depth = 0      # > 0 inside quietly
        self.noisy_depth = 0      # noisily inside quietly
        self.capture_depth = 0    # > 0 inside capture: silences even errors
        self.linesize = lambda: 0   # the session's linesize; echoed lines wrap at it

    # -- ouvintes -------------------------------------------------------
    def add_listener(self, fn: Listener) -> None:
        self._listeners.append(fn)

    def remove_listener(self, fn: Listener) -> None:
        if fn in self._listeners:
            self._listeners.remove(fn)

    @contextlib.contextmanager
    def quietly(self):
        """Silences everything inside, even when an enclosing noisily is active (as a nested
        quietly does in Stata)."""
        self.quiet_depth += 1
        saved = self.noisy_depth
        self.noisy_depth = 0
        try:
            yield
        finally:
            self.quiet_depth -= 1
            self.noisy_depth = saved

    # -- silence state -----------------------------------------------
    @property
    def suppressed(self) -> bool:
        return self.quiet_depth > 0 and self.noisy_depth == 0

    # -- escrita -----------------------------------------------------------
    def write(self, text: str, style: str = "text", *, force: bool = False) -> None:
        if not text:
            return
        if force:
            # error messages appear under quietly, but not under capture
            if self.capture_depth > 0 and self.noisy_depth == 0:
                return
        elif self.suppressed:
            return
        for fn in list(self._listeners):
            fn(text, style)
        last_nl = text.rfind("\n")
        if last_nl == -1:
            self.column += len(text)
        else:
            self.column = len(text) - last_nl - 1

    def newline(self, n: int = 1, *, force: bool = False) -> None:
        self.write("\n" * n, "text", force=force)

    def ensure_line_start(self, *, force: bool = False) -> None:
        if self.column != 0:
            self.newline(force=force)

    def error(self, message: str, rc: int, *, show_rc: bool = True,
              hint: list[tuple[str, str]] = ()) -> None:
        """Error message and r(#); — shown even under quietly (but not
        under capture). `hint`: OpenDTA's explanation as (text, style) pieces, between the two."""
        self.ensure_line_start(force=True)
        if message:
            self.write(message + "\n", "error", force=True)
        for text, style in hint:
            self.write(text, style, force=True)
        if show_rc:
            self.write(f"r({rc});\n", "error", force=True)

    def echo_command(self, lines) -> None:
        """Echo '. command' as the Results window does; continuation lines
        appear with '> '."""
        if isinstance(lines, str):
            lines = (lines,)
        self.ensure_line_start()
        w = self.linesize() - 2
        for k, line in enumerate(lines):
            prefix = ". " if k == 0 else "> "
            while w > 0 and len(line) > w:
                self.write(prefix + line[:w] + "\n", "command")
                line, prefix = line[w:], "> "
            self.write(prefix + line + "\n", "command")

    def end_command(self) -> None:
        """Blank line after each command (as in Stata)."""
        self.ensure_line_start()
        self.write("\n")


class Capture:
    """Listener that accumulates the text (used in tests and in batch mode)."""

    def __init__(self) -> None:
        self.parts: list[tuple[str, str]] = []

    def __call__(self, text: str, style: str) -> None:
        self.parts.append((text, style))

    @property
    def text(self) -> str:
        return "".join(t for t, _ in self.parts)

    def clear(self) -> None:
        self.parts.clear()

files.opendta/core/power_suites.py:
"""Formulas for power and sample-size analysis, part 2: twoway, repeated, cmh, mcc, trend, cox,
exponential and logrank ([PSS] power twoway ... power logrank, Methods and formulas).

Plain functions: they take numbers and arrays and return numbers, with no Session, no variables and
no printing. A failed search raises ValueError; commands/power3.py turns it into Stata's error.
Rules the manual does not state are marked VERIFY (case compat/do/1919_other_suites2.do).
"""

from __future__ import annotations

import math
from typing import Callable

import numpy as np

from ..lazy import lazy

st = lazy("scipy.stats")
opt = lazy("scipy.optimize")


def zq(p: float) -> float:
    return float(st.norm.ppf(p))


# ---------------------------------------------------------------------------
# searches
# ---------------------------------------------------------------------------

def smallest_int(power_of: Callable[[int], float], target: float, lo: int = 1, cap: int = 10 ** 9) -> int:
    """Smallest integer k >= lo with power_of(k) >= target (power increasing in k; nan counts as
    not reached). VERIFY: a saw-toothed power function can have a smaller k that fails."""
    k = max(int(lo), 1)
    if power_of(k) >= target:
        return k
    hi = max(2 * k, 2)
    while not power_of(hi) >= target:
        k, hi = hi, hi * 2
        if hi > cap:
            raise ValueError("no solution")
    while hi - k > 1:
        mid = (hi + k) // 2
        if power_of(mid) >= target:
            hi = mid
        else:
            k = mid
    return hi


def solve_up(f: Callable[[float], float], lo: float, hi: float) -> float:
    """Root of an increasing function f on [lo, hi]; hi is doubled until f(hi) >= 0."""
    if f(lo) >= 0:
        return lo
    for _ in range(80):
        if f(hi) >= 0:
            return float(opt.brentq(f, lo, hi, xtol=1e-13, rtol=1e-13, maxiter=500))
        lo, hi = hi, hi * 2
    raise ValueError("no solution")


def sides_z(alpha: float, sides: int) -> float:
    return zq(1 - alpha / sides)


# ---------------------------------------------------------------------------
# ANOVA: noncentral F
# ---------------------------------------------------------------------------

def anova_power(lam: float, df1: float, df2: float, alpha: float) -> float:
    if df2 <= 0:
        return math.nan
    crit = float(st.f.isf(alpha, df1, df2))
    return float(min(max(st.ncf.sf(crit, df1, df2, lam), 0.0), 1.0))


def lambda_for_power(df1: float, df2: float, alpha: float, power: float) -> float:
    """Noncentrality that gives the requested power."""
    return solve_up(lambda lam: anova_power(lam, df1, df2, alpha) - power, 1e-9, 10.0)


def standard_weights(w: list[float]) -> list[float]:
    """Smallest weights with the same ratios: divided by the gcd of integers, else by the
    minimum. VERIFY: the manual refers to [PSS] power oneway for the standardization."""
    if all(float(x).is_integer() for x in w):
        g = 0
        for x in w:
            g = math.gcd(g, int(x))
        return [float(int(x) // g) for x in w]
    m = min(w)
    return [x / m for x in w]


# ---------------------------------------------------------------------------
# twoway
# ---------------------------------------------------------------------------

def twoway_variances(means: np.ndarray) -> tuple[float, float, float]:
    """Row, column and row-by-column variances explained: sum a_j^2 / J, ..."""
    m = np.asarray(means, dtype=float)
    gm = m.mean()
    a = m.mean(axis=1) - gm
    b = m.mean(axis=0) - gm
    ab = m - m.mean(axis=1)[:, None] - m.mean(axis=0)[None, :] + gm
    return float((a ** 2).mean()), float((b ** 2).mean()), float((ab ** 2).mean())


def twoway_df1(J: int, K: int, which: str) -> int:
    return {"row": J - 1, "column": K - 1}.get(which, (J - 1) * (K - 1))


def twoway_contrast(J: int, K: int, which: str) -> np.ndarray:
    dj = np.hstack([np.eye(J - 1), -np.ones((J - 1, 1))])
    dk = np.hstack([np.eye(K - 1), -np.ones((K - 1, 1))])
    if which == "row":
        return np.kron(dj, np.ones((1, K)) / K)
    if which == "column":
        return np.kron(np.ones((1, J)) / J, dk)
    return np.kron(dj, dk)


def twoway_noncentrality(means: np.ndarray, frac: np.ndarray, n: float, which: str, var_e: float) -> float:
    """lambda = n (C mu)' {C W^-1 C'}^-1 (C mu) / var_e, cells in row-major order."""
    J, K = np.asarray(means).shape
    c = twoway_contrast(J, K, which)
    cm = c @ np.asarray(means, dtype=float).reshape(-1)
    w = np.asarray(frac, dtype=float).reshape(-1)
    a = c @ np.diag(1.0 / w) @ c.T
    return float(n * cm @ np.linalg.solve(a, cm) / var_e)


def twoway_power(lam: float, J: int, K: int, n: float, which: str, alpha: float) -> float:
    return anova_power(lam, twoway_df1(J, K, which), n - J * K, alpha)


# ---------------------------------------------------------------------------
# repeated
# ---------------------------------------------------------------------------

def cs_covariance(K: int, var: float, rho: float) -> np.ndarray:
    return var * ((1 - rho) * np.eye(K) + rho * np.ones((K, K)))


def _within_basis(K: int) -> np.ndarray:
    q, _ = np.linalg.qr(np.column_stack([np.ones(K) / math.sqrt(K), np.eye(K)[:, :K - 1]]))
    return q[:, 1:]


def repeated_summary(J: int, K: int, cov: np.ndarray, which: str, weights: np.ndarray,
                     means: np.ndarray | None = None, var_effect: float | None = None) -> dict:
    """delta^2, degrees of freedom, epsilon and the variance terms of [PSS] power repeated.
    The columns of U are the orthonormal ones divided by sqrt(K), as in Stata's Var_be, Var_we and
    Var_w (checked against the Stata 14 log of case 1919)."""
    if which in ("between", "bwithin"):
        if J < 2:
            raise ValueError("at least two groups are required for a between-subjects effect")
        c = np.hstack([np.eye(J - 1), -np.ones((J - 1, 1))])
    else:
        c = np.ones((1, J)) / J
    u = np.ones((K, 1)) / math.sqrt(K) if which == "between" else _within_basis(K)
    u = u / math.sqrt(K)
    dc, du = c.shape[0], u.shape[1]
    sstar = u.T @ np.asarray(cov, dtype=float) @ u
    tr_s = float(np.trace(sstar))
    eps = tr_s ** 2 / (du * float(np.trace(sstar @ sstar)))
    var_e = tr_s / (dc * du)
    if means is not None:
        theta = c @ np.asarray(means, dtype=float) @ u
        a = c @ np.diag(1.0 / np.asarray(weights, dtype=float)) @ c.T
        tr_h = float(np.trace(theta.T @ np.linalg.solve(a, theta)))
        var_x = tr_h / dc
    else:
        var_x = float(var_effect)
    return {"dc": dc, "du": du, "eps": eps, "var_x": var_x, "var_xe": var_e, "delta2": var_x / var_e,
            "spherical": abs(eps - 1) < 1e-8}


def repeated_power(delta2: float, dc: int, du: int, p: int, n: float, eps: float, alpha: float,
                   lower: bool = False) -> float:
    """F test with the Greenhouse-Geisser correction: epsilon scales both degrees of freedom and
    the noncentrality. Stata's multiplier m of Muller and Barton (1989) is not documented; this
    form reproduces the spherical cases of the Stata 14 log exactly and a non-spherical one to
    1e-4 (compat/known_differences.txt)."""
    df1, df2 = dc * du * eps, du * (n - p) * eps
    if df2 <= 0:
        return math.nan
    crit = float(st.f.isf(alpha, df1, df2))
    tail = st.ncf.cdf if lower else st.ncf.sf       # beta from the lower tail: no cancellation
    return float(min(max(tail(crit, df1, df2, n * delta2 * eps), 0.0), 1.0))


# ---------------------------------------------------------------------------
# cmh
# ---------------------------------------------------------------------------

def odds_probability(p1: np.ndarray, oratio: float) -> np.ndarray:
    """Experimental-group probability whose odds are oratio times the odds of p1."""
    p1 = np.asarray(p1, dtype=float)
    return oratio * p1 / (1 - p1 + oratio * p1)


def cmh_power(n1k, n2k, p1k, p2k, alpha: float, sides: int, continuity: bool = False,
              upper: bool | None = None, tail: bool = False) -> float:
    """Asymptotic power of the Cochran-Mantel-Haenszel test (Nam 1992)."""
    n1k, n2k, p1k, p2k = (np.asarray(x, dtype=float) for x in (n1k, n2k, p1k, p2k))
    if (n1k <= 0).any() or (n2k <= 0).any():
        return math.nan
    nk = n1k + n2k
    om = n1k * n2k / nk
    pk = (n1k * p1k + n2k * p2k) / nk
    ew = float((om * (p2k - p1k)).sum())
    v0 = float((om * pk * (1 - pk)).sum())
    v = float((om ** 2 * (p1k * (1 - p1k) / n1k + p2k * (1 - p2k) / n2k)).sum())
    z = sides_z(alpha, sides)
    cc = 0.5 if continuity else 0.0
    uu = (z * math.sqrt(v0) - ew + cc) / math.sqrt(v)
    ul = (-z * math.sqrt(v0) - ew - cc) / math.sqrt(v)
    pu, pl = float(st.norm.sf(uu)), float(st.norm.cdf(ul))
    if sides == 2 and not tail:         # tail: only the tail in the direction of the effect
        return pu + pl
    up = (ew > 0) if upper is None else upper
    return pu if up else pl


def cmh_sizes(weights: list[float], s: list[float], k: float, fractional: bool = False):
    """Group sizes per stratum for the multiplier k: stratum size weight x k. Equal groups
    (ratio 1/2 everywhere) split it in halves, which may be fractional (N = 201 gives 33.5 per
    group and stratum in Stata 14); otherwise the experimental group is rounded up and the
    control group takes the rest (Stata 14, case 1919)."""
    w = np.asarray(weights, dtype=float)
    sv = np.asarray(s, dtype=float)
    nk = w * k
    if np.allclose(sv, 0.5):
        return nk / 2, nk / 2
    n2 = nk * sv
    if not fractional:
        n2 = np.ceil(n2 - 1e-9)
    return nk - n2, n2


# ---------------------------------------------------------------------------
# mcc
# ---------------------------------------------------------------------------

def mcc_p1(p0: float, theta: float, rho: float) -> float:
    """Case exposure probability with odds ratio theta = p10 / p01 at correlation rho."""
    if rho == 0:
        return float(odds_probability(np.array(p0), theta))
    q0 = 1 - p0

    def g(p1):
        s = rho * math.sqrt(p1 * (1 - p1) * p0 * q0)
        return (p1 * q0 - s) - theta * ((1 - p1) * p0 - s)
    eps = 1e-9
    try:
        return float(opt.brentq(g, eps, 1 - eps, xtol=1e-14))
    except ValueError:
        raise ValueError("no valid exposure probability for these values")


def mcc_terms(p0: float, p1: float, rho: float, M: int, theta: float):
    """e_theta, nu_theta and the same at theta = 1 (VERIFY: E_1 and nu_1 are taken at theta = 1)."""
    q0, q1 = 1 - p0, 1 - p1
    s = rho * math.sqrt(p1 * q1 * p0 * q0)
    p11, p01 = p1 * p0 + s, q1 * p0 - s
    pp, pm = p11 / p1, p01 / q1
    qp, qm = 1 - pp, 1 - pm
    if min(pp, pm, qp, qm) < -1e-12:
        raise ValueError("invalid probabilities")
    pp, pm, qp, qm = (min(max(x, 0.0), 1.0) for x in (pp, pm, qp, qm))
    t = [p1 * math.comb(M, m - 1) * pp ** (m - 1) * qp ** (M - m + 1)
         + q1 * math.comb(M, m) * pm ** m * qm ** (M - m) for m in range(1, M + 1)]
    e = nu = e1 = nu1 = 0.0
    for m, tm in enumerate(t, 1):
        d = m * theta + M - m + 1
        e += m * tm * theta / d
        nu += m * tm * theta * (M - m + 1) / d ** 2
        e1 += m * tm / (M + 1)
        nu1 += m * tm * (M - m + 1) / (M + 1) ** 2
    return e, nu, e1, nu1


def mcc_power(n: float, p0: float, theta: float, rho: float, M: int, alpha: float, sides: int,
              upper: bool | None = None) -> float:
    p1 = mcc_p1(p0, theta, rho)
    e, nu, e1, nu1 = mcc_terms(p0, p1, rho, M, theta)
    z = sides_z(alpha, sides)
    s1, st_ = math.sqrt(n * nu1), math.sqrt(n * nu)
    lo = (n * (e1 - e) - z * s1) / st_
    up = (n * (e1 - e) + z * s1) / st_
    pl, pu = float(st.norm.cdf(lo)), float(st.norm.sf(up))
    if sides == 2:
        return pl + pu
    return pu if (theta > 1 if upper is None else upper) else pl


def mcc_size_start(p0: float, theta: float, rho: float, M: int, alpha: float, sides: int, power: float) -> float:
    """Closed form for the tail in the direction of the effect: Stata 14 reports it as r(init),
    the starting value of its solver (it uses z of 1 - alpha/sides, case 1919)."""
    p1 = mcc_p1(p0, theta, rho)
    e, nu, e1, nu1 = mcc_terms(p0, p1, rho, M, theta)
    za, zb = sides_z(alpha, sides), zq(power)
    return (zb * math.sqrt(nu) + za * math.sqrt(nu1)) ** 2 / (e1 - e) ** 2


# ---------------------------------------------------------------------------
# trend
# ---------------------------------------------------------------------------

def trend_power(nj, pj, xj, alpha: float, sides: int, continuity: bool = False, tail: bool = False) -> float:
    """Power of the Cochran-Armitage test for logit(p) = a + b x (Nam 1987). VERIFY: the signs of
    the one-sided bounds are the statistically coherent ones; the manual's rendering is garbled."""
    nj, pj, xj = (np.asarray(v, dtype=float) for v in (nj, pj, xj))
    n = nj.sum()
    pbar = float((nj * pj).sum() / n)
    xbar = float((nj * xj).sum() / n)
    v0 = pbar * (1 - pbar) * float((nj * (xj - xbar) ** 2).sum())
    v = float((nj * pj * (1 - pj) * (xj - xbar) ** 2).sum())
    e = float((nj * pj * (xj - xbar)).sum())
    c = (xj[1] - xj[0]) / 2 if continuity else 0.0
    z = sides_z(alpha, sides)
    uu = (z * math.sqrt(v0) + c - e) / math.sqrt(v)
    ul = (-z * math.sqrt(v0) - c - e) / math.sqrt(v)
    pu, pl = float(st.norm.sf(uu)), float(st.norm.cdf(ul))
    if sides == 2 and not tail:
        return pu + pl
    return pu if e > 0 else pl


def is_monotonic(p) -> bool:
    d = np.diff(np.asarray(p, dtype=float))
    return bool((d > 0).all() or (d < 0).all())


# ---------------------------------------------------------------------------
# cox
# ---------------------------------------------------------------------------

def cox_events(b1: float, sd: float, r2: float, alpha: float, sides: int, power: float) -> float:
    """Events for the Wald test of a covariate (Hsieh and Lavori 2000)."""
    return (sides_z(alpha, sides) + zq(power)) ** 2 / (sd ** 2 * b1 ** 2 * (1 - r2))


def cox_power(b1: float, sd: float, r2: float, n: float, pe: float, alpha: float, sides: int) -> float:
    return float(st.norm.cdf(abs(b1) * sd * math.sqrt(n * pe * (1 - r2)) - sides_z(alpha, sides)))


def cox_effect(sd: float, r2: float, n: float, pe: float, alpha: float, sides: int, power: float) -> float:
    """|b1| that reaches the power."""
    return (sides_z(alpha, sides) + zq(power)) / (sd * math.sqrt(n * pe * (1 - r2)))


# ---------------------------------------------------------------------------
# exponential
# ---------------------------------------------------------------------------

def exp_pe(lam: float, eta: float, T: float | None, r: float, gamma: float) -> float:
    """Probability of an event: follow-up to the end of the study T, accrual over [0, r] with
    truncated-exponential shape gamma (uniform for gamma = 0), loss hazard eta. T = None: followed
    until failure."""
    if T is None:
        return lam / (lam + eta)
    v = lam + eta
    if r < 1e-12:
        return lam / v * (1 - math.exp(-v * T))
    if abs(gamma) < 1e-6:
        return lam / v * (1 - (math.exp(-v * (T - r)) - math.exp(-v * T)) / (v * r))
    if abs(v - gamma) < 1e-9:
        v += 1e-7
    return lam / v * (1 + gamma * math.exp(-v * T) * (1 - math.exp((v - gamma) * r))
                      / ((v - gamma) * (1 - math.exp(-gamma * r))))


def exp_gamma(r: float, ta: float, pa: float) -> float:
    """Accrual shape with a proportion pa accrued by time ta (0 when uniform)."""
    if abs(pa - ta / r) < 1e-12:
        return 0.0

    def g(gm):
        return (1 - math.exp(-gm * ta)) / (1 - math.exp(-gm * r)) - pa
    if pa > ta / r:
        return float(opt.brentq(g, 1e-9, 1000.0 / r, xtol=1e-14))
    return float(opt.brentq(g, -1000.0 / r, -1e-9, xtol=1e-14))


def exp_xi(l1: float, l2: float, eta1: float, eta2: float, R: float, T, r: float, gamma: float,
           logtest: bool, unconditional: bool = False) -> tuple[float, float]:
    """(xi_o, xi_a) of Lachin and Foulkes (1986), hazard-difference or log-hazard-ratio test."""
    p1, p2 = 1 / (1 + R), R / (1 + R)
    lam = p1 * l1 + p2 * l2
    if unconditional:
        lam = l1          # VERIFY: lambda = lambda_1 under H0 for unconditional tests

    def zeta(lm, eta):
        pe = exp_pe(lm, eta, T, r, gamma)
        return 1 / pe if logtest else lm ** 2 / pe
    return (zeta(lam, eta1) / p1 + zeta(lam, eta2) / p2, zeta(l1, eta1) / p1 + zeta(l2, eta2) / p2)


def exp_size(delta: float, xo: float, xa: float, alpha: float, sides: int, power: float,
             unconditional: bool = False) -> float:
    za, zb = sides_z(alpha, sides), zq(power)
    if unconditional:
        return (za + zb) ** 2 * xa / delta ** 2
    return (za * math.sqrt(xo) + zb * math.sqrt(xa)) ** 2 / delta ** 2


def exp_power(delta: float, xo: float, xa: float, n: float, alpha: float, sides: int,
              unconditional: bool = False) -> float:
    za = sides_z(alpha, sides)
    if unconditional:
        return float(st.norm.cdf(abs(delta) * math.sqrt(n / xa) - za))
    return float(st.norm.cdf((abs(delta) * math.sqrt(n) - za * math.sqrt(xo)) / math.sqrt(xa)))


# ---------------------------------------------------------------------------
# logrank
# ---------------------------------------------------------------------------

def logrank_psi(hr: float, R: float, schoenfeld: bool) -> float:
    return (1 + R) / math.log(hr) if schoenfeld else (R * hr + 1) / (hr - 1)


def logrank_events(hr: float, R: float, alpha: float, sides: int, power: float, schoenfeld: bool) -> float:
    return (sides_z(alpha, sides) + zq(power)) ** 2 * logrank_psi(hr, R, schoenfeld) ** 2 / R


def logrank_power(hr: float, R: float, n: float, pe: float, alpha: float, sides: int,
                  schoenfeld: bool) -> float:
    return float(st.norm.cdf(math.sqrt(R * n * pe) / abs(logrank_psi(hr, R, schoenfeld)) - sides_z(alpha, sides)))


def logrank_pe(hr: float, R: float, s1: float | None, s2: float | None = None,
               simpson: tuple[float, float, float] | None = None) -> float:
    """Probability of an event. No survival given: no censoring. Default: average follow-up
    (Freedman); simpson = control survival at f, 0.5 r + f and T."""
    if simpson is not None:
        se = [(s + R * s ** hr) / (1 + R) for s in simpson]
        return 1 - (se[0] + 4 * se[1] + se[2]) / 6
    if s1 is None:
        return 1.0
    s2 = s1 ** hr if s2 is None else s2
    return 1 - (s1 + R * s2) / (1 + R)

files.opendta/core/smcl.py:
"""Rendering of SMCL (the help and log format) to HTML and to text.

SMCL mixes text with directives in braces. Outside paragraphs, each
line comes out as is (tables aligned by spaces); inside {p}...{p_end}
(or {pstd}, {phang}, {pmore}...), the lines form a running paragraph.

Directives handled: {title:} {cmd:} {cmdab:a:b} {opt} {opth} {it:} {bf:}
{ul:} {hi:} {res:} {txt:} {err:} {com:} {inp:} {help} {helpb} {browse}
{view} {manhelp}/{manlink} (text only), {p ...} {pstd} {phang} {pmore}
{p2colset}/{p2col} {synoptset}/{synopt}/{p2coldent} {synoptline}
{synopthdr} {hline} {.-} {c X} {col #} {space #} {tab} {break} {...}
{marker} {dlgtab} {right:} {center:} {bind:} {varlist} {newvar} {ifin}
{weight} {depvar} {indepvars} and {* comment}. Unknown directives
show the text after the colon, if any.
"""

from __future__ import annotations

import html
import re
import textwrap
from dataclasses import dataclass, field

_CHARS = {"|": "|", "-": "-", "+": "+", "TT": "-", "BT": "-", "LT": "+", "RT": "+",
          "TLC": "+", "TRC": "+", "BLC": "+", "BRC": "+", "-(": "{", ")-": "}", "S|": "$",
          "'g": "`", "a'": "á", "e'": "é", "i'": "í", "o'": "ó", "u'": "ú", "c,": "ç",
          "a~": "ã", "o~": "õ", "a^": "â", "e^": "ê", "o^": "ô", "a`": "à"}


@dataclass
class Span:
    text: str
    style: str = ""             # "", cmd, it, bf, ul, title, link, res, err, hi
    href: str = ""


@dataclass
class Block:
    kind: str                   # line | para | rule | title
    spans: list[Span] = field(default_factory=list)
    indent: int = 0             # paragraphs: indentation of the 1st line and of the others
    subindent: int = 0


def _find_close(text: str, i: int) -> int:
    """Index of the '}' that closes the '{' at i (with nesting)."""
    depth = 0
    j = i
    while j < len(text):
        if text[j] == "{":
            depth += 1
        elif text[j] == "}":
            depth -= 1
            if depth == 0:
                return j
        j += 1
    return -1


def _split_directive(body: str) -> tuple[str, str, str | None]:
    """'cmd:texto' -> ('cmd', '', 'texto'); 'help regress:texto' -> ('help', 'regress', 'texto')."""
    depth = 0
    quoted = False
    for k, ch in enumerate(body):
        if ch == '"':
            quoted = not quoted
        elif quoted:
            continue
        elif ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
        elif ch == ":" and depth == 0:
            head, text = body[:k], body[k + 1:]
            break
    else:
        head, text = body, None
    parts = head.split(None, 1)
    name = parts[0] if parts else ""
    args = parts[1] if len(parts) > 1 else ""
    return name, args, text


class _Renderer:
    def __init__(self):
        self.blocks: list[Block] = []
        self.para: Block | None = None
        self.p2col = (4, 20)        # indentation and column of p2col/synopt tables

    def spans(self, text: str, style: str = "") -> list[Span]:
        out: list[Span] = []
        i = 0
        buf = ""
        while i < len(text):
            ch = text[i]
            if ch == "{":
                j = _find_close(text, i)
                if j == -1:
                    buf += text[i:]
                    break
                if buf:
                    out.append(Span(buf, style))
                    buf = ""
                out.extend(self.directive(text[i + 1:j], style))
                i = j + 1
                continue
            buf += ch
            i += 1
        if buf:
            out.append(Span(buf, style))
        return out

    def directive(self, body: str, style: str) -> list[Span]:
        if body.startswith("*"):
            return []
        name, args, text = _split_directive(body)
        n = name.lower()
        styles = {"cmd": "cmd", "bf": "bf", "it": "it", "ul": "ul", "hi": "hi", "res": "res",
                  "result": "res", "err": "err", "error": "err", "txt": "", "text": "",
                  "com": "cmd", "inp": "cmd", "input": "cmd", "sf": "", "title": "title",
                  "hilite": "hi", "bind": style, "right": style, "center": style, "lalign": style,
                  "ralign": style}
        if n in styles:
            return self.spans(text or args or "", styles[n] or style)
        if n in ("cmdab", "opt", "opth", "opt2") and args and text is not None:
            # {opt s:hort}: the colon marks the abbreviation, not the text
            args, text = f"{args}:{text}", None
        if n == "cmdab":
            first, _, rest = (text or args).partition(":")
            return [Span(first, "cmdab"), Span(rest, "cmd")]
        if n in ("opt", "opth", "opt2"):
            t = text if text is not None else args
            m = re.fullmatch(r"([^(\s]+)(\(.*\))?", t.strip())
            if not m:
                return self.spans(t, "cmd")
            nm, arg = m.group(1), m.group(2) or ""
            ab, _, rest = nm.partition(":")
            return ([Span(ab, "cmdab"), Span(rest, "cmd")] if rest else [Span(nm, "cmd")]) + \
                ([Span(arg, "it")] if arg else [])
        if n in ("help", "helpb", "manhelp", "manhelpi", "manlink", "manlinki", "view",
                 "browse", "search", "net", "stata", "dialog"):
            target = args.strip().strip('"')
            label = text if text is not None else target
            if n in ("manhelp", "manhelpi"):
                parts = target.split()
                target = parts[0] if parts else target
                label = text if text is not None else target
            if n in ("manlink", "manlinki"):
                return self.spans(label, "bf")
            href = {"browse": target, "view": f"view:{target}", "search": f"help:{target}",
                    "stata": f"stata:{target}"}.get(n, f"help:{target}")
            return [Span(sp.text, "link", href) for sp in self.spans(label, style)]
        if n in ("varlist", "varname", "newvar", "depvar", "indepvars", "ifin", "weight",
                 "dtype", "exp", "newvarlist", "vars"):
            words = {"ifin": "[if] [in]", "weight": "[weight]", "dtype": "[type]",
                     "exp": "exp"}.get(n, n)
            return [Span(words, "it")]
        if n == "c":
            return [Span(_CHARS.get(args.strip(), args.strip()), style)]
        if n in ("hline", ".-"):
            k = args.strip()
            if k.isdigit():
                return [Span("-" * int(k), style)]
            return [Span("\x00RULE", style)]
        if n in ("space",):
            return [Span(" " * int(args or 1), style)]
        if n in ("col", "column"):
            return [Span(f"\x00COL{int(args or 1)}", style)]
        if n == "tab":
            return [Span("    ", style)]
        if n in ("break", "p_break"):
            return [Span("\x00BR", style)]
        if n == "dup":
            k = int(args or 1)
            return self.spans((text or "") * k, style)
        if n == "char":
            return [Span(chr(int(args)) if args.strip().isdigit() else args, style)]
        if n in ("marker", "viewerjumpto", "vieweralsosee", "viewerdialog", "findalias",
                 "smcl", "reset", "ul", "bind"):
            return []
        if n == "dlgtab":
            return [Span(f"\x00DLGTAB{text or args}", style)]
        return self.spans(text, style) if text is not None else []

    # -- lines and paragraphs -------------------------------------------------------------------
    _SETTINGS_ONLY = re.compile(r"^(\{(p2colset|synoptset|p2colreset|marker|viewerjumpto|"
                                r"vieweralsosee|viewerdialog|findalias|\*)[^{}]*(\{[^{}]*\})?[^{}]*\})+$")

    def feed(self, source: str) -> list[Block]:
        source = source.replace("\r\n", "\n")
        lines = source.split("\n")
        pending = ""
        for raw in lines:
            if raw.endswith("{...}"):
                body = raw[:-5]
                if self._SETTINGS_ONLY.match(body.strip() or "{*}") and not pending:
                    self.line(body)          # settings only: produces no line and does not join
                    continue
                pending += body              # {...}: the content continues on the next line
                continue
            self.line(pending + raw)
            pending = ""
        if pending:
            self.line(pending)
        self.end_para()
        return self.blocks

    def end_para(self) -> None:
        if self.para is not None:
            self.blocks.append(self.para)
            self.para = None

    def line(self, raw: str) -> None:
        s = raw
        m = re.match(r"^\{(p|pstd|phang|phang2|phang3|pmore|pmore2|pin|pin2|p2col|p2coldent|"
                     r"synopt|syntab|p2line|synoptline|synopthdr|p_end|pstd|title|marker|"
                     r"p2colset|synoptset|p2colreset|psee|pmore3)\b([^}]*)\}", s)
        if m:
            tag, args = m.group(1), m.group(2)
            rest = s[m.end():]
            if tag == "p_end":
                self.end_para()
                if rest.strip():
                    self.line(rest)
                return
            if tag in ("p2colset", "synoptset"):
                nums = [int(x) for x in re.findall(r"\d+", args)]
                if tag == "synoptset":
                    self.p2col = (2, nums[0] + 2 if nums else 20)
                elif len(nums) >= 2:
                    self.p2col = (nums[0], nums[1])
                if rest.strip():
                    self.line(rest)
                return
            if tag == "p2colreset":
                self.p2col = (4, 20)
                if rest.strip():
                    self.line(rest)
                return
            if tag in ("synoptline", "p2line"):
                self.end_para()
                self.blocks.append(Block("rule", indent=self.p2col[0]))
                return
            if tag == "synopthdr":
                self.end_para()
                label = args.strip(": ") or "options"
                width = self.p2col[1] - self.p2col[0]
                self.blocks.append(Block("line", [Span(" " * self.p2col[0] + f"{label:<{width}}"
                                                        "Description", "bf")]))
                return
            if tag in ("synopt", "p2col", "p2coldent"):
                # {synopt:{opt x}}description -> left column and text
                self.end_para()
                left_body = s[m.start():]
                j = _find_close(left_body, 0)
                inner = left_body[1:j]
                _, _, left = _split_directive(inner)
                desc = left_body[j + 1:]
                lead = 2 if tag == "p2coldent" else self.p2col[0]
                self.para = Block("para", indent=lead, subindent=self.p2col[1])
                self.para.spans = self.spans(left or "") + [Span("\x00COL" + str(self.p2col[1] + 1))]
                if desc.strip():
                    self.para.spans += self.spans(desc)
                return
            if tag == "title":
                self.end_para()
                self.blocks.append(Block("title", self.spans(s)))
                return
            if tag == "marker":
                if rest.strip():
                    self.line(rest)
                return
            self.end_para()
            ind = {"pstd": (4, 4), "phang": (4, 8), "phang2": (8, 12), "phang3": (12, 16),
                   "pmore": (8, 8), "pmore2": (12, 12), "pmore3": (16, 16), "pin": (8, 8),
                   "pin2": (12, 12), "psee": (4, 13)}.get(tag)
            if ind is None:
                nums = [int(x) for x in re.findall(r"\d+", args)]
                ind = (nums[0] if nums else 0, nums[1] if len(nums) > 1 else (nums[0] if nums else 0))
            self.para = Block("para", indent=ind[0], subindent=ind[1])
            if rest.strip():
                self.para.spans += self.spans(rest)
            return
        if self.para is not None:
            if not s.strip():
                self.end_para()
                self.blocks.append(Block("line", []))
                return
            if self.para.spans:
                self.para.spans.append(Span(" "))
            self.para.spans += self.spans(s.strip())
            return
        if s.strip().startswith("{smcl}") and not s.strip()[6:].strip():
            return
        spans = self.spans(s)
        if len(spans) == 1 and spans[0].text == "\x00RULE":
            self.blocks.append(Block("rule"))
            return
        self.blocks.append(Block("line", spans))


def parse(source: str) -> list[Block]:
    return _Renderer().feed(source)


# ---------------------------------------------------------------------------
# text output (console, batch mode)
# ---------------------------------------------------------------------------

def _plain(spans: list[Span], col0: int = 0) -> str:
    out = ""
    for sp in spans:
        t = sp.text
        if t.startswith("\x00COL"):
            target = int(t[4:]) - 1
            line_len = len(out.rsplit("\n", 1)[-1]) + col0
            out += " " * max(1, target - line_len)
            continue
        if t.startswith("\x00DLGTAB"):
            out += f"+--- {t[7:]} " + "-" * max(4, 60 - len(t))
            continue
        if t == "\x00RULE":
            out += "-" * 79
            continue
        if t == "\x00BR":
            out += "\n"
            continue
        out += t
    return out


def render_text(source: str, width: int = 79) -> str:
    lines: list[str] = []
    for b in parse(source):
        if b.kind == "rule":
            lines.append(" " * b.indent + "-" * (width - b.indent))
        elif b.kind == "para":
            pieces = _plain(b.spans, b.indent).split("\n")
            for k, piece in enumerate(pieces):
                lead = b.indent if k == 0 else b.subindent
                lines.append(textwrap.fill(" " * lead + piece.strip(), width=width,
                                           subsequent_indent=" " * b.subindent,
                                           break_long_words=False, break_on_hyphens=False))
        else:
            lines.append(_plain(b.spans).rstrip())
    return "\n".join(lines).rstrip() + "\n"


# ---------------------------------------------------------------------------
# HTML output (Viewer)
# ---------------------------------------------------------------------------

def _html_spans(spans: list[Span], colors: dict[str, str]) -> str:
    out = []
    col = 0
    for sp in spans:
        t = sp.text
        if t.startswith("\x00COL"):
            target = int(t[4:]) - 1
            pad = max(1, target - col)
            out.append("&nbsp;" * pad)
            col += pad
            continue
        if t.startswith("\x00DLGTAB"):
            label = html.escape(t[7:])
            out.append(f'<span style="color:{colors["dim"]}">+--- </span><b>{label}</b>'
                       f'<span style="color:{colors["dim"]}"> {"-" * 50}</span>')
            continue
        if t == "\x00RULE":
            out.append(f'<span style="color:{colors["dim"]}">{"-" * 79}</span>')
            continue
        if t == "\x00BR":
            out.append("<br>")
            col = 0
            continue
        col += len(t)
        e = html.escape(t).replace("  ", "&nbsp; ")
        if sp.style == "link":
            out.append(f'<a href="{html.escape(sp.href)}" style="color:{colors["link"]}">{e}</a>')
        elif sp.style in ("cmd", "bf", "title"):
            out.append(f"<b>{e}</b>")
        elif sp.style == "cmdab":
            out.append(f"<b><u>{e}</u></b>")
        elif sp.style == "it":
            out.append(f"<i>{e}</i>")
        elif sp.style == "ul":
            out.append(f"<u>{e}</u>")
        elif sp.style == "res":
            out.append(f'<span style="color:{colors["res"]}">{e}</span>')
        elif sp.style == "err":
            out.append(f'<span style="color:{colors["err"]}">{e}</span>')
        elif sp.style == "hi":
            out.append(f'<b style="color:{colors["res"]}">{e}</b>')
        else:
            out.append(e)
    return "".join(out)


LIGHT = {"text": "#000000", "res": "#000000", "err": "#cc0000", "link": "#0a5fd1", "dim": "#8e8e93",
         "bg": "#ffffff"}
DARK = {"text": "#d4d4d6", "res": "#ffffff", "err": "#ff6b68", "link": "#6cb6ff", "dim": "#8e8e93",
        "bg": "#1e1f22"}


def render_html(source: str, *, dark: bool = False, font: str = "Menlo", size: int = 12) -> str:
    colors = DARK if dark else LIGHT
    parts = [f'<html><body style="background:{colors["bg"]}; color:{colors["text"]}; '
             f'font-family:\'{font}\', monospace; font-size:{size}pt;">']
    for b in parse(source):
        if b.kind == "rule":
            parts.append(f'<div style="white-space:pre; color:{colors["dim"]}">'
                         f'{"&nbsp;" * b.indent}{"-" * (79 - b.indent)}</div>')
        elif b.kind == "para":
            # QTextBrowser does not understand the ch unit: indentation in pixels
            cw = size * 0.8
            parts.append(f'<div style="margin-left:{b.subindent * cw:.0f}px; '
                         f'text-indent:{(b.indent - b.subindent) * cw:.0f}px; '
                         f'white-space:normal; margin-top:2px; margin-bottom:2px;">'
                         f"{_html_spans(b.spans, colors)}</div>")
        elif b.kind == "title":
            parts.append(f'<div style="white-space:pre; font-weight:bold;">{_html_spans(b.spans, colors)}</div>')
        else:
            body = _html_spans(b.spans, colors) or "&nbsp;"
            parts.append(f'<div style="white-space:pre;">{body}</div>')
    parts.append("</body></html>")
    return "\n".join(parts)

files.opendta/core/sorting.py:
"""Sorting of observations (sort, gsort, bysort).

Missing values go after all numbers (. < .a < ... < .z), which is already the
natural order of the codes used. Sorting is stable. Stata does not guarantee
the order of ties without the `stable` option; here it is always stable.
"""

from __future__ import annotations

import numpy as np

from .dataset import Dataset
from .missing import SYSMISS


def _rank(data: np.ndarray) -> np.ndarray:
    if data.dtype == object:
        _, inv = np.unique(data.astype(str), return_inverse=True)
        return inv.astype(np.float64)
    return data.astype(np.float64)


def sort_order(ds: Dataset, keys: list[str], descending: list[bool] | None = None,
               *, missing_first: bool = False) -> np.ndarray:
    descending = descending or [False] * len(keys)
    cols = []
    for name, desc in zip(keys, descending):
        var = ds.get(name)
        r = _rank(var.data)
        if desc:
            if var.is_string:
                r = -r
            else:
                miss = r >= SYSMISS
                # gsort -x: missing values go last, unless mfirst
                r = np.where(miss, (-np.inf if missing_first else np.inf), -r)
        cols.append(r)
    if not cols:
        return np.arange(ds.nobs)
    return np.lexsort(cols[::-1])


def is_sorted(ds: Dataset, keys: list[str]) -> bool:
    order = sort_order(ds, keys)
    return bool(np.all(order == np.arange(ds.nobs)))


def sort(ds: Dataset, keys: list[str], descending: list[bool] | None = None, **kw) -> None:
    order = sort_order(ds, keys, descending, **kw)
    if not np.all(order == np.arange(ds.nobs)):
        ds.reorder_obs(order)
    ds.sortlist = list(keys) if not descending or not any(descending) else []

