        val = eta
    elif e.link == "log":
        val = np.exp(eta)
    elif e.link == "logit":
        val = special.expit(eta)
    elif e.link == "probit":
        val = special.ndtr(eta)
    else:
        val = -np.expm1(-np.exp(eta))
    if e.family == "ordinal" and stat != "xb":
        raise StataError(198, "predict mu is not available for ordinal outcomes")   # OpenDTA
    out[rows] = val
    return out, ""

