"""margins ([R] margins) and nlcom ([R] nlcom): average predictions, marginal
effects and nonlinear combinations, with delta-method standard errors.

The derivatives with respect to b and x are numerical (central differences)."""

from __future__ import annotations

import itertools
import re
from typing import TYPE_CHECKING

import numpy as np

from ..core import missing as M
from ..core.errors import StataError
from ..core.formats import format_value
from ..lang.syntax import match_options, parse_standard
from ..lazy import lazy
from . import fvars
from .results import LINE, CoefRow, coef_table, crit, current, g9, pvalue

# imported on first use (start-up time; see opendta/lazy.py)
special = lazy("scipy.special")
st = lazy("scipy.stats")

if TYPE_CHECKING:
    from ..session import Session

SYS = M.SYSMISS


# ---------------------------------------------------------------------------
# prediction as a function of b and of fixed values of the variables
# ---------------------------------------------------------------------------

def _xb(s: "Session", est, b: np.ndarray, rows: np.ndarray, overrides: dict) -> np.ndarray:
    """xb at rows `rows`, with variables replaced by `overrides` (var -> vector)."""
    ds = s.data
    n = len(rows)
    out = np.zeros(n)
    for j, c in enumerate(est.cols):
        if c.values is None and not c.base:
            continue
        if b[j] == 0 and c.base:
            continue
        t = est.terms[c.term]
        y = np.ones(n)
        k = 0
        for comp in t.comps:
            if comp.var in overrides and not comp.ts:
                x = overrides[comp.var]
            else:
                x = fvars.comp_values(ds, comp)[rows]
            if comp.factor:
                if isinstance(x, dict):
                    # atmeans: level indicator at its mean (proportion in the sample)
                    y = y * x.get(c.cell[k], 0.0)
                else:
                    y = y * (x == c.cell[k])
                k += 1
            else:
                y = y * x
        out += b[j] * y
    if est.constant:
        out += b[len(est.cols)]
    return out


def _transform(est, predict: str):
    """Function f(xb, b) that gives the model's default prediction, and the Expression text."""
    cmd = getattr(est, "ml_cmd", est.cmd)
    dep = est.depvar
    p = predict.strip()
    if p in ("xb", "xb()"):
        return (lambda xb, bb=None: xb), "Linear prediction, predict(xb)"
    if est.cmd == "regress" or cmd in ("regress", "areg", "xtreg", "ivregress"):
        return (lambda xb, bb=None: xb), "Linear prediction, predict()"
    if cmd in ("logit", "logistic"):
        return (lambda xb, bb=None: special.expit(xb)), f"Pr({dep}), predict()"
    if cmd == "probit":
        return (lambda xb, bb=None: st.norm.cdf(xb)), f"Pr({dep}), predict()"
    if cmd in ("poisson", "nbreg"):
        return (lambda xb, bb=None: np.exp(xb)), "Predicted number of events, predict()"
    if cmd == "glm":
        return (lambda xb, bb=None: est.glm_ginv(xb)), f"Predicted mean {dep}, predict()"
    if cmd == "tobit":
        return (lambda xb, bb=None: xb), "Linear prediction, predict()"
    if cmd in ("ologit", "oprobit"):
        m = re.fullmatch(r"outcome\(\s*#?(\d+)\s*\)", p) if p else None
        k = int(m.group(1)) if m else 1
        if p and not m:
            raise StataError(322, f"margins not yet supported by OpenDTA after {cmd} with predict({p})")
        ncut = len(est.b) - len(est.cols) - (1 if est.constant else 0)
        cdf = special.expit if cmd == "ologit" else st.norm.cdf
        if not 1 <= k <= ncut + 1:
            raise StataError(111, f"outcome {k} not found")

        def prob(xb, bb=None):
            cuts = (bb if bb is not None else est.b)[-ncut:]
            hi = cdf(cuts[k - 1] - xb) if k <= ncut else 1.0
            lo = cdf(cuts[k - 2] - xb) if k >= 2 else 0.0
            return hi - lo
        tag = f"predict(outcome({k}))" if m else "predict()"
        return prob, f"Pr({dep}=={k}), {tag}"
    raise StataError(322, f"margins not yet supported by OpenDTA after {cmd}")


def _jacobian(f, b: np.ndarray) -> np.ndarray:
    k = b.size
    f0 = np.atleast_1d(f(b))
    J = np.zeros((f0.size, k))
    for i in range(k):
        h = 1e-4 * (abs(b[i]) + 1e-3)

        def D(hh, i=i):
            a, c = b.copy(), b.copy()
            a[i] += hh
            c[i] -= hh
            return (np.atleast_1d(f(a)) - np.atleast_1d(f(c))) / (2 * hh)
        J[:, i] = (4 * D(h / 2) - D(h)) / 3     # Richardson: erro O(h⁴)
    return J


def _parse_at(s: "Session", text: str) -> list[dict]:
    """at(x=(1 2) w=3) -> list of dicts {var: value | "mean"}."""
    specs: list[tuple[str, list]] = []
    pairs = []
    i = 0
    while i < len(text):
        m = re.compile(r"\s*(\(\w+\))?\s*([\w.]+)\s*=\s*").match(text, i)
        if not m:
            break
        j = m.end()
        if j < len(text) and text[j] == "(":
            depth, k = 0, j
            while k < len(text):
                if text[k] == "(":
                    depth += 1
                elif text[k] == ")":
                    depth -= 1
                    if depth == 0:
                        break
                k += 1
            pairs.append((m.group(1), m.group(2), text[j:k + 1]))
            i = k + 1
        else:
            m2 = re.compile(r"\S+").match(text, j)
            pairs.append((m.group(1), m.group(2), m2.group(0) if m2 else ""))
            i = m2.end() if m2 else len(text)
    for stat, var, val in pairs:
        from ..core.varlist import resolve_name
        var = resolve_name(s.data, var)
        if val.startswith("("):
            vals = [float(v) for v in _numlist(val[1:-1])]
        else:
            vals = [float(val)]
        specs.append((var, vals))
    for m in re.finditer(r"\((mean|median)\)\s+([\w ]+?)(?=\s*\(|$)", text):
        for var in m.group(2).split():
            specs.append((var, ["mean"]))
    if not specs:
        return [{}]
    names = [v for v, _ in specs]
    return [dict(zip(names, combo)) for combo in itertools.product(*[vals for _, vals in specs])]


def _numlist(t: str) -> list[float]:
    out = []
    for part in t.replace(",", " ").split():
        m = re.fullmatch(r"(-?[\d.]+)\((-?[\d.]+)\)(-?[\d.]+)", part)
        if m:
            a, st_, b = float(m.group(1)), float(m.group(2)), float(m.group(3))
            x = a
            while (st_ > 0 and x <= b + 1e-9) or (st_ < 0 and x >= b - 1e-9):
                out.append(round(x, 12))
                x += st_
            continue
        if "/" in part:
            a, b = part.split("/")
            out.extend(float(v) for v in range(int(float(a)), int(float(b)) + 1))
            continue
        out.append(float(part))
    return out


def cmd_margins(s: "Session", args: str) -> None:
    est = current(s)
    p = parse_standard(args)
    o = match_options(p.options, {"dydx": 4, "eyex": 4, "dyex": 4, "eydx": 4, "at": 2, "atmeans": 3,
                                  "predict": 4, "level": 1, "post": 4, "noatlegend": 6, "nose": 4,
                                  "vce": 3, "over": 4, "asobserved": 3}) if p.options.strip() else {}
    ds = s.data
    from ..commands._util import touse
    from .postest import esample
    sample = esample(s) & touse(s, p)
    rows = np.nonzero(sample)[0]
    if not len(rows):
        raise StataError(2000, "no observations")
    f, expr = _transform(est, str(o.get("predict") or ""))
    b = est.b.copy()
    V = est.V
    lev = float(o["level"]) if o.get("level") else getattr(est, "level", 95.0)
    terms = fvars.expand_fv(ds, p.varlist) if p.varlist.strip() else []
    ats = _parse_at(s, str(o.get("at") or "")) if o.get("at") else [{}]
    atmeans = bool(o.get("atmeans"))
    means = {}
    if atmeans:
        for c in est.terms:
            for comp in c.comps:
                vals = fvars.comp_values(ds, comp)[rows]
                # Stata stores the atmeans means as float (compat 0511: changes the 7th digit of
                # the margin)
                if not comp.factor:
