    dydx_vars = []
    dydx_kind = ""
    for key in ("dydx", "eyex", "dyex", "eydx"):
        if o.get(key):
            dydx_kind = key
            txt = str(o[key]).strip()
            if txt in ("*", "_all"):
                dydx_vars = sorted({c.var for t in est.terms for c in t.comps}, key=lambda v: ds.index(v))
            else:
