                        dn = dict(ov0, **{var: x - hh})
                        return (f(_xb(s, est, bb, rows, up), bb) - f(_xb(s, est, bb, rows, dn), bb)) / (2 * hh)
                    d = (4 * D(h / 2) - D(h)) / 3
                    if dydx_kind == "eyex":
                        d = d * x / f(_xb(s, est, bb, rows, ov0), bb)
                    elif dydx_kind == "dyex":
                        d = d * x
                    elif dydx_kind == "eydx":
                        d = d / f(_xb(s, est, bb, rows, ov0), bb)
                    return float(np.mean(d))
                results.append(("", var, fn, at_lab))
        elif terms:
