                lvls = [sorted(set(ds.get(c.var).data[rows].tolist())) for c in comps]
                for cell in itertools.product(*lvls):
                    ov = dict(ov0, **{c.var: np.full(len(rows), lv) for c, lv in zip(comps, cell)})
                    lab = "#".join(f"{int(v)}" for v in cell)
