def _parse_options(args: str):
    c = find_top(args, ",")
    head, opts = (args, "") if c == -1 else (args[:c], args[c + 1:])
    # if/in after the paths
    m = re.search(r"\)\s*((?:if|in)\b.*)$", head, re.S)
    paths_text, tail = (head[:m.start() + 1], m.group(1)) if m else (head, "")
    p = parse_standard(tail + ("," + opts if opts.strip() else ""))
    o = match_options(p.options, {"standardized": 5, "method": 4, "nocapslatent": 9, "latent": 4,
                                  "covariance": 3, "variance": 3, "nolog": 4, "log": 3,
                                  "level": 1, "iterate": 4, "noheader": 6, "nodescribe": 6,
                                  "nofootnote": 7, "coeflegend": 5, "noxconditional": 3,
                                  "allmissing": 3, "group": 5, "ginvariant": 2})
    return paths_text, p, o


def cmd_sem(s: "Session", args: str) -> None:
    from .sem_out import _predict, display_sem
    from .postest import replay
    if not args.strip() or args.strip().startswith(","):
        replay(s, "sem", args)
        return
    from ..commands._util import touse
    from . import semfit
    paths_text, p, o = _parse_options(args)
    meth = str(o.get("method") or "ml").strip().lower()
    if meth not in ("ml", "mlmv", "adf"):
        raise StataError(198, f"method({meth}) not allowed")   # VERIFY
    latent_opt = set(str(o["latent"]).split()) if isinstance(o.get("latent"), str) else set()
    spec = _parse_paths(s, paths_text, latent_opt, bool(o.get("nocapslatent")))
    covs = []
    for item in str(o.get("covariance") or "").split():
        a, star, b = item.partition("*")
        if not star:
            raise StataError(198, f"invalid covariance() specification: {item}")   # VERIFY
        covs.append((a.replace("e.", ""), b.replace("e.", "")))
    var_fix = {}
    for item in str(o.get("variance") or "").split():
        name, at, val = item.partition("@")
        if at:
            var_fix[name.replace("e.", "")] = float(val)
    ds = s.data
    mask = touse(s, p)
    cols = [ds.get(n).data for n in spec.observed]
    for c in cols:
        if c.dtype.kind in "OU":
            raise StataError(109, "type mismatch")
    if meth == "mlmv":
        # observations with extended missing values (.a to .z) are dropped unless allmissing
        if not o.get("allmissing"):
            for c in cols:
                mask &= ~(c > SYS)
        nonmiss = np.zeros(len(mask), dtype=bool)
        for c in cols:
            nonmiss |= c < SYS
        mask &= nonmiss
    else:
        for c in cols:
            mask &= c < SYS
    gname = None
    levels = [None]
    if o.get("group"):
        gname = str(o["group"]).strip()
        if not ds.has(gname):
            raise StataError(111, f"variable {gname} not found")
        gcol = ds.get(gname)
        if gcol.is_string:
            raise StataError(109, "type mismatch")
        mask &= gcol.data < SYS
        levels = [float(v) for v in np.unique(gcol.data[mask])]
        if len(levels) < 2:
            raise StataError(498, "group() requires at least two groups")   # VERIFY
    elif o.get("ginvariant"):
        raise StataError(198, "option ginvariant() requires option group()")   # VERIFY
    if not mask.any():
        raise StataError(2000, "no observations")
    G = len(levels)
    inv = semfit.parse_ginvariant(o.get("ginvariant") if G > 1 else None)
    # the models: observed exogenous variables are conditioned on (Stata 14's xconditional)
    # unless the moments of one of them are constrained, noxconditional is given, or method(mlmv)
    # has missing values among them; method(adf) always uses all moments (VERIFY)
    X_all = np.column_stack([c.astype(float) for c in cols])
    X_all = np.where(np.column_stack([c >= SYS for c in cols]), np.nan, X_all)
    # e(N_missing)
    n_missing = int(np.isnan(X_all[mask]).sum())      # missing values, not observations (case 1909)
    models, datas = [], []
    for g, lev in enumerate(levels):
        mg = mask if gname is None else (mask & (ds.get(gname).data == lev))
        Xg = X_all[mg]
        lat_means: tuple[str, ...] = ()
        if g > 0 and "mcons" in inv:
            base = Model(spec, covs, var_fix)
            lat_means = tuple(L for L in spec.latent
                              if not (L in base.exog and "meanex" in inv)
                              and not (L in base.endog and "scons" in inv))
        models.append(Model(spec, covs, var_fix, lat_means))
        datas.append(semfit.build_group_data(models[-1], Xg, meth, float(lev) if lev is not None else 0.0))
    model = models[0]
    N = sum(d.N for d in datas)
    pobs = model.p
    prob = semfit.Problem(models, datas, meth, inv)
    df_s = pobs * (pobs + 3) // 2
    df = G * df_s - prob.nglob
    level = float(o["level"]) if o.get("level") else float(s.settings.get("level", "95"))
    if not o.get("nodescribe"):
        _describe_vars(s, model)
    if df < 0:
        raise StataError(503, "the model is not identified: more parameters than "
                              "moments")   # VERIFY
    # mlmv fits the saturated and the baseline models, adf the baseline model; Stata shows their
    # logs even with nolog (case 1909; their iteration paths are VERIFY, one line is shown)
    if meth in ("mlmv", "adf"):
        out = s.output
        steps = ([("saturated", "log likelihood", sum(d.ll_s for d in datas))] if meth == "mlmv" else [])
        steps.append(("baseline", "log likelihood" if meth == "mlmv" else "discrepancy",
                      sum(d.ll_b for d in datas) if meth == "mlmv"
                      else sum(d.adf["F_b"] for d in datas)))
        for what, word, v in steps:
            out.write(f"\nFitting {what} model:\n\n", "text")
            out.write(f"Iteration 0:   {word} = {g9(v, '%10.0g'):>10}  \n", "text")
    th, obj, V, conv = semfit.fit_problem(prob, s, not o.get("nolog"))
    ll_s = sum(d.ll_s for d in datas)
    ll_b = sum(d.ll_b for d in datas)
    ex_n = sum(1 for n in spec.observed if n in model.exog) if baseline_ex_correlated(model) else 0
    df_bs = G * df_s - G * (2 * pobs + ex_n * (ex_n - 1) // 2)
    if meth == "adf":
        ll = SYS
        chi2_ms = max(-obj, 0.0)
        chi2_bs = sum(d.N * d.adf["F_b"] for d in datas)
    else:
        ll = obj
        chi2_ms = max(2 * (ll_s - ll), 0.0)
        chi2_bs = max(2 * (ll_s - ll_b), 0.0)
    p_ms = float(st.chi2.sf(chi2_ms, df)) if df > 0 else SYS
    p_bs = float(st.chi2.sf(chi2_bs, df_bs)) if df_bs > 0 else SYS
    mean, cov = datas[0].mean, datas[0].cov
    base_ll = ll_b
    if G > 1:
        from .semgroup import finish_groups
        finish_groups(s, args, prob, spec, th, obj, V, conv, o, dict(
            N=N, ll=ll, df=df, chi2_ms=chi2_ms, p_ms=p_ms, chi2_bs=chi2_bs, df_bs=df_bs, p_bs=p_bs,
            ll_s=ll_s, ll_b=ll_b, level=level, mask=mask, gname=gname, levels=levels, meth=meth))
        return
    names = _param_names(model)
    th_glob, V_glob = th, V
    if prob.nglob != model.nfree:          # paths that share a label: one global entry for several items
        Tm = prob.expand_matrix()
        th, V = Tm @ th, Tm @ V @ Tm.T
    # observed exogenous variables are conditioned on: their means, variances and covariances
    # are not parameters of e(b) and are not shown (compat 1302)
    oxset = {n for n in model.exog if n in spec.observed}
    user_cov = {v for pair in covs for v in pair} | set(var_fix)
    miss_ex = meth == "mlmv" and any(bool(np.isnan(X_all[mask][:, spec.observed.index(n)]).any())
                                     for n in oxset)
    xcond = (bool(oxset) and not (oxset & user_cov) and not o.get("noxconditional")
             and meth == "ml" and not miss_ex)
    keep = [i for i, (kind, a, b) in enumerate(model.free)
            if not (xcond and kind in ("mean", "var", "cov") and a in oxset and b in oxset)]
    model.hidden = set() if not xcond else {model.free[i] for i in range(model.nfree) if i not in keep}
    est = Estimates("sem", " ".join(model.endog), [names[i][1] for i in keep], th[keep].copy(),
                    V[np.ix_(keep, keep)], N, "z", None)
    est.eqnames = [names[i][0] for i in keep]
    est.model = model
    est.level = level
    est.extra = dict(N=N, ll=ll, df=df, chi2_ms=chi2_ms, p_ms=p_ms, chi2_bs=chi2_bs, df_bs=df_bs,
                     p_bs=p_bs, mean=mean, cov=cov, ll_s=ll_s, standardized=bool(o.get("standardized")),
                     th=th.copy(), V=V, xcond=xcond, method=meth, prob=prob, mask=mask,
                     th_glob=th_glob, V_glob=V_glob)
    est.display = display_sem
    est.predict = _predict
    est.predict_opts = {"latent": 3, "xb": 2}
    from .semestat import estat_table
    est.estat = estat_table()
    lat_endog = [n for n in model.endog if n in spec.latent]
    obs_endog = [n for n in model.endog if n in spec.observed]
    lat_exog = [n for n in model.exog if n in spec.latent]
    obs_exog = [n for n in model.exog if n in spec.observed]
    # e() in Stata 14's ereturn list order (compat 1302; VERIFY the matrices' contents)
    ilog = list(prob.ilog) if prob.ilog else [ll]
    scalars = [("converged", 1.0 if conv else 0.0), ("rc", 0.0), ("ic", float(len(ilog) - 1)),
               ("N_groups", 1.0), ("modelmeans", 1.0), ("N", float(N)), ("N_missing", float(n_missing)),
               ("ll", ll), ("critvalue", ll if meth != "adf" else -obj / max(N, 1)),
               ("df_m", float(len(keep))),
               ("rank", float(np.linalg.matrix_rank(est.V))), ("estimates", 1.0),
               ("critvalue_s", ll_s), ("critvalue_b", base_ll),
               ("p_bs", p_bs), ("df_bs", float(df_bs)), ("chi2_bs", chi2_bs), ("p_ms", p_ms),
               ("df_ms", float(df)), ("chi2_ms", chi2_ms), ("df_b", float(df_s - df_bs)), ("df_s", float(df_s))]
    if meth != "mlmv":
        # VERIFY: df_s follows critvalue_b with method(ml) (compat 1302) and comes last with
        # method(mlmv) (compat 1909)
        scalars.insert(14, scalars.pop())
    if meth == "adf":
        scalars = [(k, v) for k, v in scalars if k not in ("ll", "critvalue_s", "critvalue_b")]
    first = obs_endog[0] if obs_endog else ""
    # VERIFY: _NONE when there is no observed exogenous variable (case 1909)
    covariates = " ".join(obs_exog) if xcond else ("_NONE" if not obs_exog else "")
    macros = [("cmdline", f"sem {args.strip()}"), ("covariates", covariates),
              ("cmd", "sem"), ("predict", "sem_p"), ("estat_cmd", "sem_estat"),
              ("marginsdefault", " ".join(f"predict(xb({n}))" for n in obs_endog)),
              ("marginsnotok", "XBLATent1(passthru) XBLATent LATent1(passthru) LATent SCores xb"),
              ("xconditional", "xconditional" if xcond else ""),
              ("vcetype", "OIM"), ("vce", "oim"),
              ("title", "Structural equation model"), ("method", meth), ("data", "raw"),
              ("lxvars", " ".join(lat_exog)), ("oxvars", " ".join(obs_exog)),
              ("lyvars", " ".join(lat_endog)), ("oyvars", " ".join(obs_endog)),
              ("technique", "nr"), ("properties", "b V")]
    from ..commands.matrix import Matrix
    cn = list(est.names)

    def row(v, rn="r1"):
        mt = Matrix(np.asarray(v, float).reshape(1, -1), [rn], cn)
        mt.coleq = list(est.eqnames)
        return mt
    g = (prob.grad(th_glob)[prob.gmap[0]][keep] if meth != "adf" else np.zeros(len(keep)))
    bstd = _standardized(model, th)[keep]
    J = np.zeros((len(keep), len(keep)))
    for jj, i in enumerate(keep):
        e_ = np.zeros(len(th))
        h = 1e-6 * (abs(th[i]) + 1)
        e_[i] = h
        J[:, jj] = (_standardized(model, th + e_)[keep] - _standardized(model, th - e_)[keep]) / (2 * h)
    Vstd = Matrix(J @ est.V @ J.T, cn, cn)
    Vstd.roweq = Vstd.coleq = list(est.eqnames)
    pclass = [{"path": 1, "mean": 2, "var": 3, "cov": 4}[model.free[i][0]] for i in keep]
    mats = [("gradient", row(g)), ("V_std", Vstd), ("b_std", row(bstd)),
            ("admissible", Matrix(np.ones((1, 3)), ["r1"], ["c1", "c2", "c3"])),
            ("b_pclass", row(pclass)), ("nobs", Matrix(np.array([[float(N)]]), ["r1"], ["c1"])),
            ("ilog", Matrix(np.array([ilog + [0.0] * (20 - len(ilog))])[:, :20], ["r1"],
                            [f"c{i}" for i in range(1, 21)]))]
    post(s, est, scalars, macros, mask, extra_mats=mats)
    display_sem(s, est)


def baseline_ex_correlated(model: Model) -> bool:
    """The baseline model leaves the observed exogenous variables correlated only when the model
    has observed endogenous variables; without any, every variable is uncorrelated ([SEM] methods
    and formulas for sem)."""
    return any(n in model.endog for n in model.spec.observed)


def _baseline(model: Model, mean, cov, N):
    """Baseline model: observed endogenous variables uncorrelated with everything; the
    observed exogenous variables keep their covariances (VERIFY)."""
    obs = model.spec.observed
    ex = [i for i, n in enumerate(obs) if n in model.exog] if baseline_ex_correlated(model) else []
    p = len(obs)
    Sig = np.diag(np.diag(cov)).copy()
    for i in ex:
        for j in ex:
            Sig[i, j] = cov[i, j]
    ll = float(-0.5 * N * (p * math.log(2 * math.pi) + np.linalg.slogdet(Sig)[1]
                           + np.trace(cov @ np.linalg.inv(Sig))))
    kfree = p + p + len(ex) * (len(ex) - 1) // 2
    df = p * (p + 3) // 2 - kfree
    return ll, df


def _param_names(model: Model) -> list[tuple[str, str]]:
    out = []
    for kind, a, b in model.free:
        if kind == "path":
            out.append((b, a))
        elif kind == "mean":
            out.append((a, "_cons") if a in model.endog else (f"mean({a})", "_cons"))
        elif kind == "var":
            out.append((f"var(e.{a})" if a in model.endog else f"var({a})", "_cons"))
        else:
            ea = f"e.{a}" if a in model.endog else a
            eb = f"e.{b}" if b in model.endog else b
            out.append((f"cov({ea},{eb})", "_cons"))
    return out


def _describe_vars(s: "Session", model: Model) -> None:
    out = s.output
    spec = model.spec
    obs_endog = [n for n in model.endog if n in spec.observed]
    meas = [n for n in obs_endog if all(a in spec.latent for a, b in spec.paths if b == n)]
    struct_obs = [n for n in obs_endog if n not in meas]
    lat_endog = [n for n in model.endog if n in spec.latent]
    out.write("\nEndogenous variables\n\n", "text")
    if struct_obs:
        out.write("Observed:  " if not meas else "Observed:     ", "text")
        out.write(" ".join(struct_obs) + "\n", "result")
    if meas:
        out.write("Measurement:  ", "text")
        out.write(" ".join(meas) + "\n", "result")
    if lat_endog:
        out.write("Latent:       ", "text")
        out.write(" ".join(lat_endog) + "\n", "result")
    oex = [n for n in model.exog if n in spec.observed]
    lex = [n for n in model.exog if n in spec.latent]
    if oex or lex:
        out.write("\nExogenous variables\n\n", "text")
        if oex:
            out.write("Observed:  " if not lex else "Observed:     ", "text")
            out.write(" ".join(oex) + "\n", "result")
        if lex:
            out.write("Latent:       ", "text")
            out.write(" ".join(lex) + "\n", "result")


# ---------------------------------------------------------------------------
# display
# ---------------------------------------------------------------------------

def _standardized(model: Model, th: np.ndarray) -> np.ndarray:
    """Standardized values of the parameters: paths b * sd(from) / sd(to), variances over the
    total variance, covariances as correlations; means and intercepts unchanged (VERIFY)."""
    *_, (A, S, m, B, Sv, mv) = model.implied(th)
    sd = np.sqrt(np.maximum(np.diag(Sv), 1e-300))
    out = th.copy()
    for k, (kind, a, b) in enumerate(model.free):
        ia, ib = model.idx[a], model.idx[b]
        if kind == "path":
            out[k] = th[k] * sd[ia] / sd[ib]
        elif kind == "var":
            out[k] = th[k] / Sv[ia, ia]
        elif kind == "cov":
            out[k] = th[k] / math.sqrt(S[ia, ia] * S[ib, ib]) if S[ia, ia] > 0 and S[ib, ib] > 0 else 0.0
        else:
            out[k] = th[k] / sd[ia] if a in model.exog else th[k] / sd[ia]
    return out

files.opendta/estimation/sspace.py:
"""sspace and dfactor: linear Gaussian state-space models ([TS] sspace, [TS] dfactor), estimated by
maximum likelihood with the Kalman filter of ssm.py.

Both commands translate their syntax into a ModelSpec (parameter list plus a function that builds
the system matrices) and share the fitting and display code."""

from __future__ import annotations

import math
import re
from dataclasses import dataclass, field
from typing import Callable, TYPE_CHECKING

import numpy as np

from ..core import missing as M
from ..core.errors import StataError
from ..core.stats import chi2_tail
from ..lang.syntax import find_top, match_options, parse_standard
from .ml import maximize, options as ml_options, print_log
from .results import CoefRow, Estimates, coef_table, post
from .ssm import kalman_loglik
from .tsops import require_ts

if TYPE_CHECKING:
    from ..session import Session

SYS = M.SYSMISS


@dataclass
class Param:
    name: str                 # name in e(b)
    eq: str                   # equation shown in the table ("" for the variances)
    label: str                # row label
    kind: str = "id"          # id or var
    start: float = 0.0
    hdr: str = ""             # variable shown on its own row above a lagged term (L1. under it)


@dataclass
class ModelSpec:
    cmd: str
    title: str
    deps: list[str]
    params: list[Param]
    build: Callable            # build(theta: dict[name, value], X: ndarray) -> D, A, S, H, c, d
    xcols: list[np.ndarray] = field(default_factory=list)
    diffuse: bool = False


def _split_eqs(args: str) -> tuple[list[str], str]:
    """Parenthesized equations at the top level, and the text after them."""
    eqs, i, n = [], 0, len(args)
    while i < n:
        if args[i] == "(":
            depth, j = 0, i
            while j < n:
                depth += args[j] == "("
                depth -= args[j] == ")"
                j += 1
                if depth == 0:
                    break
            eqs.append(args[i + 1:j - 1])
            i = j
        elif args[i].isspace():
            i += 1
        else:
            return eqs, args[i:]       # [if] [in] [, options]
    return eqs, ""


def parse_sspace(s: "Session", args: str):
    """Equations of sspace: list of dicts (dep, terms, state, noerror, noconstant)."""
    eqs, rest = _split_eqs(args)
    if not eqs:
        raise StataError(198, "equations required")
    out = []
    for e in eqs:
        c = find_top(e, ",")
        body, op = (e, "") if c == -1 else (e[:c], e[c + 1:])
        toks = body.split()
        if len(toks) < 1:
            raise StataError(198, "invalid equation")
        w = op.split()
        out.append({"dep": toks[0], "terms": toks[1:], "state": "state" in w,
                    "noerror": "noerror" in w, "noconstant": "noconstant" in w})
    return out, rest


def build_sspace(s: "Session", eqs: list[dict], covstate: str, covobs: str):
    if covstate not in ("diagonal", "identity") or covobs != "diagonal":
        raise StataError(198, "covstate() other than diagonal and identity, and covobserved() other than diagonal, "
                              "are not implemented in OpenDTA")   # OpenDTA
    states = [e["dep"] for e in eqs if e["state"]]
    obs = [e for e in eqs if not e["state"]]
    if not states or not obs:
        raise StataError(198, "at least one state and one observation equation required")
    r, m = len(states), len(obs)
    params: list[Param] = []
    pidx: dict[str, int] = {}        # shared parameter names
    fixed: dict[tuple, float] = {}
    entries = []                     # (kind, row, col or xindex, ref)  ref: ("p", name) | ("f", value)
    xnames: list[str] = []
    errs_state = [None] * r
    errs_obs = [None] * m

    def coef(eq_label, label, ename, spec, start, hdr=""):
        if spec is None:
            nm = f"{eq_label}:{ename}"
            params.append(Param(nm, eq_label, label, "id", start, hdr))
            return ("p", nm)
        try:
            return ("f", float(spec))
        except ValueError:
            if spec not in pidx:
                pidx[spec] = 1
                params.append(Param(spec, eq_label, label, "id", start))
            return ("p", spec)

    for k, e in enumerate(eqs if False else states):
        pass
    for kind, lst in (("S", [e for e in eqs if e["state"]]), ("O", obs)):
        for i, e in enumerate(lst):
            for t in e["terms"]:
                spec = None
                if "@" in t:
                    t, spec = t.split("@", 1)
                if t.lower().startswith("e."):
                    if spec is not None:
                        raise StataError(198, "error terms may not carry coefficients")
                    nm = t[2:]
                    if nm != e["dep"]:
                        raise StataError(198, f"error term {t} must belong to equation {e['dep']}")   # VERIFY
                    (errs_state if kind == "S" else errs_obs)[i] = nm
                    continue
                lagm = re.fullmatch(r"[lL](\d*)\.(\w+)", t)
                base = lagm.group(2) if lagm else t
                lag = (int(lagm.group(1) or 1) if lagm else 0)
                if kind == "S":
                    if lag != 1 or base not in states:
                        raise StataError(198, "state equations may contain only lagged states and error terms in OpenDTA")   # OpenDTA
                    entries.append(("A", i, states.index(base), coef(e["dep"], "L1.", t, spec, 0.1, base)))
                else:
                    if lag == 0 and base in states:
                        entries.append(("D", i, states.index(base), coef(e["dep"], base, t, spec, 1.0)))
                    else:
                        if base in states or lag:
                            raise StataError(198, "observation equations may contain only current states and exogenous variables in OpenDTA")   # OpenDTA
                        if t not in xnames:
                            xnames.append(t)
                        entries.append(("X", i, xnames.index(t), coef(e["dep"], t, t, spec, 0.0)))
            if not e["noconstant"]:
                entries.append(("C" if kind == "S" else "K", i, 0, coef(e["dep"], "_cons", "_cons", None, 0.0)))
    implicit = not any(nm for nm in errs_state + errs_obs)
    if implicit:
        # covariance form: every equation has an error unless it says noerror
        errs_state = [None if e["noerror"] else e["dep"] for e in eqs if e["state"]]
        errs_obs = [None if e["noerror"] else e["dep"] for e in obs]
    unit = set()
    for i, nm in enumerate(errs_state):
        if nm and not [e for e in eqs if e["state"]][i]["noerror"]:
            if covstate == "identity":
                unit.add(i)
                continue
            params.append(Param(f"var(e.{states[i]})", "", f"var({states[i]})" if implicit else f"var(e.{states[i]})", "var", 1.0))
    for i, nm in enumerate(errs_obs):
        if nm and not obs[i]["noerror"]:
            params.append(Param(f"var(e.{obs[i]['dep']})", "", f"var({obs[i]['dep']})" if implicit else f"var(e.{obs[i]['dep']})", "var", 1.0))
    # an equation without the e. term is exact only when noerror is given or the term is omitted
    deps = [e["dep"] for e in obs]
    pnames = {p.name for p in params}

    def val(ref, th):
        return th[ref[1]] if ref[0] == "p" else ref[1]

    def build(th, X):
        T = X.shape[0] if X.size else th["__T"]
        A = np.zeros((r, r)); D = np.zeros((m, r)); c = np.zeros(r)
        k0 = np.zeros(m); Bx = np.zeros((m, max(len(xnames), 1)))
        for kd, i, j, ref in entries:
            v = val(ref, th)
            if kd == "A": A[i, j] = v
            elif kd == "D": D[i, j] = v
            elif kd == "X": Bx[i, j] = v
            elif kd == "C": c[i] = v
            else: k0[i] = v
        S = np.zeros((r, r)); H = np.zeros((m, m))
        for i in range(r):
            if i in unit:
                S[i, i] = 1.0
            elif f"var(e.{states[i]})" in th:
                S[i, i] = th[f"var(e.{states[i]})"]
        for i in range(m):
            if f"var(e.{deps[i]})" in th:
                H[i, i] = th[f"var(e.{deps[i]})"]
        d = k0[None, :] + (X @ Bx[:, :X.shape[1]].T if xnames else 0.0)
        return D, A, S, H, c, np.broadcast_to(d, (T, m)).copy()

    return ModelSpec("sspace", "State-space model", deps, params, build), xnames


def build_dfactor(s: "Session", obs_eq: tuple, fac_eq: tuple):
    """obs_eq = (deps, exog, noconstant); fac_eq = (name, arlags)."""
    deps, exog, nocons = obs_eq
    fname, arl = fac_eq
    p = max(arl) if arl else 0
    r = max(p, 1)
    m = len(deps)
    params: list[Param] = []
    for l in arl:
        params.append(Param(f"{fname}:L{l}.{fname}", fname, f"L{l}.", "id", 0.3 if l == 1 else 0.0, fname))
    for i, dv in enumerate(deps):
        params.append(Param(f"{dv}:{fname}", dv, fname, "id", 0.5 + 0.1 * i))
        for x in exog:
            params.append(Param(f"{dv}:{x}", dv, x, "id", 0.0))
        if not nocons:
            params.append(Param(f"{dv}:_cons", dv, "_cons", "id", 0.0))
    for dv in deps:
        params.append(Param(f"var(e.{dv})", "", f"var(e.{dv})", "var", 1.0))

    def build(th, X):
        T = X.shape[0]
        A = np.zeros((r, r))
        for l in arl:
            A[0, l - 1] = th[f"{fname}:L{l}.{fname}"]
        for i in range(1, r):
            A[i, i - 1] = 1.0
        S = np.zeros((r, r)); S[0, 0] = 1.0           # the factor variance is normalized to one
        D = np.zeros((m, r)); H = np.zeros((m, m))
        d = np.zeros((T, m))
        for i, dv in enumerate(deps):
            D[i, 0] = th[f"{dv}:{fname}"]
            H[i, i] = th[f"var(e.{dv})"]
            for k, x in enumerate(exog):
                d[:, i] += th[f"{dv}:{x}"] * X[:, k]
            if not nocons:
                d[:, i] += th[f"{dv}:_cons"]
        return D, A, S, H, np.zeros(r), d

    return ModelSpec("dfactor", "Dynamic-factor model", deps, params, build), fname


def _to_nat(u, kind):
    return math.exp(min(u, 700)) if kind == "var" else u


def _fit(s: "Session", spec: ModelSpec, xnames: list[str], mask: np.ndarray, o: dict, cmdline: str,
         arg_extra: dict | None = None) -> None:
    from .tsmodels import _check_gaps, _numderiv, _sample_text
    ds = s.data
    info = require_ts(ds)
    Y = np.column_stack([ds.get(v).data.astype(float) for v in spec.deps])
    Y[Y >= SYS] = np.nan
    X = np.column_stack([ds.get(x).data.astype(float) for x in xnames]) if xnames else np.zeros((ds.nobs, 0))
    ok = mask & np.any(np.isfinite(Y), axis=1)
    if xnames:
        ok &= np.all(X < SYS, axis=1)
    t0, t1 = _check_gaps(s, ok)
    order = np.argsort(ds.get(info.tvar).data[ok], kind="stable")
    y, Xo = Y[ok][order], X[ok][order]
    T = y.shape[0]
    names = [p.name for p in spec.params]
    kinds = [p.kind for p in spec.params]
    if T < 2:
        raise StataError(2001, "insufficient observations")

    def theta(u):
        d = {p.name: _to_nat(v, p.kind) for p, v in zip(spec.params, u)}
        d["__T"] = T
        return d

    def ll(u):
        if any(abs(v) > 25 for v, k in zip(u, kinds) if k == "var"):
            return -np.inf            # variances beyond exp(+-25) are numerically meaningless
        try:
            D, A, S, H, c, d = spec.build(theta(u), Xo)
            sm = spec.diffuse
            dm = np.ones(A.shape[0], dtype=bool) if sm else None
            r = kalman_loglik(y, D, A, S, H, c, d, dm)
        except (np.linalg.LinAlgError, OverflowError):
            return -np.inf
        return -np.inf if r is None else float(r.sum())

    def fun(u, todo):
        if todo == 0:
            return ll(u), None, None
        return _numderiv(ll, u)

    vy = float(np.nanvar(y)) or 1.0
    u0 = np.array([math.log(vy * 0.5) if p.kind == "var" else p.start for p in spec.params])
    if spec.cmd == "sspace":
        # constants of the observation equations start at the sample means
        for i, p in enumerate(spec.params):
            if p.label == "_cons" and p.eq in spec.deps:
                u0[i] = float(np.nanmean(y[:, spec.deps.index(p.eq)]))
    if spec.cmd == "dfactor":
        for i, p in enumerate(spec.params):
            if p.label == "_cons" and p.eq in spec.deps:
                u0[i] = float(np.nanmean(y[:, spec.deps.index(p.eq)]))
            if p.name.startswith("var(e."):
                u0[i] = math.log(vy * 0.5)
    if not np.isfinite(ll(u0)):
        # a smaller autoregressive start usually restores feasibility
        for i, p in enumerate(spec.params):
            if p.kind == "id" and ("L" in p.label and p.label != "_cons"):
                u0[i] = 0.0
    Tm = a_c = Cmat = None
    if o.get("constraints") not in (None, True):
        # constraints() on the coefficients (not on the variances, which are estimated on the log
        # scale): u = Tm uc + a (core/constraints.py)
        from types import SimpleNamespace
        from ..core.constraints import constraint_transform
        from .postest import _constraint
        from .sysmodels import _constraints, _numlist
        fake = SimpleNamespace(names=[p.label for p in spec.params], eqnames=[p.eq or "" for p in spec.params])
        defined = _constraints(s)
        crow = []
        for cn_ in _numlist(str(o["constraints"])):
            if cn_ not in defined:
                raise StataError(111, f"constraint {cn_} not found")
            coef, rhs = _constraint(s, fake, defined[cn_])
            if any(spec.params[j].kind == "var" for j in coef):
                raise StataError(198, "constraints on variances are not available in OpenDTA")   # OpenDTA
            row = np.zeros(len(u0) + 1)
            for j, v in coef.items():
                row[j] += v
            row[-1] = rhs
            crow.append(row)
        Cmat = np.array(crow)
        Tm, a_c = constraint_transform(Cmat)
        a_c = a_c.ravel()
        u0 = a_c + Tm @ (Tm.T @ (u0 - a_c))
    if not np.isfinite(ll(u0)):
        raise StataError(430, "initial values not feasible")
    if Tm is not None:
        def cfun(uc, todo):
            l_, g_, H_ = fun(Tm @ uc + a_c, todo)
            return (l_, g_, H_) if g_ is None else (l_, Tm.T @ g_, Tm.T @ H_ @ Tm)
        r = maximize(cfun, Tm.T @ (u0 - a_c), **ml_options(o))
        r.b = Tm @ r.b + a_c
    else:
        r = maximize(fun, u0, **ml_options(o))
    out = s.output
    if not o.get("nolog"):
        out.write("\n", "text")
        print_log(out, r, "log likelihood")
    u = r.b
    _l, _g, Hm = _numderiv(ll, u)
    Tq = Tm if Tm is not None else np.eye(len(u))
    try:
        Vu = Tq @ np.linalg.inv(-(Tq.T @ Hm @ Tq)) @ Tq.T
    except np.linalg.LinAlgError:
        Vu = Tq @ np.linalg.pinv(-(Tq.T @ Hm @ Tq)) @ Tq.T
    nat = np.array([_to_nat(v, k) for v, k in zip(u, kinds)])
    J = np.array([nat[i] if kinds[i] == "var" else 1.0 for i in range(len(u))])
    V = J[:, None] * Vu * J[None, :]
    V = (V + V.T) / 2
    se = np.sqrt(np.maximum(np.diag(V), 0))
    D, A, S, H, c, d = spec.build(theta(u), Xo)
    # Wald test of all the coefficients other than the variances
    idx = [i for i, p in enumerate(spec.params) if p.kind == "id"]
    df_w = len(idx)
    try:
        if Tm is not None and idx:
            # the test has the rank of the constrained variance (VERIFY)
            df_w = int(np.linalg.matrix_rank(V[np.ix_(idx, idx)]))
            chi2 = float(nat[idx] @ np.linalg.pinv(V[np.ix_(idx, idx)]) @ nat[idx]) if df_w else SYS
        else:
            chi2 = float(nat[idx] @ np.linalg.solve(V[np.ix_(idx, idx)], nat[idx])) if idx else SYS
    except np.linalg.LinAlgError:
        chi2 = SYS
    pv = float(chi2_tail(chi2, df_w)) if chi2 < SYS else SYS
    rows: list[CoefRow] = []
    last, lasth = None, ""
    for i, p in enumerate(spec.params):
        if p.eq and p.eq != last:
            if last is not None:
                rows.append(CoefRow("sep"))
            rows.append(CoefRow("eq", p.eq))
            last, lasth = p.eq, ""
        elif not p.eq and last is not None:
            rows.append(CoefRow("sep"))
            last, lasth = None, ""
        if p.hdr and p.hdr != lasth:
            if lasth:
                rows.append(CoefRow("blank"))
            rows.append(CoefRow("header", p.hdr))
        lasth = p.hdr
        kind_ = "cons" if Tm is not None and se[i] < 1e-12 else "coef"     # fixed by a constraint
        rows.append(CoefRow(kind_, p.label, nat[i], se[i], name=p.name, tight=p.kind == "var", zero_lo=p.kind == "var"))
    est = Estimates(spec.cmd, " ".join(spec.deps), names, nat, V, T, "z", None)
    est.eqnames = [p.eq or "_" for p in spec.params]
    est.rows = rows
    est.level = float(o["level"]) if isinstance(o.get("level"), str) else float(s.settings.get("level", "95"))
    est.vcetype = "OIM"
    cns_text = []
    if Cmat is not None:
        from .postest import _ctext
        cns_text = [_ctext(fake, {j: float(v) for j, v in enumerate(row[:-1]) if v}, float(row[-1])) for row in Cmat]
    est.extra = {"N": float(T), "ll": r.ll, "chi2": chi2, "p": pv, "df_m": df_w, "title": spec.title,
                 "cns_text": cns_text,
                 "sample": _sample_text(s, t0, t1)}
    est.ssm = {"spec": spec, "u": u, "y": y, "X": Xo, "mask": ok.copy(), "order": order}
    est.display = display_ssm
    est.predict = _predict_ssm
    nvar = sum(1 for k in kinds if k == "var")
    scalars = [("N", float(T)), ("k", float(len(u))), ("k_aux", float(nvar)), ("k_eq", float(len(spec.deps))),
               ("k_dv", float(len(spec.deps))), ("df_m", float(len(idx))), ("ll", r.ll), ("chi2", chi2), ("p", pv),
               ("tmin", t0), ("tmax", t1), ("rank", float(len(u))), ("ic", float(r.iterations)), ("rc", 0.0),
               ("converged", 1.0 if r.converged else 0.0)]
    macros = [("cmd", spec.cmd), ("cmdline", cmdline), ("depvar", " ".join(spec.deps)), ("title", spec.title),
              ("tvar", info.tvar), ("vce", "oim"), ("vcetype", "OIM"), ("chi2type", "Wald"),
              ("properties", "b V")]
    post(s, est, scalars, macros, ok)
    display_ssm(s, est)


def display_ssm(s: "Session", est: Estimates, *, header: bool = True, table: bool = True,
                level: float | None = None, **_kw) -> None:
    from .results import g9
    from .tsmodels import _right
    out = s.output
    x = est.extra
    if header:
        out.write(f"\n{x['title']}\n\n", "text")
        _right(out, x["sample"].replace("Sample:  ", "Sample: "), "Number of obs", f"{int(x['N']):,}")
        _right(out, "", f"Wald chi2({int(x['df_m'])})", g9(x["chi2"], "%10.2f"))
        _right(out, f"Log likelihood = {g9(x['ll'], '%10.0g'):>10}", "Prob > chi2", g9(x["p"], "%10.4f"))
        if x.get("cns_text"):
            out.write("\n", "text")
            for i, t_ in enumerate(x["cns_text"], 1):
                out.write(f" ({i:>2})  {t_}\n", "text")              # VERIFY: place of the list
    if table:
        coef_table(s, est.depvar.split()[0] if est.cmd == "sspace" else "", est.rows, stat="z", df=None, level=level or est.level, vcetype=est.vcetype)
        out.write("Note: Tests of variances against zero are one sided, and the two-sided\n"
                  "      confidence intervals are truncated at zero.\n", "text")


_OPTS = {"covstate": 3, "covobserved": 3, "constraints": 3, "from": 3, "vce": 3, "robust": 1, "level": 1,
         "nolog": 3, "iterate": 4, "tolerance": 3, "ltolerance": 4, "nrtolerance": 4, "technique": 4,
         "difficult": 4, "trace": 5, "diffuse": 4, "nocnsreport": 5, "collinear": 4, "covariance": 3,
         "noconstant": 4}


def _prep(s, args, name):
    from .postest import replay
    if not args.strip() or args.strip().startswith(","):
        replay(s, name, args)
        return None
    return True


def cmd_sspace(s: "Session", args: str) -> None:
    from .regress import cmdline
    if not _prep(s, args, "sspace"):
        return
    # "if"/"in" may follow the equations before the comma
    eqs, rest = parse_sspace(s, args)
    c = find_top(rest, ",") if rest else -1
    pre, opts = (rest, "") if c == -1 else (rest[:c], rest[c + 1:])
    p = parse_standard(pre) if pre.strip() else parse_standard("")
    o = match_options(opts, _OPTS) if opts.strip() else {}
    for bad in ("from", "vce"):
        if o.get(bad):
            raise StataError(198, f"option {bad}() not implemented in OpenDTA")   # OpenDTA
    from ..commands._util import touse
    mask = touse(s, p)
    spec, xnames = build_sspace(s, eqs, str(o.get("covstate", "diagonal")), str(o.get("covobserved", "diagonal")))
    spec.diffuse = bool(o.get("diffuse"))
    _fit(s, spec, xnames, mask, o, cmdline("sspace", args))


def cmd_dfactor(s: "Session", args: str) -> None:
    from .regress import cmdline
    from ..commands._util import touse
    if not _prep(s, args, "dfactor"):
        return
    eqs, rest = _split_eqs(args)
    if len(eqs) != 2:
        raise StataError(198, "one observed-variables equation and one factor equation required")   # OpenDTA
    c = find_top(rest, ",") if rest else -1
    pre, opts = (rest, "") if c == -1 else (rest[:c], rest[c + 1:])
    p = parse_standard(pre) if pre.strip() else parse_standard("")
    o = match_options(opts, _OPTS) if opts.strip() else {}
    for bad in ("from", "vce"):
        if o.get(bad):
            raise StataError(198, f"option {bad}() not implemented in OpenDTA")   # OpenDTA
    if o.get("covariance") and str(o["covariance"]) != "diagonal":
        raise StataError(198, "covariance() other than diagonal not implemented in OpenDTA")   # OpenDTA
    parts = []
    for e in eqs:
        cc = find_top(e, ",")
        body, op = (e, "") if cc == -1 else (e[:cc], e[cc + 1:])
        if "=" not in body:
            raise StataError(198, "equations must have the form (varlist = ...)")
        lhs, rhs = body.split("=", 1)
        parts.append((lhs.split(), rhs.split(), op))
    (od, ox, oop), (fd, fx, fop) = parts
    if len(fd) != 1 or fx:
        raise StataError(198, "factor equation must be (factorname = , ar(numlist))")   # OpenDTA
    odeps = s.expand_varlist(" ".join(od))
    exog = s.expand_varlist(" ".join(ox)) if ox else []
    m_ = re.search(r"\bar\(([^)]*)\)", fop)
    from .tsmodels import _lags
    arl = _lags(m_.group(1)) if m_ else []
    if re.search(r"\bma\(|\barstructure|\bcovstructure|\bcovariance", oop + fop):
        raise StataError(198, "ma(), arstructure() and error autoregressions not implemented in OpenDTA")   # OpenDTA
    spec, _f = build_dfactor(s, (odeps, exog, "noconstant" in oop.split()), (fd[0], arl))
    _fit(s, spec, exog, touse(s, p), o, cmdline("dfactor", args))


def _predict_ssm(s: "Session", est: Estimates, stat: str, mask: np.ndarray):
    """One-step predictions (xb, the default), residuals and standardized residuals of one observed
    variable (equation(), the first by default) over the estimation sample. VERIFY: states, the
    smethod() and dynamic() options."""
    from .ssm import kalman_onestep
    M_ = est.ssm
    spec, u = M_["spec"], M_["u"]
    th = {p.name: _to_nat(v, p.kind) for p, v in zip(spec.params, u)}
    th["__T"] = M_["y"].shape[0]
    D, A, S, H, c, d = spec.build(th, M_["X"])
    dm = np.ones(A.shape[0], dtype=bool) if spec.diffuse else None
    yhat, fv, Fs = kalman_onestep(M_["y"], D, A, S, H, c, d, dm, full=True)
    eq = str((getattr(est, "_pred_opts", {}) or {}).get("equation") or "").strip().lstrip("#")
    j = 0
    if eq:
        j = int(eq) - 1 if eq.isdigit() else (spec.deps.index(eq) if eq in spec.deps else -1)
        if not 0 <= j < len(spec.deps):
            raise StataError(198, f"equation {eq} not found")                     # VERIFY
    rows = np.nonzero(M_["mask"])[0][M_["order"]]
    out = np.full(s.data.nobs, SYS)
    if stat in ("", "xb"):
        out[rows] = yhat[:, j]
        # dfactor names the default y (compat 1915)
        return out, "" if stat else f"(option {'y' if est.cmd == 'dfactor' else 'xb'} assumed; fitted values)"
    e = M_["y"][:, j] - yhat[:, j]
    if stat == "residuals":
        out[rows] = np.where(np.isfinite(e), e, SYS)
    elif stat == "rstandard":
        # the innovations standardized jointly, by the Cholesky factor of their covariance
        # (VERIFY, compat 1915: the second equation of a dfactor model has Stata's minimum and
        # maximum but not its mean; also with missing values)
        E = M_["y"] - yhat
        z = np.full(len(e), np.nan)
        for t in range(len(e)):
            if np.all(np.isfinite(E[t])):
                z[t] = np.linalg.solve(np.linalg.cholesky(Fs[t]), E[t])[j]
            elif np.isfinite(e[t]):
                z[t] = e[t] / np.sqrt(fv[t, j])
        out[rows] = np.where(np.isfinite(z), z, SYS)
    else:
        raise StataError(198, f"option {stat} not allowed")                      # VERIFY
    return out, ""

