"""Time series and panels: tsset, xtset and the L. F. D. S. operators
([TS] tsset, [XT] xtset, [U] 11.4.4 time-series varlists).

The declaration is kept in the _dta characteristics, as in Stata (_TStvar,
_TSpanel, _TSdelta), and so it travels with the saved file.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import TYPE_CHECKING

import numpy as np

from ..core import missing as M
from ..core.errors import StataError

if TYPE_CHECKING:
    from ..core.dataset import Dataset
    from ..session import Session

SYS = M.SYSMISS


@dataclass
class TSInfo:
    tvar: str
    panel: str = ""
    delta: float = 1.0


def ts_info(ds: "Dataset") -> TSInfo | None:
    ch = ds.chars.get("_dta", {})
    tvar = ch.get("_TStvar", "")
    if not tvar or not ds.has(tvar):
        return None
    panel = ch.get("_TSpanel", "")
    if panel and not ds.has(panel):
        panel = ""
    try:
        delta = float(ch.get("_TSdelta", "1") or 1)
    except ValueError:
        delta = 1.0
    return TSInfo(tvar, panel, delta)


def panel_info(ds: "Dataset") -> str:
    """Panel variable declared by xtset (with or without time)."""
    ch = ds.chars.get("_dta", {})
    p = ch.get("_TSpanel", "") or ch.get("iis", "")
    return p if p and ds.has(p) else ""


def require_ts(ds: "Dataset") -> TSInfo:
    info = ts_info(ds)
    if info is None:
        # VERIFY texto exato
        raise StataError(111, "time variable not set")
    return info


class _TSIndex:
    """Index (panel, time) -> observation, vectorized: the keys become
    integers panel*(range+1) + (t - tmin) and the lookup is binary."""

    def __init__(self, ds: "Dataset", info: TSInfo):
        n = ds.nobs
        t = ds.get(info.tvar).data.astype(np.float64)
        pv = ds.get(info.panel).data.astype(np.float64) if info.panel else np.zeros(n)
        self.ok = (t < SYS) & (pv < SYS)
        self.t, self.pv = t, pv
        self.n = n
        tt = t[self.ok]
        if not len(tt):
            self.keys = np.zeros(0, dtype=np.int64)
            self.order = np.zeros(0, dtype=np.int64)
            return
        self.tmin = float(tt.min())
        span = float(tt.max()) - self.tmin
        codes = np.zeros(n, dtype=np.int64)
        codes[self.ok] = np.unique(pv[self.ok], return_inverse=True)[1]
        self.codes = codes
        npan = int(codes.max()) + 1
        # margin so that t - step leaves the range without colliding with another panel
        self.width = int(3 * span + 3)
        self.vector = (npan + 1) * self.width < 2 ** 62
        if self.vector:
            key = codes * self.width + (t - self.tmin + span + 1)
            key = np.where(self.ok, key, -1).astype(np.int64)
            idx = np.nonzero(self.ok)[0]
            self.order = idx[np.argsort(key[idx], kind="stable")]
            self.keys = key[self.order]
            self.span = span
        else:
            self.lookup = {(pv[i], t[i]): i for i in np.nonzero(self.ok)[0]}

    def source(self, step: float) -> np.ndarray:
        """For each observation, the row with time t - step in the same panel (-1 if none)."""
        out = np.full(self.n, -1, dtype=np.int64)
        if not self.ok.any():
            return out
        if not self.vector:
            for i in np.nonzero(self.ok)[0]:
                out[i] = self.lookup.get((self.pv[i], self.t[i] - step), -1)
            return out
        tq = self.t - step
        inside = self.ok & (np.abs(tq - self.tmin) <= 2 * self.span + 1)
        q = (self.codes * self.width + (tq - self.tmin + self.span + 1)).astype(np.int64)
        pos = np.searchsorted(self.keys, q)
        pos = np.clip(pos, 0, max(len(self.keys) - 1, 0))
        hit = inside & (self.keys[pos] == q) & (np.round(tq) == tq)
        out[hit] = self.order[pos[hit]]
        return out


def shift(ds: "Dataset", values: np.ndarray, k: int, index: _TSIndex | None = None) -> np.ndarray:
    """Value of `values` k periods before (k > 0, lag) or after (k < 0, lead),
    in the same panel; missing when the period does not exist."""
    info = require_ts(ds)
    index = index or _TSIndex(ds, info)
    src = index.source(k * info.delta)
    vals = np.asarray(values, dtype=np.float64)
    return np.where(src >= 0, vals[np.clip(src, 0, None)], SYS) if len(vals) else vals.copy()


def apply_ops(ds: "Dataset", ops: list[tuple[str, int]], values: np.ndarray) -> np.ndarray:
    """Applies the operators (letter, order) to a vector. L and F add up to a
    net shift (LF.y = y, as in Stata, compat 0503); D and S are
    applied before the shift (the operators commute)."""
    x = np.asarray(values, dtype=np.float64)
    index = _TSIndex(ds, require_ts(ds))
    net = sum(k for op, k in ops if op == "L") - sum(k for op, k in ops if op == "F")
    rest = [(op, k) for op, k in ops if op not in "LF"]
    if net:
        rest.append(("L", net) if net > 0 else ("F", -net))
    for op, k in rest:
        for _ in range(k if op in "DS" else 1):
            if op == "L":
                y = shift(ds, x, k, index)
            elif op == "F":
                y = shift(ds, x, -k, index)
            elif op == "D":
                prev = shift(ds, x, 1, index)
                y = np.where((x < SYS) & (prev < SYS), x - prev, SYS)
            elif op == "S":
                # seasonal S.x: x - L.x; Sk.x = x - Lk.x (applied once)
                prev = shift(ds, x, k, index)
                y = np.where((x < SYS) & (prev < SYS), x - prev, SYS)
                x = y
                break
            else:
                raise StataError(198, f"{op}: unknown operator")
            x = y
    return x


def ops_name(ops: list[tuple[str, int]]) -> str:
    """Canonical prefix: [('L', 2), ('D', 1)] -> 'L2D'. VERIFY the order."""
    out = []
    for op, k in ops:
        out.append(op + (str(k) if k != 1 else ""))
    return "".join(out)


# ---------------------------------------------------------------------------
# tsset / xtset
# ---------------------------------------------------------------------------

_UNITS = {"d": "day", "w": "week", "m": "month", "q": "quarter", "h": "halfyear", "y": "year",
          "c": "ms", "C": "ms"}


def _fmt_time(ds: "Dataset", tvar: str, x: float) -> str:
    from ..core.formats import format_value
    v = ds.get(tvar)
    if v.fmt.startswith("%t"):
        return format_value(x, v.fmt, pad=False).strip()
    return format_value(x, "%9.0g", pad=False).strip()


def _declare(s: "Session", args: str, *, xt: bool) -> None:
    from ..core.varlist import resolve_name
    from ..lang.syntax import match_options
    ds = s.data
    head, comma, opts = args.partition(",")
    words = head.split()
    o = match_options(opts, {"delta": 1, "clear": 5, "daily": 5, "weekly": 6, "monthly": 7,
                             "quarterly": 9, "yearly": 6, "generic": 7, "format": 3}) \
        if comma and opts.strip() else {}
    ch = ds.chars.setdefault("_dta", {})
    if o.get("clear"):
        for k in ("_TStvar", "_TSpanel", "_TSdelta", "_TSitrvl", "tis", "iis"):
            ch.pop(k, None)
        return
    if not words:
        info = ts_info(ds)
        if xt:
            p = panel_info(ds)
            if not p:
                raise StataError(459, "panel variable not set; use xtset varname ...")   # VERIFY
            _report(s, p, info.tvar if info else "", info.delta if info else 1.0, xt=True)
        else:
            if info is None:
                raise StataError(111, "time variable not set")
            _report(s, info.panel, info.tvar, info.delta, xt=False)
        return
    names = [resolve_name(ds, w) for w in words]
    if len(names) > 2:
        raise StataError(103, "too many variables specified")
    if xt:
        panel = names[0]
        tvar = names[1] if len(names) > 1 else ""
    else:
        panel, tvar = (names[0], names[1]) if len(names) == 2 else ("", names[0])
    for nm in [panel, tvar]:
        if nm and ds.get(nm).is_string:
            raise StataError(109, f"variable {nm} must be numeric")   # VERIFY
    delta = 1.0
    if o.get("delta"):
        delta = float(s.eval(str(o["delta"]).split()[0]))
    if tvar:
        t = ds.get(tvar).data
        if np.any((t < SYS) & (t != np.trunc(t))):
            raise StataError(451, "time variable must contain only integer values")   # VERIFY
        pv = ds.get(panel).data if panel else np.zeros(ds.nobs)
        seen: set = set()
        for i in range(ds.nobs):
            if t[i] >= SYS or pv[i] >= SYS:
                continue
            key = (pv[i], t[i])
            if key in seen:
                raise StataError(451, "repeated time values within panel" if panel
                                 else "repeated time values in sample")
            seen.add(key)
    ch.pop("_TStvar", None)
    ch.pop("_TSpanel", None)
    ch.pop("_TSdelta", None)
    if panel:
        ch["_TSpanel"] = panel
    if tvar:
        ch["_TStvar"] = tvar
        ch["_TSdelta"] = f"{delta:g}"
    # tsset/xtset sorts the data by panel and time
    from ..core.sorting import sort
    keys = [k for k in (panel, tvar) if k]
    sort(ds, keys)
    _report(s, panel, tvar, delta, xt=xt)
    s.notify_state()


def _report(s: "Session", panel: str, tvar: str, delta: float, *, xt: bool) -> None:
    ds = s.data
    out = s.output
    s.r = {}
    pv = ds.get(panel).data if panel else np.zeros(ds.nobs)
    t = ds.get(tvar).data if tvar else None
    if panel:
        balance = "strongly balanced"
        if t is not None:
            ok = (pv < SYS) & (t < SYS)
            sets: dict[float, set] = {}
            for p_, tt in zip(pv[ok], t[ok]):
                sets.setdefault(p_, set()).add(tt)
            vals = list(sets.values())
            if vals and any(v != vals[0] for v in vals):
                lens = {len(v) for v in vals}
                balance = "weakly balanced" if len(lens) == 1 else "unbalanced"
        out.write(f"{'panel variable:':>22}  ", "text")
        out.write(f"{panel} ({balance})\n", "result")
    if t is not None:
        ok = t < SYS
        if panel:
            ok &= pv < SYS
        tmin, tmax = (float(t[ok].min()), float(t[ok].max())) if ok.any() else (SYS, SYS)
        ngaps = 0
        if ok.any():
            groups: dict[float, list[float]] = {}
            for p_, tt in zip(pv[ok], t[ok]):
                groups.setdefault(p_, []).append(tt)
            for ts in groups.values():
                ts = sorted(ts)
                ngaps += sum(1 for a, b in zip(ts, ts[1:]) if abs((b - a) - delta) > 1e-9)
        gaps = ngaps > 0
        line = f"{tvar}, {_fmt_time(ds, tvar, tmin)} to {_fmt_time(ds, tvar, tmax)}"
        if gaps:
            line += ", but with a gap" if ngaps == 1 else ", but with gaps"
        out.write(f"{'time variable:':>22}  ", "text")
        out.write(line + "\n", "result")
        fmt = ds.get(tvar).fmt
        unit = "unit" if not fmt.startswith("%t") else _UNITS.get(fmt[2:3], "unit")
        dtext = f"{delta:g} {unit}" + ("s" if delta != 1 else "")
        out.write(f"{'delta:':>22}  ", "text")
        out.write(dtext + "\n", "result")
        tfmt = ds.get(tvar).fmt
        code = tfmt[2:3] if tfmt.startswith("%t") else ""
        tmins, tmaxs = _fmt_time(ds, tvar, tmin), _fmt_time(ds, tvar, tmax)
        res = {}
        if panel:
            res["balanced"] = balance
        res["tmins"], res["tmaxs"], res["tdeltas"] = tmins, tmaxs, dtext
        res["tsfmt"] = tfmt
        res["unit1"] = code or "."     # VERIFY for %t formats
        if code:
            res["unit"] = {"d": "daily", "w": "weekly", "m": "monthly", "q": "quarterly",
                           "h": "halfyearly", "y": "yearly", "c": "clocktime", "C": "clocktime"}[code]
        res["timevar"] = tvar
        if panel:
            res["panelvar"] = panel
            pvals = pv[pv < SYS]
            res["imin"] = float(pvals.min()) if len(pvals) else SYS
            res["imax"] = float(pvals.max()) if len(pvals) else SYS
        res["tmin"], res["tmax"], res["tdelta"] = tmin, tmax, float(delta)
        s.r = res          # Stata lists in the reverse order of storage
        return
    if panel:
        s.r["panelvar"] = panel


def cmd_tsset(s: "Session", args: str) -> None:
    _declare(s, args, xt=False)


def cmd_xtset(s: "Session", args: str) -> None:
    _declare(s, args, xt=True)

files.opendta/graphics/data.py:
"""Graph data: sample (if/in), labels, by() groups and the computations
of histogram, kdensity, fits (lfit/qfit) and boxes (graph box).

Formulas taken from manuals [G-2] and [R] (histogram, kdensity, graph box);
undocumented points have the VERIFY mark."""

from __future__ import annotations

import math
from typing import TYPE_CHECKING, Iterator

import numpy as np

from ..core import missing as M
from ..core import stats as S
from ..core.errors import StataError
from ..core.formats import format_value
from ..lang.syntax import Parsed

if TYPE_CHECKING:
    from ..session import Session

SYS = M.SYSMISS


def base_mask(s: "Session", p: Parsed) -> np.ndarray:
    from ..commands._util import touse
    return touse(s, p)


def numeric(s: "Session", name: str) -> np.ndarray:
    v = s.data.get(name)
    if v.is_string:
        raise StataError(109, "type mismatch")
    return np.asarray(v.data, dtype=np.float64)


def valid(x: np.ndarray) -> np.ndarray:
    return x < SYS


def nan(x: np.ndarray) -> np.ndarray:
    y = np.asarray(x, dtype=np.float64).copy()
    y[y >= SYS] = np.nan
    return y


def var_title(s: "Session", name: str) -> str:
    v = s.data.get(name)
    return v.label or v.name


def value_labels(s: "Session", name: str) -> dict:
    v = s.data.get(name)
    if not v.value_label:
        return {}
    return dict(s.data.value_labels.get(v.value_label, {}))


def value_text(s: "Session", name: str, x) -> str:
    v = s.data.get(name)
    if v.is_string:
        return str(x)
    if x >= SYS:
        return M.missing_name(x)
    labs = value_labels(s, name)
    if float(x).is_integer() and int(x) in labs:
        return labs[int(x)]
    return format_value(float(x), v.fmt, pad=False).strip()


def groups(s: "Session", mask: np.ndarray, byvars: list[str], *, missing: bool = False
           ) -> Iterator[tuple[list, np.ndarray]]:
    """by()/over() groups: (values, mask), in increasing order."""
    if not byvars:
        yield [], mask
        return
    cols = []
    for b in byvars:
        v = s.data.get(b)
        cols.append(np.asarray(v.raw if v.is_string else v.data))
    keep = mask.copy()
    if not missing:
        for b, c in zip(byvars, cols):
            if not s.data.get(b).is_string:
                keep &= c < SYS
    idx = np.flatnonzero(keep)
    keys = sorted({tuple(c[i] for c in cols) for i in idx},
                  key=lambda t: tuple((0, x) if not isinstance(x, str) else (1, x) for x in t))
    for key in keys:
        m = keep.copy()
        for c, k in zip(cols, key):
            m &= (c == k)
        yield list(key), m


def group_title(s: "Session", byvars: list[str], key: list) -> str:
    return ", ".join(value_text(s, b, k) for b, k in zip(byvars, key))


def weights(s: "Session", p: Parsed, mask: np.ndarray, allowed=("fweight", "aweight")):
    if p.weight is None:
        return None, mask
    from ..commands.summarize import weights as _w
    w, _, mask = _w(s, p, mask, allowed)
    return w, mask


# ---------------------------------------------------------------------------
# histogram
# ---------------------------------------------------------------------------

def hist_bins(x: np.ndarray, w: np.ndarray | None, opts: dict) -> dict:
    """Histogram bins. opts: bin, width, start, discrete, and the scale
    (density, fraction, frequency, percent). Returns centers, heights,
    width, start and number of bins."""
    n = len(x)
    if n == 0:
        raise StataError(2000, "no observations")
    ww = np.ones(n) if w is None else w
    W = float(ww.sum())
    xmin, xmax = float(x.min()), float(x.max())
    if opts.get("discrete"):
        vals = np.unique(x)
        if "width" in opts:
            width = float(opts["width"])
        else:
            # VERIFY: width = smallest difference between distinct values
            width = float(np.min(np.diff(vals))) if len(vals) > 1 else 1.0
        start = float(opts.get("start", xmin))
        k = int(math.floor((xmax - start) / width + 1e-9)) + 1
        idx = np.floor((x - start) / width + 0.5).astype(int)
        idx = np.clip(idx, 0, k - 1)
        centers = start + width * np.arange(k)
    else:
        start = float(opts["start"]) if "start" in opts else xmin
        if start > xmin:
            raise StataError(198, "start() must be less than or equal to the minimum")   # VERIFY
        if "width" in opts:
            width = float(opts["width"])
            # the maximum goes into the last bin (compat 0701: width(2) start(0) with maximum 10
            # gives 5 bins)
            k = max(1, int(math.ceil((xmax - start) / width - 1e-9)))
        else:
            if "bin" in opts:
                k = int(opts["bin"])
            else:
                # [R] histogram: k = min(sqrt(N), 10 ln(N)/ln(10)), truncado
                k = int(min(math.sqrt(W), 10 * math.log10(W)))
                k = max(k, 1)
            width = (xmax - start) / k if xmax > start else 1.0
        # VERIFY: intervals [a, b), the last one closed at xmax
        idx = np.floor((x - start) / width + 1e-12 * max(1.0, abs(xmax))).astype(int)
        idx = np.clip(idx, 0, k - 1)
        centers = start + width * (np.arange(k) + 0.5)
    counts = np.bincount(idx, weights=ww, minlength=k)[:k]
    scale = opts.get("scale", "density")
    if scale == "frequency":
        h = counts
    elif scale == "fraction":
        h = counts / W
    elif scale == "percent":
        h = 100 * counts / W
    else:
        h = counts / (W * width)
    return {"centers": centers.tolist(), "heights": h.tolist(), "width": width, "start": start,
            "bins": k, "N": W, "min": xmin, "max": xmax}


# ---------------------------------------------------------------------------
# kdensity
# ---------------------------------------------------------------------------

_SQ5 = math.sqrt(5.0)


def _kernel(name: str):
    if name == "epanechnikov":
        return lambda z: np.where(np.abs(z) < _SQ5, 3 / (4 * _SQ5) * (1 - z * z / 5), 0.0)
    if name == "epan2":
        return lambda z: np.where(np.abs(z) < 1, 0.75 * (1 - z * z), 0.0)
    if name == "biweight":
        return lambda z: np.where(np.abs(z) < 1, 15 / 16 * (1 - z * z) ** 2, 0.0)
    if name == "cosine":
        return lambda z: np.where(np.abs(z) < 0.5, 1 + np.cos(2 * np.pi * z), 0.0)
    if name == "gaussian":
        return lambda z: np.exp(-0.5 * z * z) / math.sqrt(2 * math.pi)
    if name == "parzen":
        def k(z):
            a = np.abs(z)
            return np.where(a <= 0.5, 4 / 3 - 8 * z * z + 8 * a ** 3,
                            np.where(a <= 1, 8 * (1 - a) ** 3 / 3, 0.0))
        return k
    if name == "rectangle":
        return lambda z: np.where(np.abs(z) < 1, 0.5, 0.0)
    if name == "triangle":
        return lambda z: np.where(np.abs(z) < 1, 1 - np.abs(z), 0.0)
    raise StataError(198, f"kernel {name} not allowed")   # VERIFY mensagem


KERNELS = ("epanechnikov", "epan2", "biweight", "cosine", "gaussian", "parzen", "rectangle", "triangle")


def kernel_name(text: str | None) -> str:
    if not text:
        return "epanechnikov"
    t = text.strip().lower()
    if t == "epan2":
        return "epan2"
    for k in KERNELS:
        if k != "epan2" and len(t) >= 2 and k.startswith(t):
            return k
    raise StataError(198, f"kernel({text}) invalid")   # VERIFY


def is_fweight(p) -> bool:
    """True when the command's weight is a frequency weight (a bare [weight=] is one too)."""
    return p.weight is not None and p.weight[0] in ("fweight", "weight")


def default_bandwidth(x: np.ndarray, w: np.ndarray | None, fw: bool = True) -> float:
    """[R] kdensity: h = 0.9 m / n^(1/5), m = min(sd, IQR/1.349). n is the sum of the
    weights with fweights and the number of observations with aweights (r(N) of summarize)."""
    order = np.argsort(x, kind="stable")
    xs = x[order]
    ws = None if w is None else w[order]
    mom = S.moments(xs, ws, ("fweight" if fw else "aweight") if w is not None else "")
    n = float(mom.N)   # VERIFY: aweight n (compat 1921)
    q1 = S.percentile(xs, 25, ws)
    q3 = S.percentile(xs, 75, ws)
    m = min(mom.sd, (q3 - q1) / 1.349)
    if m <= 0:
        m = mom.sd
    return 0.9 * m / n ** 0.2


def kdensity(x: np.ndarray, w: np.ndarray | None, *, kernel: str = "epanechnikov",
             bw: float | None = None, n: int | None = None, at: np.ndarray | None = None,
             fw: bool = True) -> dict:
    N = len(x)
    if N == 0:
        raise StataError(2000, "no observations")
    h = bw if bw is not None else default_bandwidth(x, w, fw)
    if at is None:
        npts = n if n is not None else min(N, 50)
        # grid from minimum - h to maximum + h (compat 0701)
        lo, hi = float(x.min()) - h, float(x.max()) + h
        grid = np.linspace(lo, hi, npts) if npts > 1 else np.array([lo])
    else:
        grid = at
    K = _kernel(kernel)
    ww = np.ones(N) if w is None else w / w.sum() * N
    z = (grid[:, None] - x[None, :]) / h
    dens = (K(z) * ww[None, :]).sum(axis=1) / (N * h)
    return {"x": grid, "d": dens, "bwidth": h, "n": len(grid), "kernel": kernel}


# ---------------------------------------------------------------------------
# ajustes
# ---------------------------------------------------------------------------

def poly_fit(x: np.ndarray, y: np.ndarray, degree: int, grid: np.ndarray, ci: bool = False,
             level: float = 95.0, w: np.ndarray | None = None):
    X = np.vander(x - x.mean(), degree + 1, increasing=True)
    Xg = np.vander(grid - x.mean(), degree + 1, increasing=True)
    ww = np.ones(len(x)) if w is None else w
    XtX = X.T @ (X * ww[:, None])
    beta = np.linalg.solve(XtX, X.T @ (ww * y))
    fit = Xg @ beta
    if not ci:
        return fit, None, None
    resid = y - X @ beta
    df = len(x) - (degree + 1)
    s2 = float((ww * resid * resid).sum() / df)
    V = s2 * np.linalg.inv(XtX)
    se = np.sqrt(np.einsum("ij,jk,ik->i", Xg, V, Xg))
    from scipy import stats as _st
    t = float(_st.t.ppf(0.5 + level / 200, df))
    return fit, fit - t * se, fit + t * se


# ---------------------------------------------------------------------------
# graph box
# ---------------------------------------------------------------------------

def box_stats(x: np.ndarray, w: np.ndarray | None = None) -> dict:
    """[G-2] graph box: quartiles as defined by summarize; whiskers up to the
    adjacent values (within 1.5 IQR); the rest are outside points."""
    order = np.argsort(x, kind="stable")
    xs = x[order]
    ws = None if w is None else w[order]
    q1 = S.percentile(xs, 25, ws)
    med = S.percentile(xs, 50, ws)
    q3 = S.percentile(xs, 75, ws)
    iqr = q3 - q1
    lo_lim, hi_lim = q1 - 1.5 * iqr, q3 + 1.5 * iqr
    inside = xs[(xs >= lo_lim) & (xs <= hi_lim)]
    lo = float(inside.min()) if len(inside) else q1
    hi = float(inside.max()) if len(inside) else q3
    out = xs[(xs < lo_lim) | (xs > hi_lim)]
    return {"q1": q1, "med": med, "q3": q3, "lo": lo, "hi": hi, "out": out.tolist()}


# ---------------------------------------------------------------------------
# graph bar: statistics
# ---------------------------------------------------------------------------

STATS = ("mean", "median", "p", "sum", "rawsum", "count", "percent", "max", "min", "sd",
         "first", "last", "firstnm", "lastnm", "iqr", "semean")


def stat_value(stat: str, x: np.ndarray, w: np.ndarray | None) -> float:
    ok = x < SYS
    x = x[ok]
    if w is not None:
        w = w[ok]
    if stat == "count":
        return float(len(x) if w is None else w.sum())
    if len(x) == 0:
        return SYS
    ww = np.ones(len(x)) if w is None else w
    if stat == "mean":
        return float((ww * x).sum() / ww.sum())
    if stat in ("sum", "rawsum"):
        return float((ww * x).sum()) if stat == "sum" else float(x.sum())
    if stat == "max":
        return float(x.max())
    if stat == "min":
        return float(x.min())
    if stat == "sd":
        if len(x) < 2:
            return SYS
        m = (ww * x).sum() / ww.sum()
        return float(math.sqrt((ww * (x - m) ** 2).sum() / (ww.sum() - 1)))
    if stat == "semean":
        sd = stat_value("sd", x, w)
        return sd / math.sqrt(ww.sum()) if sd < SYS else SYS
    if stat in ("first", "firstnm"):
        return float(x[0])
    if stat in ("last", "lastnm"):
        return float(x[-1])
    order = np.argsort(x, kind="stable")
    xs, ws = x[order], (None if w is None else w[order])
    if stat == "median":
        return S.percentile(xs, 50, ws)
    if stat == "iqr":
        return S.percentile(xs, 75, ws) - S.percentile(xs, 25, ws)
    if stat.startswith("p") and stat[1:].isdigit():
        return S.percentile(xs, float(stat[1:]), ws)
    raise StataError(198, f"({stat}) invalid statistic")   # VERIFY

files.opendta/graphics/opts.py:
"""Reading graph options ([G-3] options).

The options are split into two groups:
  - layer options (colors, symbols, line patterns...), which apply only
    to the plot where they appear;
  - graph options (titles, axes, legend, by(), name()...), which apply
    to the whole graph, in whichever plot they are written (as in
    Stata, where `twoway (scatter y x, title("a"))` gives the graph a title).

The result is always a plain dictionary (JSON), so that it fits in the .gph.
"""

from __future__ import annotations

import re

from ..core.errors import StataError
from ..lang.syntax import find_top, parse_options
from ..lang.words import parse_numlist, split_words, strip_outer_quotes

# full name -> minimal abbreviation
LAYER_OPTS = {
    "mcolor": 3, "msymbol": 2, "msize": 3, "mfcolor": 3, "mlcolor": 3, "mlabel": 4, "mlabposition": 6,
    "mlabcolor": 6, "mlabsize": 6, "lcolor": 3, "lpattern": 3, "lwidth": 3, "lstyle": 3,
    "color": 5, "fcolor": 3, "fintensity": 5, "bcolor": 3, "barwidth": 4, "base": 4,
    "sort": 4, "connect": 1, "cmissing": 5, "jitter": 6, "horizontal": 5, "vertical": 4,
    "range": 1, "n": 1, "droplines": 5, "recast": 6, "yaxis": 5, "xaxis": 5,
    "estopts": 7, "predopts": 8, "level": 3, "noweights": 8,
}

GRAPH_OPTS = {
    "title": 2, "subtitle": 3, "note": 4, "caption": 3,
    "xtitle": 6, "ytitle": 6, "xlabel": 4, "ylabel": 4, "xtick": 5, "ytick": 5,
    "xmlabel": 5, "ymlabel": 5, "xmtick": 5, "ymtick": 5,
    "xscale": 3, "yscale": 3, "legend": 3, "name": 4, "saving": 3, "scheme": 3,
    "by": 2, "yline": 5, "xline": 5, "aspectratio": 6, "xsize": 5, "ysize": 5,
    "nodraw": 6, "graphregion": 6, "plotregion": 5, "text": 4, "xcommon": 7, "ycommon": 7,
}

_PLAIN = re.compile(r"^[-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?$")


def _match(name: str, spec: dict[str, int]) -> str | None:
    if name in spec:
        return name
    for full, minimum in spec.items():
        if len(name) >= minimum and full.startswith(name):
            return full
    return None


def split_layer_graph(text: str, layer_spec: dict[str, int] | None = None,
                      extra_graph: dict[str, int] | None = None) -> tuple[dict, dict]:
    """Splits the options into (layer, graph). Returns dictionaries
    {full name: argument (str) or True}. `no...` is accepted in the graph
    options as the value False (for example nodraw → nodraw=True)."""
    layer_spec = layer_spec if layer_spec is not None else LAYER_OPTS
    gspec = dict(GRAPH_OPTS)
    if extra_graph:
        gspec.update(extra_graph)
    layer: dict = {}
    graph: dict = {}
    for name, arg in parse_options(text):
        full = _match(name, layer_spec)
        if full is not None:
            layer[full] = arg if arg is not None else True
            continue
        full = _match(name, gspec)
        if full is not None:
            graph[full] = arg if arg is not None else True
            continue
        raise StataError(198, f"option {name} not allowed")
    return layer, graph


# ---------------------------------------------------------------------------
# argumentos
# ---------------------------------------------------------------------------

def split_sub(arg: str) -> tuple[str, dict]:
    """'texto, sub(1) outra' -> ('texto', {'sub': '1', 'outra': True})."""
    if arg is None or arg is True:
        return "", {}
    c = find_top(arg, ",")
    if c == -1:
        return arg.strip(), {}
    subs: dict = {}
    for n, a in parse_options(arg[c + 1:]):
        subs[n] = a if a is not None else True
    return arg[:c].strip(), subs


def text_lines(arg) -> list[str]:
    """Argument of title(), note()...: several quoted strings are
    lines; unquoted text is a single line."""
    if arg is None or arg is True:
        return []
    main, _ = split_sub(arg)
    if not main:
        return []
    if main.startswith('"') or main.startswith('`"'):
        return [w for w in split_words(main)]
    return [main]


def text_opt(arg) -> dict:
    main, subs = split_sub(arg if isinstance(arg, str) else "")
    lines = text_lines(main) if main else []
    out: dict = {"lines": lines}
    for k in ("size", "color", "position", "ring", "angle"):
        for n, v in subs.items():
            if k.startswith(n) and len(n) >= 3:
                out[k] = strip_outer_quotes(v) if isinstance(v, str) else v
    return out


def axis_label(arg) -> dict:
    """xlabel()/ylabel(): values (numlist), value "label" pairs, #k,
    none, minmax and the suboptions angle(), grid/nogrid, valuelabel, format()."""
    out: dict = {}
    if arg is None or arg is True:
        return out
    main, subs = split_sub(arg)
    for n, v in subs.items():
        nl = n.lower()
        if nl.startswith("ang") or nl == "a":
            try:
                out["angle"] = float(strip_outer_quotes(v)) if v not in ("vertical", "v") else 90.0
            except (TypeError, ValueError):
                out["angle"] = 90.0 if str(v).startswith("v") else 0.0
        elif nl == "grid":
            out["grid"] = True
        elif nl == "nogrid":
            out["grid"] = False
        elif nl.startswith("val"):
            out["valuelabel"] = True
        elif nl.startswith("form"):
            out["format"] = strip_outer_quotes(v or "")
        elif nl.startswith("labs"):
            out["size"] = v
        elif nl == "nolabels":
            out["none"] = True
    words = split_words(main, keep_quotes=True)
    ticks: list = []
    nums: list[str] = []

    def flush() -> None:
        if nums:
            for x in parse_numlist(" ".join(nums)):
                ticks.append([x, None])
            nums.clear()

    for w in words:
        if w.startswith('"') or w.startswith('`"'):
            flush()
            if not ticks:
                raise StataError(198, "invalid label specifier")
            ticks[-1][1] = strip_outer_quotes(w)
        elif w.startswith("##"):
            flush()
            out["minor"] = int(w[2:])
        elif w.startswith("#"):
            flush()
            try:
                out["auto"] = int(w[1:])
            except ValueError:
                raise StataError(198, "invalid label specifier")
        elif w in ("none", "minmax"):
            flush()
            out[w] = True
        else:
            nums.append(w)
    flush()
    if ticks:
        out["ticks"] = ticks
    return out


def axis_scale(arg) -> dict:
    out: dict = {}
    if arg is None or arg is True:
        return out
    for n, a in parse_options(arg):
        if n == "log":
            out["log"] = True
        elif n.startswith("rev"):
            out["reverse"] = True
        elif n.startswith("r") and "range".startswith(n):
            vals = parse_numlist(a or "")
            out["range"] = [min(vals), max(vals)] if vals else None
        elif n in ("off", "noline"):
            out[n] = True
        elif n.startswith("alt"):
            out["alt"] = True
        else:
            raise StataError(198, f"option {n} not allowed")
    return out


def legend_opt(arg) -> dict:
    out: dict = {}
    if arg is None or arg is True:
        return out
    for n, a in parse_options(arg):
        if n == "off":
            out["off"] = True
        elif n == "on":
            out["on"] = True
        elif n.startswith("ord"):
            order: list = []
            for w in split_words(a or "", keep_quotes=True):
                if w.startswith('"') or w.startswith('`"'):
                    if order:
                        order[-1][1] = strip_outer_quotes(w)
                elif w == "-":
                    continue
                else:
                    order.append([int(w), None])
            out["order"] = order
        elif n.startswith("lab"):
            ws = split_words(a or "")
            if ws:
                out.setdefault("labels", {})[str(int(ws[0]))] = " ".join(ws[1:])
        elif n in ("rows", "row", "r"):
            out["rows"] = int(a)
        elif n in ("cols", "col", "c"):
            out["cols"] = int(a)
        elif n.startswith("pos") or n == "position":
            out["position"] = int(a)
        elif n == "ring":
            out["ring"] = int(a)
        elif n.startswith("ti"):
            out["title"] = " ".join(text_lines(a))
        else:
            pass     # VERIFY: appearance suboptions ignored (size, region...)
    return out


def name_opt(arg) -> tuple[str, bool]:
    main, subs = split_sub(arg or "")
    name = main.strip()
    if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]{0,31}", name):
        raise StataError(198, f"{name} invalid name")
    return name, any("replace".startswith(k) and len(k) >= 3 for k in subs)


def saving_opt(arg) -> tuple[str, bool]:
    main, subs = split_sub(arg or "")
    return strip_outer_quotes(main), any("replace".startswith(k) and len(k) >= 3 for k in subs)


def lines_opt(arg) -> dict:
    main, subs = split_sub(arg or "")
    out: dict = {"values": parse_numlist(main) if main else []}
    for n, v in subs.items():
        if n.startswith("lc"):
            out["lcolor"] = strip_outer_quotes(v)
        elif n.startswith("lp"):
            out["lpattern"] = strip_outer_quotes(v)
        elif n.startswith("lw"):
            out["lwidth"] = strip_outer_quotes(v)
    return out


def by_opt(arg) -> dict:
    main, subs = split_sub(arg or "")
    out: dict = {"vars": main.split()}
    for n, v in subs.items():
        if n.startswith("tot"):
            out["total"] = True
        elif n in ("cols", "col", "c"):
            out["cols"] = int(v)
        elif n in ("rows", "row", "r"):
            out["rows"] = int(v)
        elif n.startswith("ti"):
            out["title"] = text_lines(v)
        elif n.startswith("note"):
            out["note"] = text_lines(v)
        elif n.startswith("leg"):
            out["legend"] = legend_opt(v)
        elif n in ("compact", "missing", "ixaxes", "iyaxes", "iscale", "noiyaxes", "noixaxes"):
            out[n] = True
    return out


def graph_options(graph: dict) -> dict:
    """Converts the graph options (text) to the form stored in the Graph."""
    o: dict = {}
    for key in ("title", "subtitle", "note", "caption", "xtitle", "ytitle"):
        if key in graph:
            o[key] = text_opt(graph[key])
    for key in ("xlabel", "ylabel"):
        if key in graph:
            o[key] = axis_label(graph[key])
    for key in ("xscale", "yscale"):
        if key in graph:
            o[key] = axis_scale(graph[key])
    if "legend" in graph:
        o["legend"] = legend_opt(graph["legend"])
    for key in ("yline", "xline"):
        if key in graph:
            o[key] = lines_opt(graph[key])
    if "by" in graph:
        o["by"] = by_opt(graph["by"])
    if "scheme" in graph:
        o["scheme"] = strip_outer_quotes(str(graph["scheme"]))
    if "aspectratio" in graph:
        o["aspectratio"] = float(split_sub(graph["aspectratio"])[0])
    for key in ("xsize", "ysize"):
        if key in graph:
            o[key] = float(graph[key])
    if "text" in graph:
        ws = split_words(graph["text"])
        o["text"] = [[float(ws[i]), float(ws[i + 1]), ws[i + 2]] for i in range(0, len(ws) - 2, 3)]
    return o


def is_number(text: str) -> bool:
    return bool(_PLAIN.match(text.strip()))

files.opendta/graphics/render.py:
"""Drawing graphs with matplotlib.

Takes a Graph (model.py) and returns a matplotlib Figure, used both
in the Graph window of the interface and in `graph export`. The look follows
OpenDTA's own schemes (scheme.py); the general layout (titles at the
top, legend and notes at the bottom, by() panels in a grid) follows
Stata's as described in [G-3], without copying StataCorp graphical elements."""

from __future__ import annotations

import math
from typing import TYPE_CHECKING

import numpy as np

from ..lazy import lazy
from . import scheme as SC
from .model import Graph, Layer, Panel

if TYPE_CHECKING:
    from matplotlib.figure import Figure

# matplotlib is imported when the first graph is drawn (start-up time; see opendta/lazy.py)
_mfigure = lazy("matplotlib.figure")
_mticker = lazy("matplotlib.ticker")

# Stata's default size: 5.5 × 4 inches ([G-3] region_options)
DEFAULT_SIZE = (5.5, 4.0)

_HOLLOW = {"oh", "dh", "sh", "th", "circle_hollow", "diamond_hollow", "square_hollow", "triangle_hollow", "smcircle_hollow"}
_MSIZE = {"vtiny": 4, "tiny": 6, "vsmall": 9, "small": 14, "medsmall": 20, "medium": 26, "medlarge": 34,
          "large": 44, "vlarge": 60, "huge": 80, "vhuge": 110, "ehuge": 150}
_LWIDTH = {"none": 0, "vvthin": 0.3, "vthin": 0.5, "thin": 0.8, "medthin": 1.1, "medium": 1.4,
           "medthick": 1.8, "thick": 2.3, "vthick": 3.0, "vvthick": 4.0, "vvvthick": 5.0}
_TSIZE = {"vtiny": 5, "tiny": 6, "vsmall": 7, "small": 8, "medsmall": 9, "medium": 10, "medlarge": 11,
          "large": 13, "vlarge": 15, "huge": 18, "vhuge": 22}

FORMATS = {".png": ("png", "PNG"), ".pdf": ("pdf", "PDF"), ".svg": ("svg", "SVG"),
           ".eps": ("eps", "EPS"), ".ps": ("ps", "PS"), ".tif": ("tiff", "TIFF"),
           ".tiff": ("tiff", "TIFF"), ".jpg": ("jpg", "JPEG"), ".jpeg": ("jpg", "JPEG")}


# ---------------------------------------------------------------------------
# estilos
# ---------------------------------------------------------------------------

def _msymbol(style: dict, i: int, sch: dict) -> tuple[str, bool]:
    sym = str(style.get("msymbol", "")).strip().lower()
    if not sym:
        return sch["markers"][i % len(sch["markers"])], False
    return SC.SYMBOLS.get(sym, "o"), sym in _HOLLOW


def _color(style: dict, keys: tuple[str, ...], default: str) -> str:
    for k in keys:
        if style.get(k):
            return SC.color(str(style[k]), default)
    return default


def _lw(style: dict, default: float = 1.4) -> float:
    v = str(style.get("lwidth", "")).strip().lower()
    if not v:
        return default
    if v in _LWIDTH:
        return _LWIDTH[v]
    try:
        return float(v) * 1.4
    except ValueError:
        return default


def _ls(style: dict):
    v = str(style.get("lpattern", "")).strip().lower()
    return SC.PATTERNS.get(v, "-") if v else "-"


def _ms(style: dict, default: float = 22.0) -> float:
    v = str(style.get("msize", "")).strip().lower()
    if not v:
        return default
    if v in _MSIZE:
        return _MSIZE[v]
    try:
        return float(v) * 8
    except ValueError:
        return default


def _tsize(spec: dict, default: float) -> float:
    v = str(spec.get("size", "")).strip().lower() if isinstance(spec, dict) else ""
    return _TSIZE.get(v, default)


def _arr(v) -> np.ndarray:
    return np.asarray([np.nan if x is None else x for x in v], dtype=float)


# ---------------------------------------------------------------------------
# twoway layers
# ---------------------------------------------------------------------------

def draw_layer(ax, ly: Layer, i: int, sch: dict) -> list:
    """Draws a layer; returns the artists that go into the legend."""
    st = ly.style
    pal = sch["colors"]
    base_color = pal[int(st.get("_pal", i)) % len(pal)]
    col = _color(st, ("color", "mcolor", "lcolor"), base_color)
    lcol = _color(st, ("lcolor", "color"), base_color)
    fcol = _color(st, ("fcolor", "bcolor", "color"), base_color)
    x, y = _arr(ly.x), _arr(ly.y)
    horiz = bool(st.get("horizontal"))
    kind = ly.kind
    label = ly.label or None
    if kind in ("scatter", "scatteri"):
        mk, hollow = _msymbol(st, i, sch)
        if mk == "":
            return []
        sizes = ly.extra.get("sizes")
        s = _ms(st) if sizes is None else _arr(sizes)
        h = ax.scatter(x, y, s=s, marker=mk, label=label, linewidths=0.8,
                       facecolors="none" if hollow else col, edgecolors=col, zorder=2 + i * 0.01)
        labs = ly.extra.get("mlabel")
        if labs:
            for xi, yi, t in zip(x, y, labs):
                if np.isfinite(xi) and np.isfinite(yi):
                    ax.annotate(str(t), (xi, yi), xytext=(3, 3), textcoords="offset points",
                                fontsize=7, color=sch["text"])
        return [h]
    if kind in ("line", "connected", "lfit", "qfit", "function", "kdensity", "tsline", "mspline"):
        mk = ""
        if kind == "connected":
            mk, _ = _msymbol(st, i, sch)
        (h,) = ax.plot(y if horiz else x, x if horiz else y, color=lcol, linestyle=_ls(st), linewidth=_lw(st),
                       marker=mk or None, markersize=math.sqrt(_ms(st)), label=label, zorder=2 + i * 0.01)
        return [h]
    if kind == "area":
        base = float(st.get("base", 0) or 0)
        h = ax.fill_between(x, base, y, color=fcol, alpha=0.85, linewidth=0, label=label, zorder=1)
        return [h]
    if kind in ("bar", "histogram"):
        w = float(ly.extra.get("width", st.get("barwidth", 1) or 1))
        base = float(st.get("base", 0) or 0)
        edge = sch["background"] if kind == "histogram" else fcol
        # many narrow bins: an edge in the background color would eat the fill
        lw = 0.0 if kind == "histogram" and len(x) > 40 else 0.6
        if horiz:
            h = ax.barh(x, y - base, height=w, left=base, color=fcol, edgecolor=edge, linewidth=lw,
                        label=label, zorder=1)
        else:
            h = ax.bar(x, y - base, width=w, bottom=base, color=fcol, edgecolor=edge, linewidth=lw,
                       label=label, zorder=1)
        return [h]
    if kind in ("spike", "dropline"):
        base = float(st.get("base", 0) or 0)
        h = ax.vlines(x, base, y, colors=lcol, linewidth=_lw(st, 1.0), label=label)
        if kind == "dropline":
            mk, hollow = _msymbol(st, i, sch)
            ax.scatter(x, y, s=_ms(st), marker=mk, facecolors="none" if hollow else col, edgecolors=col)
        return [h]
    y2 = _arr(ly.extra.get("y2", []))
    if kind == "rarea":
        h = ax.fill_between(x, y, y2, color=fcol, alpha=0.35, linewidth=0, label=label, zorder=1)
        return [h]
    if kind == "rbar":
        w = float(st.get("barwidth", 0.6) or 0.6)
        h = ax.bar(x, y2 - y, bottom=y, width=w, color=fcol, label=label, zorder=1)
        return [h]
    if kind in ("rcap", "rspike", "rcapsym"):
        if horiz:
            h = ax.hlines(x, y, y2, colors=lcol, linewidth=_lw(st, 1.0), label=label)
        else:
            h = ax.vlines(x, y, y2, colors=lcol, linewidth=_lw(st, 1.0), label=label)
        if kind == "rcap":
            span = np.nanmax(x) - np.nanmin(x) if len(x) > 1 else 1.0
            cap = 0.012 * (span if span > 0 else 1.0)
            fn = ax.vlines if horiz else ax.hlines
            for yy in (y, y2):
                fn(yy, x - cap, x + cap, colors=lcol, linewidth=_lw(st, 1.0))
        if kind == "rcapsym":
            mk, _ = _msymbol(st, i, sch)
            ax.scatter(np.r_[x, x], np.r_[y, y2], s=_ms(st), marker=mk, color=lcol)
        return [h]
    if kind in ("rline", "rconnected"):
        mk = _msymbol(st, i, sch)[0] if kind == "rconnected" else None
        (h,) = ax.plot(x, y, color=lcol, linestyle=_ls(st), linewidth=_lw(st), marker=mk, label=label)
        ax.plot(x, y2, color=lcol, linestyle=_ls(st), linewidth=_lw(st), marker=mk)
        return [h]
    if kind == "rscatter":
        mk, hollow = _msymbol(st, i, sch)
        h = ax.scatter(np.r_[x, x], np.r_[y, y2], s=_ms(st), marker=mk, label=label,
                       facecolors="none" if hollow else col, edgecolors=col)
        return [h]
    return []


# ---------------------------------------------------------------------------
# eixos
# ---------------------------------------------------------------------------

def _apply_axis(ax, which: str, o: dict, sch: dict, value_labels: dict | None) -> None:
    lab = o.get(which + "label", {})
    sc = o.get(which + "scale", {})
    axis = ax.xaxis if which == "x" else ax.yaxis
    if sc.get("log"):
        (ax.set_xscale if which == "x" else ax.set_yscale)("log")
    if sc.get("range"):
        lo, hi = sc["range"]
        cur = ax.get_xlim() if which == "x" else ax.get_ylim()
        lo, hi = min(lo, cur[0]), max(hi, cur[1])
        (ax.set_xlim if which == "x" else ax.set_ylim)(lo, hi)
    if sc.get("reverse"):
        (ax.invert_xaxis if which == "x" else ax.invert_yaxis)()
    if sc.get("off"):
        axis.set_visible(False)
    if lab.get("none"):
        axis.set_ticks([])
    elif lab.get("ticks"):
        vals = [t[0] for t in lab["ticks"]]
        texts = []
        for v, t in lab["ticks"]:
            if t is not None:
                texts.append(t)
            elif lab.get("valuelabel") and value_labels and float(v).is_integer() and int(v) in value_labels:
                texts.append(value_labels[int(v)])
            else:
                texts.append(_num(v))
        axis.set_ticks(vals)
        axis.set_ticklabels(texts)
    elif lab.get("auto"):
        axis.set_major_locator(_mticker.MaxNLocator(nbins=max(1, lab["auto"] - 1)))
    elif lab.get("valuelabel") and value_labels:
        keys = sorted(value_labels)
        axis.set_ticks(keys)
        axis.set_ticklabels([value_labels[k] for k in keys])
    if "angle" in lab:
        for t in axis.get_ticklabels():
            t.set_rotation(lab["angle"])
    grid = lab.get("grid", which == "y")
    if grid:
        ax.grid(True, axis=which, color=sch["grid"], linewidth=0.7, zorder=0)
    else:
        ax.grid(False, axis=which)
    for v in o.get(which + "line", {}).get("values", []) if which in ("x", "y") else []:
        spec = o.get(which + "line", {})
        c = SC.color(spec.get("lcolor"), sch["axis"])
        (ax.axvline if which == "x" else ax.axhline)(v, color=c, linestyle=SC.PATTERNS.get(spec.get("lpattern", ""), "-"),
                                                     linewidth=0.9, zorder=1)


def _num(v: float) -> str:
    if float(v).is_integer():
        return str(int(v))
    t = f"{v:.6g}"
    return t[1:] if t.startswith("0.") else ("-" + t[2:] if t.startswith("-0.") else t)


def _style_axes(ax, sch: dict) -> None:
    ax.set_facecolor(sch["plotregion"])
    for side in ("top", "right"):
        ax.spines[side].set_visible(False)
    for side in ("left", "bottom"):
        ax.spines[side].set_color(sch["axis"])
    ax.tick_params(colors=sch["axis"], labelcolor=sch["text"], labelsize=8)
    ax.set_axisbelow(True)


def _join(spec) -> str:
    if not spec:
        return ""
    return "\n".join(spec.get("lines", [])) if isinstance(spec, dict) else str(spec)


# ---------------------------------------------------------------------------
# families
# ---------------------------------------------------------------------------

def _draw_twoway_panel(ax, panel: Panel, g: Graph, sch: dict) -> list:
    handles = []
    for i, ly in enumerate(panel.layers):
        hs = draw_layer(ax, ly, i, sch)
        if hs and ly.label:
            handles.append((hs[0], ly.label))
    # histogram: the value axis starts at zero, as in Stata
    for ly in panel.layers:
        if ly.kind == "histogram":
            horiz = bool(ly.style.get("horizontal"))
            lo, hi = ax.get_ylim() if horiz else ax.get_xlim()
            if lo > 0:
                (ax.set_ylim if horiz else ax.set_xlim)(0, hi)
            break
    if g.opts.get("text"):
        for yv, xv, t in g.opts["text"]:
            ax.text(xv, yv, t, fontsize=8, color=sch["text"], ha="center", va="center")
    return handles


# graph bar/box/dot: positions, value axis and nested over() labels

_GAP = 0.5          # extra space between groups of an outer over(), in category widths


def _positions(ly: Layer) -> np.ndarray:
    """Category positions: consecutive, with a gap where an outer over() changes."""
    n = len(ly.extra.get("cats", []))
    levels = ly.extra.get("levels", [])
    pos = np.arange(n, dtype=float)
    for i in range(1, n):
        for L in range(len(levels), 0, -1):
            if any(levels[j][i] != levels[j][i - 1] for j in range(L - 1, len(levels))):
                pos[i:] += _GAP * L
                break
    return pos


def _outer_labels(ax, ly: Layer, pos: np.ndarray, horizontal: bool) -> None:
    """Labels of the outer over() groups, below (or left of) the category labels."""
    levels = ly.extra.get("levels", [])
    if not levels:
        return
    cats = ly.extra.get("cats", [])
    inner = max((len(str(c)) for c in cats), default=0)
    for L, labs in enumerate(levels, start=1):
        keys = [tuple(levels[j][i] for j in range(L - 1, len(levels))) for i in range(len(cats))]
        i = 0
        while i < len(keys):
            j = i
            while j + 1 < len(keys) and keys[j + 1] == keys[i]:
                j += 1
            mid = float(pos[i:j + 1].mean())
            if horizontal:
                ax.text(-(0.04 + 0.012 * inner + 0.05 * L) , mid, labs[i], transform=ax.get_yaxis_transform(),
                        rotation=90, ha="center", va="center", fontsize=8, color=ax.yaxis.label.get_color())
            else:
                ax.text(mid, -(0.05 + 0.07 * L), labs[i], transform=ax.get_xaxis_transform(),
                        ha="center", va="top", fontsize=8, color=ax.xaxis.label.get_color())
            i = j + 1
    if not horizontal:
        ax.xaxis.labelpad = 6 + 18 * len(levels)


def _set_cats(ax, ly: Layer, pos: np.ndarray, horizontal: bool, invert: bool = True) -> None:
    cats = ly.extra.get("cats", [])
    if horizontal:
        ax.set_yticks(pos)
        ax.set_yticklabels(cats)
        if invert:
            ax.invert_yaxis()
    else:
        ax.set_xticks(pos)
        ax.set_xticklabels(cats)
    _outer_labels(ax, ly, pos, horizontal)


def _value_axis(ax, lo: float, hi: float, horizontal: bool, zero: bool = True) -> None:
    """Value axis of bars and boxes: about four ticks, reaches the next tick when the data end
    close to it, and leaves room for the labels above the last bar. Bars start at zero; boxes
    (zero=False) follow the data, as in Stata."""
    if not (np.isfinite(lo) and np.isfinite(hi)):
        return
    if zero:
        lo, hi = min(lo, 0.0), max(hi, 0.0)
    if hi == lo:
        return
    axis = ax.xaxis if horizontal else ax.yaxis
    loc = _mticker.MaxNLocator(nbins=4 if zero else 5, steps=[1, 2, 5, 10])
    axis.set_major_locator(loc)
    ticks = loc.tick_values(lo, hi)
    step = ticks[1] - ticks[0]

    def reach(v: float, up: bool) -> float:
        cand = [t for t in ticks if (t >= v if up else t <= v)]
        if not cand:
            return v
        t = min(cand) if up else max(cand)
        return t if abs(t - v) <= 0.4 * step else v

    top, bottom = reach(hi, True), reach(lo, False)
    span = top - bottom
    top = top + 0.045 * span if (top > 0 or not zero) else top
    bottom = bottom - 0.045 * span if (bottom < 0 or not zero) else bottom
    (ax.set_xlim if horizontal else ax.set_ylim)(bottom, top)


def _tint(color: str, background: str, amount: float) -> tuple:
    """`color` mixed with the background: a light fill for the boxes."""
    from matplotlib.colors import to_rgb
    c, b = np.array(to_rgb(color)), np.array(to_rgb(background))
    return tuple(c * (1 - amount) + b * amount)


def _draw_bars(ax, ly: Layer, sch: dict, horizontal: bool) -> list:
    series = ly.extra.get("series", [])
    stack = ly.extra.get("stack", False)
    nser = max(1, len(series))
    pos = _positions(ly)
    width = (0.6 if nser == 1 else 0.8) / (1 if stack else nser)
    group = width * (1 if stack else nser)
    bottom = np.zeros(len(pos))
    handles = []
    top = -np.inf
    low = np.inf
    for j, ser in enumerate(series):
        vals = _arr(ser["values"])
        c = sch["colors"][j % len(sch["colors"])]
        offs = pos if stack else pos - group / 2 + width * (j + 0.5)
        if horizontal:
            h = ax.barh(offs, np.nan_to_num(vals), height=width, left=bottom if stack else 0, color=c, zorder=2)
        else:
            h = ax.bar(offs, np.nan_to_num(vals), width=width, bottom=bottom if stack else 0, color=c, zorder=2)
        if ly.extra.get("blabel"):
            fmt = ly.extra.get("blabel_fmt")
            if fmt:
                from ..core.formats import format_value
                texts = [format_value(v, fmt, pad=False) if np.isfinite(v) else "" for v in vals]
            else:
                texts = [_num(round(v, 4)) if np.isfinite(v) else "" for v in vals]
            ax.bar_label(h, labels=texts, fontsize=7, color=sch["text"])
        if stack:
            bottom = bottom + np.nan_to_num(vals)
            top, low = max(top, float(bottom.max())), min(low, float(bottom.min()))
        else:
            fin = vals[np.isfinite(vals)]
            if len(fin):
                top, low = max(top, float(fin.max())), min(low, float(fin.min()))
        handles.append((h, ser.get("label", "")))
    _set_cats(ax, ly, pos, horizontal)
    ax.grid(True, axis="x" if horizontal else "y", color=sch["grid"], linewidth=0.7, zorder=0)
    _value_axis(ax, low, top, horizontal)
    return handles if len(series) > 1 else []


def _orientation_kw(horizontal: bool) -> dict:
    """matplotlib 3.10 replaced vert= with orientation= in bxp."""
    import matplotlib
    major, minor = (int(p) for p in matplotlib.__version__.split(".")[:2])
    if (major, minor) >= (3, 10):
        return {"orientation": "horizontal" if horizontal else "vertical"}
    return {"vert": not horizontal}


def _draw_dots(ax, ly: Layer, sch: dict) -> list:
    """graph dot: one dotted line per category and one marker per series."""
    series = ly.extra.get("series", [])
    pos = _positions(ly)
    for p_ in pos:
        ax.axhline(p_, color=sch["grid"], linestyle=":", linewidth=0.9, zorder=0)
    handles = []
    for j, ser in enumerate(series):
        vals = _arr(ser["values"])
        c = sch["colors"][j % len(sch["colors"])]
        h = ax.scatter(vals, pos, s=30, color=c, marker=sch["markers"][j % len(sch["markers"])], zorder=3)
        handles.append((h, ser.get("label", "")))
    _set_cats(ax, ly, pos, True)
    return handles if len(series) > 1 else []


def _draw_boxes(ax, ly: Layer, sch: dict, horizontal: bool) -> list:
    series = ly.extra.get("series", [])
    nser = max(1, len(series))
    width = 0.7 / nser
    pos_cat = _positions(ly)
    handles = []
    top, low = -np.inf, np.inf
    for j, ser in enumerate(series):
        c = sch["colors"][j % len(sch["colors"])]
        stats = []
        positions = []
        for k, b in enumerate(ser["stats"]):
            if b is None:
                continue
            stats.append({"med": b["med"], "q1": b["q1"], "q3": b["q3"], "whislo": b["lo"], "whishi": b["hi"],
                          "fliers": b["out"]})
            positions.append(pos_cat[k] - 0.35 + width * (j + 0.5))
            top = max(top, b["hi"], *(b["out"] or [b["hi"]]))
            low = min(low, b["lo"], *(b["out"] or [b["lo"]]))
        if not stats:
            continue
        orient = _orientation_kw(horizontal)
        r = ax.bxp(stats, positions=positions, widths=width * 0.85, patch_artist=True, **orient,
                   showfliers=True, manage_ticks=False,
                   boxprops={"facecolor": _tint(c, sch["background"], 0.6), "edgecolor": c},
                   medianprops={"color": c, "linewidth": 1.5},
                   whiskerprops={"color": c}, capprops={"color": c},
                   flierprops={"marker": "o", "markerfacecolor": c, "markeredgecolor": c, "markersize": 3.5})
        handles.append((r["boxes"][0], ser.get("label", "")))
    _set_cats(ax, ly, pos_cat, horizontal, invert=False)
    ax.grid(True, axis="x" if horizontal else "y", color=sch["grid"], linewidth=0.7, zorder=0)
    cats = ly.extra.get("cats", [])
    if len(cats) == 1 and cats[0] == "":
        (ax.set_yticks if horizontal else ax.set_xticks)([])
    _value_axis(ax, low, top, horizontal, zero=False)
    return handles if len(series) > 1 else []


def _draw_pie(ax, ly: Layer, sch: dict) -> list:
    vals = _arr(ly.extra.get("values", []))
    labels = ly.extra.get("labels", [])
    ok = np.isfinite(vals) & (vals > 0)
    vals = vals[ok]
    labels = [lab for lab, k in zip(labels, ok) if k]
    pl = ly.extra.get("plabel")
    auto = None
    if pl == "percent":
        auto = "%1.1f%%"
    elif pl == "sum":
        total = vals.sum()
        auto = lambda p: _num(round(p * total / 100, 4))   # noqa: E731
    wedges, *_ = ax.pie(vals, colors=[sch["colors"][k % len(sch["colors"])] for k in range(len(vals))],
                        autopct=auto, startangle=90, counterclock=False,
                        wedgeprops={"edgecolor": sch["background"], "linewidth": 1},
                        textprops={"fontsize": 8, "color": sch["text"]})
    ax.set_aspect("equal")
    return list(zip(wedges, labels))


def _draw_matrix(fig, ly: Layer, sch: dict) -> None:
    names = ly.extra.get("names", [])
    cols = [_arr(c) for c in ly.extra.get("cols", [])]
    half = ly.extra.get("half", False)
    k = len(names)
    gs = fig.add_gridspec(k, k, hspace=0.08, wspace=0.08)
    for r in range(k):
        for c in range(k):
            if half and c > r:
                continue
            ax = fig.add_subplot(gs[r, c])
            _style_axes(ax, sch)
            ax.tick_params(labelsize=6)
            if r == c:
                ax.text(0.5, 0.5, names[r], ha="center", va="center", fontsize=9, color=sch["text"],
                        transform=ax.transAxes)
                ax.set_xticks([])
                ax.set_yticks([])
                for sp in ax.spines.values():
                    sp.set_visible(True)
                    sp.set_color(sch["grid"])
                continue
            ax.scatter(cols[c], cols[r], s=6, color=sch["colors"][0], linewidths=0)
            if r != k - 1:
                ax.set_xticklabels([])
            if c != 0:
                ax.set_yticklabels([])


# ---------------------------------------------------------------------------
# montagem
# ---------------------------------------------------------------------------

def draw(container, g: Graph, sch: dict) -> None:
    """Draws `g` in a Figure or SubFigure."""
    o = g.opts
    container.set_facecolor(sch["background"])
    tcolor = sch["text"]
    title = _join(o.get("title"))
    subtitle = _join(o.get("subtitle"))
    head = title + (("\n" + subtitle) if subtitle and title else subtitle)
    if head:
        container.suptitle(head, fontsize=_tsize(o.get("title", {}), 12), color=tcolor)
    if g.family == "combine":
        kids = g.children
        n = len(kids)
        cols = int(o.get("cols") or 0) or (math.ceil(math.sqrt(n)) if n else 1)
        rows = int(o.get("rows") or 0) or max(1, math.ceil(n / cols))
        if o.get("rows") and not o.get("cols"):
            cols = max(1, math.ceil(n / rows))
        subs = container.subfigures(rows, cols, squeeze=False)
        for k, child in enumerate(kids):
            sub = subs[k // cols][k % cols]
            draw(sub, child, SC.get(child.opts.get("scheme")) if child.opts.get("scheme") else sch)
        for k in range(n, rows * cols):
            subs[k // cols][k % cols].set_facecolor(sch["background"])
        _notes(container, o, sch)
        return
    panels = g.panels or [Panel()]
    if g.family == "matrix":
        _draw_matrix(container, panels[0].layers[0], sch)
        _notes(container, o, sch)
        return
    byo = o.get("by")
    n = len(panels)
    if byo or n > 1:
        cols = int(byo.get("cols") or 0) if byo else 0
        rows = int(byo.get("rows") or 0) if byo else 0
        if not cols:
            cols = math.ceil(n / rows) if rows else (math.ceil(math.sqrt(n)) if n > 1 else 1)
        rows = max(1, math.ceil(n / cols))
        share = g.family not in ("pie",)
        axes = container.subplots(rows, cols, squeeze=False, sharex=share, sharey=share)
    else:
        rows = cols = 1
        axes = [[container.add_subplot(1, 1, 1)]]
    handles: list = []
    horizontal = g.family in ("hbar", "hbox", "dot")
    for k in range(rows * cols):
        ax = axes[k // cols][k % cols]
        if k >= n:
            ax.set_visible(False)
            continue
        p = panels[k]
        _style_axes(ax, sch)
        if g.family == "pie":
            ax.axis("off")
        if p.title and (byo or n > 1):
            ax.set_title(p.title, fontsize=9, color=tcolor, backgroundcolor=sch["grid"])
        elif subtitle and not title and n == 1:
            pass
        hs: list = []
        for ly in p.layers:
            if ly.kind == "bars" and g.family == "dot":
                hs += _draw_dots(ax, ly, sch)
            elif ly.kind == "bars":
                hs += _draw_bars(ax, ly, sch, horizontal)
            elif ly.kind == "boxes":
                hs += _draw_boxes(ax, ly, sch, horizontal)
            elif ly.kind == "pie":
                hs += _draw_pie(ax, ly, sch)
        if g.family == "twoway":
            hs = _draw_twoway_panel(ax, p, g, sch)
            vl = o.get("_xvaluelabels")
            _apply_axis(ax, "x", o, sch, {int(a): b for a, b in vl.items()} if vl else None)
            vl = o.get("_yvaluelabels")
            _apply_axis(ax, "y", o, sch, {int(a): b for a, b in vl.items()} if vl else None)
        elif g.family in ("bar", "hbar", "box", "hbox", "dot"):
            vax = "x" if horizontal else "y"
            _apply_axis(ax, vax, {**o, vax + "label": {**o.get("ylabel", {}), "grid": True}}, sch, None)
        if not handles:
            handles = hs
        if g.family != "pie":
            last_row = (k // cols == rows - 1) or (k + cols >= n)
            if last_row or n == 1:
                xt = _join(o.get("xtitle")) if "xtitle" in o else o.get("_xtitle", "")
                if horizontal:
                    xt = _join(o.get("ytitle")) if "ytitle" in o else o.get("_ytitle", "")
                ax.set_xlabel(xt, fontsize=9, color=tcolor)
            if k % cols == 0:
                yt = _join(o.get("ytitle")) if "ytitle" in o else o.get("_ytitle", "")
                if horizontal:
                    yt = ""
                ax.set_ylabel(yt, fontsize=9, color=tcolor)
    leg = o.get("legend", {})
    show = (len(handles) > 1 or (g.family == "pie" and handles)) and not leg.get("off")
    if leg.get("on") and handles:
        show = True
    if show:
        order = leg.get("order")
        labels_over = leg.get("labels", {})
        items = []
        if order:
            for idx, txt in order:
                if 1 <= idx <= len(handles):
                    h, lab = handles[idx - 1]
                    items.append((h, txt if txt is not None else labels_over.get(str(idx), lab)))
        else:
            for idx, (h, lab) in enumerate(handles, start=1):
                items.append((h, labels_over.get(str(idx), lab)))
        ncol = leg.get("cols") or (math.ceil(len(items) / leg["rows"]) if leg.get("rows") else min(2, len(items)))
        L = container.legend([h for h, _ in items], [t for _, t in items], loc="outside lower center",
                             ncol=ncol, fontsize=8, frameon=True, title=leg.get("title"))
        L.get_frame().set_edgecolor(sch["grid"])
        L.get_frame().set_facecolor(sch["background"])
        for t in L.get_texts():
            t.set_color(tcolor)
    _notes(container, o, sch)


def _notes(container, o: dict, sch: dict) -> None:
    parts = [_join(o.get("note")), _join(o.get("caption"))]
    text = "\n".join(p for p in parts if p)
    if text:
        container.supxlabel(text, x=0.01, ha="left", fontsize=7, color=sch["text"])


def figure(g: Graph, default_scheme: str = "opendta") -> Figure:
    sch = SC.get(g.opts.get("scheme") or default_scheme)
    w = float(g.opts.get("xsize", DEFAULT_SIZE[0]))
    h = float(g.opts.get("ysize", DEFAULT_SIZE[1]))
    fig = _mfigure.Figure(figsize=(w, h), layout="constrained")
    fig.patch.set_facecolor(sch["background"])
    draw(fig, g, sch)
    return fig


def export(g: Graph, path, fmt: str, *, width: int | None = None, height: int | None = None,
           default_scheme: str = "opendta") -> None:
    fig = figure(g, default_scheme)
    dpi = 150
    w, h = fig.get_size_inches()
    if width:
        dpi = width / w
    elif height:
        dpi = height / h
    fig.savefig(path, format=fmt, dpi=dpi, facecolor=fig.get_facecolor())

files.opendta/graphics/store.py:
"""Graphs in memory (graph dir/drop/rename/display) and .gph files.

OpenDTA's .gph is its own JSON (not StataCorp's format): it keeps the
description of the graph (layers and options), not the image. `graph use` of a
.gph saved by Stata is not supported."""

from __future__ import annotations

import json
from pathlib import Path
from typing import TYPE_CHECKING

from ..core.errors import StataError
from .model import Graph

if TYPE_CHECKING:
    from ..session import Session

MAGIC = "OpenDTA graph"
VERSION = 1


class GraphStore:
    def __init__(self) -> None:
        self.graphs: dict[str, Graph] = {}
        self.current: str = ""

    def put(self, g: Graph, *, replace: bool) -> None:
        if g.name in self.graphs and not replace and g.name != "Graph":
            # VERIFY: message and code when name() already exists without replace
            raise StataError(110, f"graph {g.name} already exists")
        # replacing keeps the position in the list (VERIFY the order of graph dir)
        self.graphs[g.name] = g
        self.current = g.name

    def get(self, name: str | None = None) -> Graph:
        n = name or self.current
        if not n or n not in self.graphs:
            if not self.graphs:
                raise StataError(111, "no graphs in memory")   # VERIFY
            raise StataError(111, f"graph {n} not found")      # VERIFY
        return self.graphs[n]

    def drop(self, name: str) -> None:
        if name not in self.graphs:
            raise StataError(111, f"graph {name} not found")   # VERIFY
        del self.graphs[name]
        if self.current == name:
            self.current = next(reversed(self.graphs), "") if self.graphs else ""

    def clear(self) -> None:
        self.graphs.clear()
        self.current = ""


def store(s: "Session") -> GraphStore:
    st = getattr(s, "_graphs", None)
    if st is None:
        st = GraphStore()
        s._graphs = st
    return st


def gph_path(text: str) -> Path:
    from ..lang.words import strip_outer_quotes
    t = strip_outer_quotes(text.strip())
    if not t:
        raise StataError(198, "invalid file specification")
    p = Path(t).expanduser()
    if p.suffix == "":
        p = p.with_suffix(".gph")
    return p


def save_gph(g: Graph, path: Path, *, replace: bool, out=None) -> None:
    if path.exists() and not replace:
        raise StataError(602, f"file {path} already exists")
    if replace and not path.exists() and out is not None:
        # like save, replace: a note when the file does not exist yet (compat 0701)
        out.write(f"(note: file {path} not found)\n", "text")
    payload = {"format": MAGIC, "version": VERSION, "graph": g.to_json()}
    try:
        path.write_text(json.dumps(payload), encoding="utf-8")
    except OSError:
        raise StataError(603, f"file {path} could not be opened")


def load_gph(path: Path) -> Graph:
    if not path.exists():
        raise StataError(601, f"file {path} not found")
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError, UnicodeDecodeError):
        payload = None
    if not isinstance(payload, dict) or payload.get("format") != MAGIC:
        # Stata .gph (its own binary format) or a corrupt file
        raise StataError(610, f"file {path} not an OpenDTA graph file")
    return Graph.from_json(payload["graph"])

files.opendta/io/delimited.py:
"""Delimited text files (CSV, TSV): reading and writing.

Used by import delimited / export delimited and by the old insheet /
outsheet. The inference rules follow Stata 14's [D] import delimited
manual; undocumented points are marked VERIFY and have
cases in compat/do/0105_delimitado.do.
"""

from __future__ import annotations

import csv
import io
import itertools
import re
from dataclasses import dataclass, field
from pathlib import Path

import numpy as np

from ..core import missing as M
from ..core import storage
from ..core.dataset import (NAME_RE, RESERVED, Dataset, Variable, smallest_type_for,
                            str_len, str_type_for)

_NUM_RE = re.compile(r"^[+-]?(\d+\.?\d*|\.\d+)([eEdD][+-]?\d+)?$")


@dataclass
class ReadOptions:
    delimiter: str | None = None        # None: detects comma or tab
    varnames: int | None = None         # line with the names (1-based); 0 = nonames; None = detect
    case: str = "lower"                 # lower | upper | preserve
    asdouble: bool = False
    stringcols: set[int] = field(default_factory=set)    # 1-based
    numericcols: set[int] = field(default_factory=set)
    rowrange: tuple[int | None, int | None] = (None, None)
    colrange: tuple[int | None, int | None] = (None, None)
    encoding: str | None = None
    bindquote: str = "loose"            # loose | strict | nobind
    stripquotes: str = "default"        # default | yes | no
    # insheet: if the 1st line has fewer fields than the data, it is not a header
    header_must_cover: bool = False
    trim_cells: bool = False            # insheet: strips spaces from the ends of the fields


def _sniff(first_line: str) -> str:
    # VERIFY: Stata detects comma or tab from the first line
    return "\t" if first_line.count("\t") > first_line.count(",") else ","


def split_rows(text: str, delimiter: str, bindquote: str = "loose") -> list[list[str]]:
    """Splits a whole text into lines and cells (used in tests and short snippets)."""
    if bindquote == "nobind":
        return [line.split(delimiter) for line in text.splitlines()]
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=delimiter,
                        quotechar='"', doublequote=True, strict=False)
    return [row for row in reader]


def _is_number(s: str) -> bool:
    return bool(_NUM_RE.match(s))


def _to_number(s: str) -> float:
    s = s.strip()
    if s in ("", "."):
        return M.SYSMISS
    if len(s) == 2 and s[0] == "." and s[1].isalpha() and s[1].islower():
        return M.missing_code(s)
    return float(s.replace("d", "e").replace("D", "e"))


def _numeric_cell(s: str) -> bool:
    s = s.strip()
    return s in ("", ".") or _is_number(s) or (len(s) == 2 and s[0] == "." and "a" <= s[1] <= "z")


def make_name(raw: str, case: str) -> str | None:
    """Variable name from the header; None if it does not give a valid name."""
    t = raw.strip()
    if case == "lower":
        t = t.lower()
    elif case == "upper":
        t = t.upper()
    # VERIFY: replacing invalid characters with _ and cutting at 32
    t = re.sub(r"[^A-Za-z0-9_]", "_", t)[:32]
    if not t or not NAME_RE.match(t) or t in RESERVED:
        return None
    return t


CHUNK_ROWS = 50_000           # linhas convertidas por vez
_STR_CACHE_MAX = 50_000       # distinct values kept per text column


class _Column:
    """Column under construction. Starts numeric; becomes text at the first cell
    that is not a number (unless numericcols)."""

    def __init__(self, index: int, offset: int, force_str: bool, force_num: bool):
        self.index = index
        self.offset = offset             # lines before the column appeared
        self.numeric = not force_str
        self.force_num = force_num
        self.num_chunks: list[np.ndarray] = []
        self.text: list[str] = []
        self.maxlen = 1
        self.cache: dict[str, str] | None = {}
        self.flipped_late = False        # became text after the 1st block: needs rereading

    def add_text(self, cells) -> None:
        cache = self.cache
        if cache is None:
            self.text.extend(cells)
            longest = max((str_len(s) for s in cells), default=0)
        else:
            longest = 0
            for s in cells:
                hit = cache.get(s)
                if hit is None:
                    hit = cache[s] = s
                    n = str_len(s)
                    if n > longest:
                        longest = n
                self.text.append(hit)
            if len(cache) > _STR_CACHE_MAX:
                self.cache = None
        self.maxlen = max(self.maxlen, longest)

    def add(self, cells: list[str]) -> None:
        if not self.numeric:
            self.add_text(cells)
            return
        vals = _parse_numbers(cells, strict=not self.force_num)
        if vals is None:                 # apareceu texto
            self.numeric = False
            if self.num_chunks or self.offset:
                self.flipped_late = True
                self.num_chunks = []
            else:
                self.add_text(cells)
            return
        self.num_chunks.append(vals)


def _parse_numbers(cells: list[str], strict: bool) -> np.ndarray | None:
    """Converts a block of cells to float64. None if there is text (strict)."""
    if not cells:
        return np.empty(0)
    s = np.array(cells, dtype=str)
    s = np.char.strip(s)
    miss = (s == "") | (s == ".")
    # missing estendidos .a–.z
    ext = (np.char.str_len(s) == 2) & np.char.startswith(s, ".") & ~miss
    if ext.any():
        ext &= np.char.isalpha(np.char.lstrip(s, "."))
    try:
        if (np.char.find(s, "_") >= 0).any():
            raise ValueError
        vals = np.where(miss | ext, "0", s).astype(np.float64)
        if not np.isfinite(vals).all():
            raise ValueError
        vals[miss] = M.SYSMISS
        if ext.any():
            vals[ext] = [M.missing_code(x) for x in s[ext].tolist()]
        return vals
    except (ValueError, KeyError):
        pass
    # slow path: extended missing values (.a), exponent with d, text
    out = np.empty(len(cells))
    for i, c in enumerate(cells):
        if _numeric_cell(c):
            out[i] = _to_number(c)
        elif strict:
            return None
        else:
            out[i] = M.SYSMISS
    return out


def _open_rows(path: Path, opts: ReadOptions, encoding: str):
    """Open file and an iterator over lines (lists of cells)."""
    f = open(path, encoding=encoding, newline="")
    first = f.readline()
    f.seek(0)
    delim = opts.delimiter or _sniff(first)
    if opts.bindquote == "nobind":
        rows = (line.rstrip("\r\n").split(delim) for line in f)
    else:
        rows = csv.reader(f, delimiter=delim, quotechar='"', doublequote=True, strict=False)
    if opts.trim_cells:
        # insheet strips the spaces from the ends of each field (observed in Stata 14)
        rows = ([c.strip() for c in r] for r in rows)
    return f, rows


def _data_rows(rows, opts: ReadOptions, header_out: list):
    """Applies header, colrange and rowrange; drops blank lines at the end.
    The header found is put in header_out[0]."""
    c0, c1 = opts.colrange
    c0 = (c0 or 1) - 1
    r0, r1 = opts.rowrange
    it = iter(rows)

    def cut(r: list[str]) -> list[str]:
        return r[c0:c1] if (c0 or c1) else r

    header_out.append(None)
    lead: list[list[str]] = []
    if opts.varnames is None:
        # VERIFY: heuristic to detect names in the 1st line (here: all filled cells of the 1st line
        # are non-numeric text)
        first = next(it, None)
        if first is None:
            return
        first = cut(first)
        filled = [c for c in first if c.strip()]
        if filled and not any(_numeric_cell(c) for c in filled):
            header_out[0] = first
        else:
            lead = [first]
    elif opts.varnames > 0:
        for _ in range(opts.varnames - 1):
            next(it, None)
        h = next(it, None)
        header_out[0] = cut(h) if h is not None else None

    k = 0          # data line (1-based), for rowrange
    pending: list[list[str]] = []
    for r in itertools.chain(lead, (cut(x) for x in it)):
        if not ((r and r[0].strip()) or any(c.strip() for c in r)):
            pending.append(r)
            continue
        for b in pending + [r]:
            k += 1
            # VERIFY: here rowrange counts data lines (after the header)
            if r0 and k < r0:
                continue
            if r1 and k > r1:
                return
            yield b
        pending = []


def read_delimited(path: str | Path, opts: ReadOptions | None = None) -> Dataset:
    opts = opts or ReadOptions()
    encodings = [opts.encoding] if opts.encoding else ["utf-8-sig", "latin-1"]
    last: Exception | None = None
    for enc in encodings:
        try:
            return _read(Path(path), opts, enc)
        except UnicodeDecodeError as e:
            last = e
    raise last  # type: ignore[misc]


def _read(path: Path, opts: ReadOptions, encoding: str) -> Dataset:
    header_box: list = []
    cols: list[_Column] = []
    nrows = 0
    f, rows = _open_rows(path, opts, encoding)
    with f:
        buf: list[list[str]] = []

        def flush() -> None:
            nonlocal nrows
            if not buf:
                return
            width = max(len(r) for r in buf)
            while len(cols) < width:
                j = len(cols)
                cols.append(_Column(j, nrows, (j + 1) in opts.stringcols, (j + 1) in opts.numericcols))
            padded = [r if len(r) == width else r + [""] * (width - len(r)) for r in buf]
            for c, cells in zip(cols, zip(*padded)):
                c.add(list(cells))
            nrows += len(buf)
            buf.clear()

        for r in _data_rows(rows, opts, header_box):
            buf.append(r)
            if len(buf) >= CHUNK_ROWS:
                flush()
        flush()

    header = header_box[0] if header_box else None
    if header is not None and opts.header_must_cover and len(header) < len(cols):
        from dataclasses import replace
        return _read(path, replace(opts, varnames=0, header_must_cover=False), encoding)
    if header is not None:
        while len(cols) < len(header):
            j = len(cols)
            cols.append(_Column(j, nrows, (j + 1) in opts.stringcols, (j + 1) in opts.numericcols))

    # columns that became text after the 1st block: reread only those
    late = [c for c in cols if c.flipped_late]
    if late:
        for c in late:
            c.text, c.cache, c.maxlen, c.offset = [], {}, 1, 0
        f, rows = _open_rows(path, opts, encoding)
        with f:
            chunk: list[list[str]] = []
            for r in _data_rows(rows, opts, []):
                chunk.append(r)
                if len(chunk) >= CHUNK_ROWS:
                    for c in late:
                        c.add_text([x[c.index] if c.index < len(x) else "" for x in chunk])
                    chunk = []
            for c in late:
                c.add_text([x[c.index] if c.index < len(x) else "" for x in chunk])

    ds = Dataset()
    ds.nobs = nrows
    used: set[str] = set()
    for c in cols:
        j = c.index
        raw_name = header[j] if header is not None and j < len(header) else ""
        name = make_name(raw_name, opts.case) if raw_name.strip() else None
        if name is None or name in used:
            name = f"v{j + 1}"
        used.add(name)
        # VERIFY: the original header becomes the label when the name had to change (beyond case)
        label = raw_name.strip() if raw_name.strip() and name.lower() != raw_name.strip().lower() else ""
        if c.numeric:
            parts = ([np.full(c.offset, M.SYSMISS)] if c.offset else []) + c.num_chunks
            vals = np.concatenate(parts) if parts else np.full(nrows, M.SYSMISS)
            c.num_chunks = []
            vtype = smallest_type_for(vals)
            if vtype == "float" and opts.asdouble:
                vtype = "double"
            elif vtype == "double" and not opts.asdouble:
                nm = vals[vals < M.SYSMISS]
                # large integers stay double; decimals become float (VERIFY)
                if not (nm.size and np.all(nm == np.trunc(nm))):
                    vtype = "float"
            var = Variable(name, vtype, vals)       # float: rounds to single precision
            del vals
        else:
            text = ([""] * c.offset if c.offset else []) + c.text
            c.text = []
            var = Variable(name, str_type_for(c.maxlen), text)
        var.label = label
        ds.vars.append(var)
    ds.changed = True
    return ds


# ---------------------------------------------------------------------------
# writing
# ---------------------------------------------------------------------------

@dataclass
class WriteOptions:
    delimiter: str = ","
    varnames: bool = True
    nolabel: bool = False
    datafmt: bool = False
    quote: bool = False          # quotes around all strings
    leading_zero: bool = False   # VERIFY: Stata writes .5 instead of 0.5
    never_quote: bool = False    # outsheet, noquote: raw text, even with the delimiter


def number_text(x: float, vtype: str, fmt: str | None = None, *, leading_zero: bool = False) -> str:
    """Text of a value, the same as export delimited writes."""
    if fmt and x < M.SYSMISS:
        from ..core.formats import format_value, plain_numbers
        with plain_numbers():
            return format_value(x, fmt, pad=False).strip()
    v = Variable("_", vtype, np.array([x], dtype=np.float64))
    return str(_number_cells(v, v.raw, leading_zero)[0])


def _number_cells(v: Variable, raw: np.ndarray, leading_zero: bool) -> np.ndarray:
    """Text of each numeric value (vector of str), without a Python loop."""
    dec = storage.decode(raw, v.vtype)
    miss = dec >= M.SYSMISS
    out = np.empty(len(dec), dtype=object)
    if v.vtype in ("byte", "int", "long"):
        txt = raw.astype(np.int64).astype(str)
    else:
        vals = raw if v.vtype == "float" else dec
        whole = ~miss & (dec == np.trunc(dec)) & (np.abs(dec) < 1e15)
        txt = np.where(miss, 0, vals).astype(str)
        if whole.any():
            txt = txt.astype(object)
            txt[whole] = dec[whole].astype(np.int64).astype(str)
            txt = txt.astype(str)
        if not leading_zero:
            m = np.char.startswith(txt, "0.")
            if m.any():
                txt[m] = np.char.replace(txt[m], "0.", ".", count=1)
            m = np.char.startswith(txt, "-0.")
            if m.any():
                txt[m] = np.char.replace(txt[m], "-0.", "-.", count=1)
    out[:] = txt
    if miss.any():
        out[miss] = [("" if M.missing_name(x) == "." else M.missing_name(x)) for x in dec[miss]]
    return out


def write_delimited(ds: Dataset, path: str | Path, names: list[str], rows: np.ndarray,
                    opts: WriteOptions | None = None) -> None:
    """Writes in blocks of lines, building each column at once."""
    opts = opts or WriteOptions()
    d = opts.delimiter
    vars_ = [ds.get(n) for n in names]
    special = (d, '"', "\n", "\r")

    def q(s: str) -> str:
        if opts.never_quote:
            return s
        if opts.quote or any(ch in s for ch in special):
            return '"' + s.replace('"', '""') + '"'
        return s

    rows = np.asarray(rows)
    with open(path, "w", encoding="utf-8", newline="") as f:
        if opts.varnames:
            f.write(d.join(v.name for v in vars_) + "\n")
        for start in range(0, len(rows), CHUNK_ROWS):
            idx = rows[start:start + CHUNK_ROWS]
            columns = []
            for v in vars_:
                part = v.raw[idx]
                if v.is_string:
                    columns.append([q(s) for s in part.tolist()])
                    continue
                if opts.datafmt:
                    from ..core.formats import format_value, plain_numbers
                    dec = storage.decode(part, v.vtype)
                    with plain_numbers():
                        cells = np.array([("" if x >= M.SYSMISS and M.missing_name(x) == "."
                                           else M.missing_name(x) if x >= M.SYSMISS
                                           else format_value(x, v.fmt, pad=False).strip()) for x in dec],
                                         dtype=object)
                else:
                    cells = _number_cells(v, part, opts.leading_zero)
                lab = ds.value_labels.get(v.value_label, {}) if v.value_label and not opts.nolabel else {}
                if lab:
                    dec = storage.decode(part, v.vtype)
                    for value, text in lab.items():
                        hit = dec == value
                        if hit.any():
                            cells[hit] = q(text)
                columns.append(cells.tolist())
            f.write("".join(d.join(r) + "\n" for r in zip(*columns)) if columns else "")

