@register("word", 2)
def _word(s: Value, n: Value) -> str:
    words = _s(s).split()
    n = _n(n)
    if M.is_missing(n):
        return ""
    k = int(n)
    if k > 0 and k <= len(words):
        return words[k - 1]
    if k < 0 and -k <= len(words):
        return words[k]
    return ""


@register("substr", 3)
def _substr(s: Value, n1: Value, n2: Value) -> str:
    s, n1, n2 = _s(s), _n(n1), _n(n2)
    if M.is_missing(n1):
        return ""
    L = len(s)
    start = int(n1)
    if start < 0:
        start = L + start + 1
    if start < 1 or start > L:
        return ""
    length = L - start + 1 if M.is_missing(n2) else int(n2)
    if length <= 0:
        return ""
    return s[start - 1:start - 1 + length]


@register("strpos", 2)
