    def _forvalues(self, spec: str, lines: list[LogicalLine], a: int, b: int) -> None:
        text = self.s.expand(spec)
        m = re.match(r"^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.+?)\s*$", text)
        if not m:
            raise StataError(198, "invalid syntax")
