    i = v[2].int_scalar()
    e = S.eq(i)
    if (e["X"] is None or e["X"].shape[1] == 0) and e["offset"] is None:
        # a constant-only equation gives a scalar ([M-5] moptimize(); compat 0408)
        a, z = S.indices(i)
        b = _b(v[1])
        if z - a == 1:
            return real(float(b[a]) + S.theta_shift.get(i, 0.0))
