        arr[0, k] = nm
    return MV(arr, "string")


# running Stata commands --------------------------------------------------

@lib("stata", 1, 3)
def _stata(eng, v, r):
    cmd = v[0].str_scalar()
    quiet = len(v) > 1 and v[1] is not None and v[1].real_scalar() != 0
    rc = _run_stata(eng, cmd, quiet)
    if rc:
        raise MataError(rc, "Stata returned error")    # VERIFY (3598?)
    return None


@lib("_stata", 1, 3)
def _stata_rc(eng, v, r):
    cmd = v[0].str_scalar()
    quiet = len(v) > 1 and v[1] is not None and v[1].real_scalar() != 0
    return real(float(_run_stata(eng, cmd, quiet)))


def _run_stata(eng, cmd: str, quiet: bool) -> int:
    s = eng.s
    out = s.output
    if quiet:
        out.quiet_depth += 1
    try:
        s.interp.execute(cmd)
        return 0
    except StataError as e:
        if not quiet:
            s.report_error(e)
        return e.rc
    finally:
        if quiet:
            out.quiet_depth -= 1

